window.allQuizData={
  njjzw:[
{"c":"经典急转弯","q":"什么东西越洗越脏？","a":"水。洗涤时污物进入水中，水越洗越脏。"},
{"c":"经典急转弯","q":"天气热起来，它里面的液柱就往上爬，读数也跟着变大。它是什么？","a":"温度计。天气越热，管内液体膨胀得越厉害，读数就升得越高。"},
{"c":"经典急转弯","q":"有风时它不动，无风时它自己动。它是什么？","a":"扇子。人拿着扇子扇风时扇面在动；有风时人往往不用扇。"},
{"c":"经典急转弯","q":"什么东西越剪越大？","a":"洞。剪掉材料，孔洞扩大。"},
{"c":"经典急转弯","q":"什么东西越老越年轻？","a":"照片。照片定格拍摄那一刻。"},
{"c":"经典急转弯","q":"什么东西越擦越小？","a":"橡皮擦。每擦一次磨掉一点。"},
{"c":"经典急转弯","q":"别人用得比你多，可它明明是你的。它是什么？","a":"名字。名字属于你，但别人叫你的名字，比你自己叫得还多。"},
{"c":"经典急转弯","q":"它只能增加，不能减少。它是什么？","a":"年龄。时间往前走，人的年龄只会增长，不会倒退。"},
{"c":"经典急转弯","q":"人一生气，它就容易变大，事后又慢慢消下去。它是什么？","a":"脾气。人一生气，脾气就上来，显得越来越大。"},
{"c":"经典急转弯","q":"什么东西越洗越小？","a":"肥皂。每次使用溶掉一层。"},
{"c":"经典急转弯","q":"什么东西越热越硬？","a":"鸡蛋。蛋白受热后凝固，蛋黄也会变硬。"},
{"c":"经典急转弯","q":"人人都说不想吃，可几乎人人都吃过。它是什么？","a":"吃亏。没人愿意吃亏，但生活中人人都难免吃一次亏。"},
{"c":"经典急转弯","q":"一只手有五个指头，一只脚有五个趾头。这些“头”是什么？","a":"手指和脚趾。它们都带“头”字，合起来正好十个。"},
{"c":"经典急转弯","q":"一个数字倒过来看，会比原来多一半。它是几？","a":"6。6倒过来是9，9比6多一半。"},
{"c":"经典急转弯","q":"梳头时，它用一排“牙齿”咬住头发，却从不咬人。它是什么？","a":"梳子。梳齿像牙齿，只用来梳理头发。"},
{"c":"经典急转弯","q":"看不见，摸不着，缺了它人几分钟都撑不住。它是什么？","a":"空气。空气无色无味，但人呼吸离不开它。"},
{"c":"经典急转弯","q":"你走，它也走；你停，它也停。它是什么？","a":"影子。影子跟着人和光源的位置变化，人停它也停。"},
{"c":"经典急转弯","q":"拍卖会上，年份久远的旧物常被高价追捧。它是什么？","a":"古董。年代越久，古董的收藏和研究价值通常越高。"},
{"c":"经典急转弯","q":"什么东西越翻越薄？","a":"日历。每翻一页少一张。"},
{"c":"经典急转弯","q":"被打破时，大家反而高兴。它是什么？","a":"纪录。体育比赛里打破纪录是好事，所以大家会高兴。"},
{"c":"经典急转弯","q":"小明家有三个孩子：老大叫大毛，老二叫二毛，老三叫什么？","a":"小明。题目开头已经说了，这是小明家。"},
{"c":"经典急转弯","q":"十根点燃的蜡烛，吹灭三根，第二天还剩几根？","a":"三根。吹灭的三根保留下来，其余七根会烧完。"},
{"c":"经典急转弯","q":"五个苹果分给两个人，怎样分最公平？","a":"榨成果汁。把五个苹果榨成汁再平分，两人得到的一样多。"},
{"c":"经典急转弯","q":"一斤棉花和一斤铁，哪个更重？","a":"一样重。两者都是一斤，重量相同，只是体积不同。"},
{"c":"经典急转弯","q":"一个人住十楼，下楼走楼梯，上楼却只坐电梯到七楼，再走三层。为什么？","a":"他够不到八楼按钮。个子矮，手只能按到七楼，只好再走楼梯。"},
{"c":"经典急转弯","q":"什么东西越写越短？","a":"粉笔。书写摩擦消耗粉笔。"},
{"c":"经典急转弯","q":"两个爸爸和两个儿子去吃饭，为什么只付了三份钱？","a":"他们是爷爷、爸爸和儿子。爷爷是爸爸的爸爸，爸爸是儿子的爸爸，三个人正好是两个爸爸、两个儿子。"},
{"c":"经典急转弯","q":"一辆车从甲地到乙地用了1小时，返回却用了2小时，为什么？","a":"去时下坡，回来上坡。下坡快、上坡慢，路程一样但用时不同。"},
{"c":"经典急转弯","q":"上面有山有水，却没有一块石头、一滴水。它是什么？","a":"地图。地图用符号画出山川河流，纸面上只有线条和标记。"},
{"c":"经典急转弯","q":"它有翅膀，却不会自己飞，要靠风才能上天。它是什么？","a":"风筝。风筝有骨架和翅膀，但要借风力才能飞起来。"},
{"c":"经典急转弯","q":"写好了信，把它装进去，封口一粘就寄走。它是什么？","a":"信封。信封有封口，但没有嘴巴，不会说话。"},
{"c":"经典急转弯","q":"出门前，它插进锁孔一转，门就开了。它是什么？","a":"钥匙。钥匙的齿用来开锁，不会咬人。"},
{"c":"经典急转弯","q":"买东西时，扫一下它，黑白方块就变成信息。它是什么？","a":"二维码。二维码由黑白模块组成，用来存信息，不是棋盘。"},
{"c":"经典急转弯","q":"衣服脏了，把它放进去，转几圈就干净。它是什么？","a":"洗衣机。滚筒转动，水和洗涤剂把污渍从衣服上带走。"},
{"c":"经典急转弯","q":"现在人人出门都带它，能打电话、能扫码，还能看视频。它是什么？","a":"手机。手机屏幕用来显示文字、图片和视频，不是画布。"},
{"c":"经典急转弯","q":"进医院或坐公交时，它会罩住口鼻。它是什么？","a":"口罩。口罩有罩口，但只用来遮挡，不吃饭。"},
{"c":"经典急转弯","q":"一个人从飞机上跳下来，却没有摔伤。为什么？","a":"飞机停在地上。他从停在地面的飞机上跳下，离地很近。"},
{"c":"经典急转弯","q":"你喊一声，它跟着喊一声；你不喊，它也不出声。它是什么？","a":"回声。声音碰到障碍物反射回来，就形成回声。"},
{"c":"经典急转弯","q":"寄信时贴在右上角，边缘有一排小齿孔。它是什么？","a":"邮票。邮票边缘有齿孔，方便撕开，不是牙齿。"},
{"c":"经典急转弯","q":"打字时手放在上面，敲一敲就出现文字。它是什么？","a":"键盘。键盘按键用来输入文字和命令，不发出琴声。"},
{"c":"经典急转弯","q":"老式账房里，拨动珠子就能算账。它是什么？","a":"算盘。算盘的珠子用来计数，不是手串。"},
{"c":"经典急转弯","q":"转一转，里面出现许多彩色花纹，像万花盛开。它是什么？","a":"万花筒。万花筒用镜片反射出花纹，不是真花。"},
{"c":"经典急转弯","q":"什么东西越长越香？","a":"酒。酒在陈放中发生酯化，香气更浓。"},
{"c":"经典急转弯","q":"登山迷路时，看它就能找到方向。它是什么？","a":"指南针。指南针的针用来指示方向，不是缝衣针。"},
{"c":"经典急转弯","q":"路口上，红黄绿三盏灯轮流亮，像三只眼睛。它是什么？","a":"红绿灯。红黄绿三盏灯像三只眼睛，只用来指挥交通。"},
{"c":"经典急转弯","q":"过马路时，地上有一排黑白条纹。它是什么？","a":"斑马线。斑马线是黑白相间的交通标线，不是动物。"},
{"c":"经典急转弯","q":"每天早上送上门，上面有日期和新闻。它是什么？","a":"报纸。报纸每天出版，上面有日期和文字，但不是日历。"},
{"c":"经典急转弯","q":"看不清字时，戴上它，两片镜片就像两只眼睛。它是什么？","a":"眼镜。眼镜的两片镜片像两只眼睛，只用来矫正视力。"},
{"c":"经典急转弯","q":"什么东西越小声越清晰？","a":"悄悄话。贴近耳朵，减少干扰。"},
{"c":"经典急转弯","q":"公司里有人名叫“书”，却整天处理文件、安排会议，他不是一本书。他是什么？","a":"秘书。秘书是职务名称，负责文书、会务和日常协调。"},
{"c":"经典急转弯","q":"远远看去像一匹白布挂在悬崖，走近却剪不断。它是什么？","a":"瀑布。瀑布是水流从高处落下，远看像白布，却没有布的纤维。"},
{"c":"经典急转弯","q":"它像花一样绽放，却不能摘，越碰越容易熄灭。它是什么？","a":"火花。火花是燃烧中飞出的细小颗粒，碰到手或风就会熄灭。"},
{"c":"经典急转弯","q":"人人都有，却不能煮来吃；有人还把它叫作“蛋”。它是什么？","a":"脸蛋。脸蛋是脸面的俗称，名字里带“蛋”，和禽蛋无关。"},
{"c":"经典急转弯","q":"天上有一条河，里面有许多星星，却没有一滴水。它是什么？","a":"银河。银河是大量恒星和星云组成的密集带，没有液态水。"},
{"c":"经典急转弯","q":"有一个海，装的是想法和记忆，看不见水。它是什么？","a":"脑海。脑海是思维活动的比喻，并没有真实的海水。"},
{"c":"经典急转弯","q":"传说中有一座桥，由喜鹊搭成，人却走不了。它是什么？","a":"鹊桥。鹊桥是牛郎织女传说中喜鹊搭成的相会之桥。"},
{"c":"经典急转弯","q":"运动场上有一种饼，越用力扔越远，却咬不动。它是什么？","a":"铁饼。铁饼是田径投掷器材，用金属和圆盘做成。"},
{"c":"经典急转弯","q":"有一种球，全世界的人都在上面，却没人拍得动。它是什么？","a":"地球。地球是行星，体积和质量都远大于人能拍动的球。"},
{"c":"经典急转弯","q":"它一响，运动员就往前跑，却打不倒人。它是什么？","a":"发令枪。发令枪只发出起跑信号，不装弹头。"},
{"c":"经典急转弯","q":"它像杯子，装的是荣誉，不能用来喝水。它是什么？","a":"奖杯。奖杯是比赛奖品，用来象征成绩和荣誉。"},
{"c":"经典急转弯","q":"它像手掌，却长满尖刺，拍一下会扎手。它是什么？","a":"仙人掌。仙人掌的肉质茎上长着刺，用来减少水分蒸发。"},
{"c":"经典急转弯","q":"它每天叫你起床，却不是靠敲响来提醒。它是什么？","a":"闹钟。闹钟靠铃锤、蜂鸣器或电子音报时。"},
{"c":"经典急转弯","q":"它从窗户照进来，看得见亮，却抓不住。它是什么？","a":"光线。光线是光的传播路径，本身没有实体，抓不住。"},
{"c":"经典急转弯","q":"它有头，没有脚，却能在水里自由来去。它是什么？","a":"鱼。鱼靠鳍和身体的摆动在水里游动。"},
{"c":"经典急转弯","q":"它有嘴，有肚子，还有把手，却不会说话。它是什么？","a":"茶壶。茶壶的嘴用来倒水，肚子用来盛水。"},
{"c":"经典急转弯","q":"它有一只眼，却看不见；有一条腿，却不走路。它是什么？","a":"针。针眼是穿线的小孔，针身细长，不会走路。"},
{"c":"经典急转弯","q":"它有耳朵，却听不见；有肚子，却能装水。它是什么？","a":"杯子。杯耳是把手，杯肚用来盛水。"},
{"c":"经典急转弯","q":"它外面有皮，里面却没有肉，过节时挂在门前。它是什么？","a":"灯笼。灯笼外面糊纸或纱，里面点灯，并没有肉。"},
{"c":"经典急转弯","q":"它有四条腿，却从来不走路。它是什么？","a":"桌子。桌腿只用来支撑桌面。"},
{"c":"经典急转弯","q":"它有嘴，却不会说话；有肚子，却能装酒。它是什么？","a":"葫芦。葫芦的嘴是开口，肚子中空，可以盛东西。"},
{"c":"经典急转弯","q":"它有一个头，却没有脑子；一擦就着火。它是什么？","a":"火柴。火柴头是发火端，擦划后引燃。"},
{"c":"经典急转弯","q":"它有脸，却没有嘴；有手，却不会拿东西。它是什么？","a":"钟。钟面像脸，指针像手，用来显示时间。"},
{"c":"经典急转弯","q":"它有五个手指，却没有手；冬天戴它保暖。它是什么？","a":"手套。手套做成手的形状，套在手上。"},
{"c":"经典急转弯","q":"它越咽越多，永远用不完。它是什么？","a":"口水。唾液腺不断分泌唾液，咽下后还会继续产生。"},
{"c":"经典急转弯","q":"和尚念经时敲的那条“鱼”，不会游水。它是什么？","a":"木鱼。木鱼是木制的打击乐器，用来敲击。"},
{"c":"经典急转弯","q":"它是鸟，却飞不起来，跑起来很快。它是什么？","a":"鸵鸟。鸵鸟体型大、翅膀退化，不能飞行，但奔跑很快。"},
{"c":"经典急转弯","q":"头部像马、尾巴像象鼻的小鱼，是什么？","a":"海马。海马是小型鱼类，头部像马。"},
{"c":"经典急转弯","q":"背着螺旋壳、爬得很慢的软体动物，是什么？","a":"蜗牛。蜗牛是软体动物，背着螺旋形的壳。"},
{"c":"经典急转弯","q":"常在墙上爬、专吃蚊虫的小蜥蜴，是什么？","a":"壁虎。壁虎是蜥蜴，常在墙壁上捕食昆虫。"},
{"c":"经典急转弯","q":"史前时代的大型爬行动物，已经灭绝，是什么？","a":"恐龙。恐龙是史前爬行动物，不会喷火。"},
{"c":"经典急转弯","q":"黑白毛色、爱吃竹子的熊科动物，是什么？","a":"熊猫。熊猫是熊科动物，主食竹子。"},
{"c":"经典急转弯","q":"面包夹香肠的食物，名字里有个“狗”，是什么？","a":"热狗。热狗是面包夹香肠的食物。"},
{"c":"经典急转弯","q":"青蛙的俗称，名字里带“鸡”，是什么？","a":"田鸡。田鸡是青蛙的俗称，没有羽毛。"},
{"c":"经典急转弯","q":"北京名菜，皮脆肉嫩，名字里带“鸭”，是什么？","a":"烤鸭。烤鸭是烤熟的鸭子，已经不能游水。"},
{"c":"经典急转弯","q":"它名字里有个“珠”，圆润光亮，却藏在贝壳里。它是什么？","a":"珍珠。珍珠是贝类分泌形成的圆珠，常用来做首饰。"},
{"c":"经典急转弯","q":"月宫传说里捣药的兔子，是什么？","a":"玉兔。玉兔是月宫传说中的兔子。"},
{"c":"经典急转弯","q":"屏幕上吃方块会变长的游戏角色，是什么？","a":"贪吃蛇。贪吃蛇是电子游戏中的角色，靠吃方块变长。"},
{"c":"经典急转弯","q":"让人犯困的比喻说法，名字里带“虫”，是什么？","a":"瞌睡虫。瞌睡虫是让人想睡觉的比喻说法。"},
{"c":"经典急转弯","q":"母兽肚子上有育儿袋的哺乳动物，是什么？","a":"袋鼠。袋鼠是哺乳动物，母袋鼠腹部有育儿袋。"},
{"c":"经典急转弯","q":"表示假设关系的连词，名字里带“果”，是什么？","a":"如果。如果是一个连词，表示假设关系。"},
{"c":"经典急转弯","q":"春天开在桃树上、凋谢后结桃的花，是什么？","a":"桃花。桃花是桃树的花，凋谢后才结桃。"},
{"c":"经典急转弯","q":"它和梨同音，却不能吃，是法国的首都。它是什么？","a":"巴黎。巴黎是法国首都，和水果梨只是同音。"},
{"c":"经典急转弯","q":"铁扇公主手里的扇子，一扇就有风，是什么？","a":"芭蕉扇。芭蕉扇是用芭蕉叶或仿叶做的扇子。"},
{"c":"经典急转弯","q":"它和柚同音，却不能吃，人人都在追求。它是什么？","a":"自由。自由是权利和状态，和柚子只是同音。"},
{"c":"经典急转弯","q":"它和茶同音，却不能喝，专门维护治安。它是什么？","a":"警察。警察是职业，和茶水只是同音。"},
{"c":"经典急转弯","q":"滑冰鞋底部的金属刃，名字里带“刀”，是什么？","a":"冰刀。冰刀是滑冰鞋底部的金属刃。"},
{"c":"经典急转弯","q":"靠向后喷气飞上天的航天运载器，是什么？","a":"火箭。火箭是航天运载器，靠向后喷气反冲飞行。"},
{"c":"经典急转弯","q":"事情过后才发表意见的成语，是什么？","a":"马后炮。马后炮比喻事后才发表评论或办法。"},
{"c":"经典急转弯","q":"用电磁波探测飞机和船只的设备，是什么？","a":"雷达。雷达用电磁波探测物体位置和速度。"},
{"c":"经典急转弯","q":"用电磁波传递信息的技术，是什么？","a":"无线电。无线电利用电磁波传递信息，看不见也摸不着。"},
{"c":"经典急转弯","q":"形容人气派、有声势的词，是什么？","a":"威风。威风形容有气派、有声势的样子。"},
{"c":"经典急转弯","q":"许多流星从夜空同一区域划过的现象，是什么？","a":"流星雨。流星雨是许多流星从夜空同一区域划过的天文现象。"},
{"c":"经典急转弯","q":"比喻不值得计较、转眼即逝的事，是什么？","a":"浮云。浮云常用来比喻不值得计较、转眼即逝的事。"},
{"c":"经典急转弯","q":"两个人你一句我一句地说话，是什么？","a":"聊天。聊天是人们互相说话交流。"},
{"c":"经典急转弯","q":"用扫帚清理地面垃圾的动作，是什么？","a":"扫地。扫地是清理地面垃圾和灰尘的动作。"},
{"c":"经典急转弯","q":"受热或撞击会爆炸的物品，是什么？","a":"炸药。炸药是爆炸物，受热或撞击可能爆炸。"},
{"c":"经典急转弯","q":"表面粘有磨料、用来打磨木材的纸，是什么？","a":"砂纸。砂纸表面粘有磨料，用来打磨木材和金属。"},
{"c":"经典急转弯","q":"电工用来检测电路是否带电的工具，是什么？","a":"电笔。电笔是测电工具，笔尖接触电路时能显示带电状态。"},
{"c":"经典急转弯","q":"写在灯笼上供人猜的谜语，是什么？","a":"灯谜。灯谜是写在灯笼上的谜语，供人猜射。"},
{"c":"经典急转弯","q":"利用空气阻力让人或物缓慢下降的伞，是什么？","a":"降落伞。降落伞利用空气阻力减缓下降速度。"},
{"c":"经典急转弯","q":"安装在管道上、计量用水量的表，是什么？","a":"水表。水表用来计量用水量。"},
{"c":"经典急转弯","q":"放在鞋内吸汗缓冲的垫子，是什么？","a":"鞋垫。鞋垫放在鞋内，用来吸汗、缓冲。"},
{"c":"经典急转弯","q":"拧在螺栓上固定零件的螺母，是什么？","a":"螺丝帽。螺丝帽是螺母，用来固定螺栓。"},
{"c":"经典急转弯","q":"挂衣服用的架子，是什么？","a":"衣架。衣架是挂衣服的架子。"},
{"c":"经典急转弯","q":"缝在裤子上装东西的口袋，是什么？","a":"裤兜。裤兜是裤子上的口袋。"},
{"c":"经典急转弯","q":"长在海里的大型褐藻，常用来做菜，是什么？","a":"海带。海带是大型海藻，常用来做菜。"},
{"c":"经典急转弯","q":"用面粉发酵后烘烤成的食品，是什么？","a":"面包。面包是烘烤制成的面食。"},
{"c":"经典急转弯","q":"长在脖子上、装着大脑的部位，是什么？","a":"脑袋。脑袋是头部的俗称，里面装着大脑。"},
{"c":"经典急转弯","q":"内部装扬声器、用来放声音的设备，是什么？","a":"音箱。音箱是发声设备，内部装有扬声器。"},
{"c":"经典急转弯","q":"旧时店铺里管事的店主，叫什么？","a":"掌柜。掌柜是旧时对店主的称呼。"},
{"c":"经典急转弯","q":"河水流动时底部承载水流的凹地，是什么？","a":"河床。河床是河流底部承载水流的凹地。"},
{"c":"经典急转弯","q":"西方占卜用的卡牌，叫什么？","a":"塔罗牌。塔罗牌是占卜用的卡牌。"},
{"c":"经典急转弯","q":"光线折射在海面上形成的幻景，是什么？","a":"海市蜃楼。海市蜃楼是光线折射形成的幻景。"},
{"c":"经典急转弯","q":"蜜蜂用蜡筑成的六边形巢，是什么？","a":"蜂房。蜂房是蜜蜂用蜡筑成的巢。"},
{"c":"经典急转弯","q":"因为喜欢一个人，连他屋上的乌鸦也喜欢的成语，是什么？","a":"爱屋及乌。爱屋及乌指喜爱一个人，连带着喜爱与他有关的事物。"},
{"c":"经典急转弯","q":"形容女子身材修长、姿态优美的成语，是什么？","a":"亭亭玉立。亭亭玉立形容女子身材修长、姿态优美。"},
{"c":"经典急转弯","q":"放在桌面上照明的灯，是什么？","a":"台灯。台灯是放在桌面上的照明灯具。"},
{"c":"经典急转弯","q":"伪装起来的坑或圈套，踩进去会掉，是什么？","a":"陷阱。陷阱是伪装起来的坑或圈套。"},
{"c":"经典急转弯","q":"储存电能、给电器供电的装置，是什么？","a":"电池。电池是储存电能的装置。"},
{"c":"经典急转弯","q":"常用来指社会或武林圈子的词，是什么？","a":"江湖。江湖常用来指社会或武林圈子。"},
{"c":"经典急转弯","q":"糯米的别称，名字里带“江”，是什么？","a":"江米。江米是糯米的别称。"},
{"c":"经典急转弯","q":"电流通过的路径，是什么？","a":"电路。电路是电流通过的路径。"},
{"c":"经典急转弯","q":"车辆密集、行驶缓慢或停滞的现象，是什么？","a":"堵车。堵车是车辆密集、行驶缓慢或停滞。"},
{"c":"经典急转弯","q":"棋盘上走直线、没有轮子的棋子，是什么？","a":"象棋中的车。象棋的车是棋子，走直线，不吃子时不能转弯。"},
{"c":"经典急转弯","q":"在太空航行的航天器，是什么？","a":"宇宙飞船。宇宙飞船是航天器，在太空中航行。"},
{"c":"经典急转弯","q":"航天器的统称，在太空飞行，是什么？","a":"飞船。飞船是航天器的统称，在太空飞行。"},
{"c":"经典急转弯","q":"用纸折成、不会载人的玩具飞机，是什么？","a":"纸飞机。纸飞机是折纸做成的玩具，不会载人。"},
{"c":"经典急转弯","q":"没有动力、靠气流滑翔的飞机，是什么？","a":"滑翔机。滑翔机没有动力，靠上升气流和重力滑翔。"},
{"c":"经典急转弯","q":"靠电子元件工作、能上网打字的机器，是什么？","a":"电脑。电脑靠电子元件工作，不需要机械转动。"},
{"c":"经典急转弯","q":"给汽车提供动力、运转时会发热的机器，是什么？","a":"发动机。发动机靠燃料燃烧或电力驱动，运转时产生热量。"},
{"c":"经典急转弯","q":"靠制冷剂把箱内热量搬到箱外、用来冷藏食物的机器，是什么？","a":"冰箱。冰箱靠制冷剂把箱内热量搬到箱外。"},
{"c":"经典急转弯","q":"跨越道路、下面没有水的桥，是什么？","a":"立交桥。立交桥跨越道路，用来疏导交通。"},
{"c":"经典急转弯","q":"伤心时从眼里流出、含盐的水，是什么？","a":"泪水。泪水含盐和代谢物，不适合饮用。"},
{"c":"经典急转弯","q":"形容大面积燃烧的火焰的词，是什么？","a":"火海。火海形容大面积燃烧的火焰。"},
{"c":"经典急转弯","q":"黄豆磨成的饮品，名字里带“江”，是什么？","a":"豆浆。豆浆是黄豆磨成的饮品。"},
{"c":"经典急转弯","q":"大型汉语词典，名字里带“海”，是什么？","a":"辞海。辞海是大型汉语词典。"},
{"c":"经典急转弯","q":"比喻书多得像山一样的词，是什么？","a":"书山。书山比喻书多得像山一样。"},
{"c":"经典急转弯","q":"思考问题的线索和方向，是什么？","a":"思路。思路是思考问题的线索和方向。"},
{"c":"经典急转弯","q":"说话或唱歌的声音大小，是什么？","a":"嗓门。嗓门指说话或唱歌的声音大小。"},
{"c":"经典急转弯","q":"同学的古称，名字里带“窗”，是什么？","a":"同窗。同窗是同学的古称。"},
{"c":"经典急转弯","q":"溶洞里碳酸钙沉积形成的石柱，是什么？","a":"钟乳石。钟乳石是溶洞中碳酸钙沉积形成的石柱。"},
{"c":"经典急转弯","q":"用行列排列数据的表，是什么？","a":"表格。表格用行列排列数据。"},
{"c":"经典急转弯","q":"鞋面部分，不包括鞋底，是什么？","a":"鞋帮。鞋帮是鞋面部分，不包括鞋底。"},
{"c":"经典急转弯","q":"帽子前部或周围伸出的边，是什么？","a":"帽檐。帽檐是帽子前部或周围伸出的边。"},
{"c":"经典急转弯","q":"无袖上衣，夏天常穿，是什么？","a":"背心。背心是无袖上衣。"},
{"c":"经典急转弯","q":"心脏接收血液的腔室，是什么？","a":"心房。心房是心脏接收血液的腔室。"},
{"c":"经典急转弯","q":"只用一个字，就能让人想到最值钱的东西。是什么字？","a":"金。金字本义就是黄金。"},
{"c":"经典急转弯","q":"只用一个字，就能让人想到最冷的东西。是什么字？","a":"冰。冰是水冻结成的固体。"},
{"c":"经典急转弯","q":"只用一个字，就能让人想到最热的东西。是什么字？","a":"火。火是燃烧产生的光和热。"},
{"c":"经典急转弯","q":"只用一个字，就能让人想到最重的东西。是什么字？","a":"山。山字像隆起的山峰，常用来形容分量重。"},
{"c":"经典急转弯","q":"只用一个字，就能让人想到最轻的东西。是什么字？","a":"毛。毛字本义是毛发，轻而细小。"},
{"c":"经典急转弯","q":"只用一个字，就能让人想到最慢的东西。是什么字？","a":"龟。龟行动缓慢，常用来形容慢。"},
{"c":"经典急转弯","q":"有一个字，你一念它，就等于承认自己念错。是什么字？","a":"错。念“错”字时，说的正是“错”。"},
{"c":"经典急转弯","q":"哪个字加一横，就变成“天”？","a":"大。大字上面加一横，就是天。"},
{"c":"经典急转弯","q":"哪个字正着写、倒着写都一样？","a":"回。回字由内外两个口组成，倒过来也一样。"},
{"c":"经典急转弯","q":"哪个字加两笔，就变成“田”？","a":"口。口字中间加一横一竖，成为田。"},
{"c":"经典急转弯","q":"只用一个字，就能让人想到霜冻的冷。是什么字？","a":"霜。霜是空气中水汽在低温物体上凝华成的白色冰晶。"},
{"c":"经典急转弯","q":"只用一个字，就能让人想到双重火焰的热。是什么字？","a":"炎。炎由两个火字叠成，表示热或炎症。"},
{"c":"经典急转弯","q":"什么字一出现，就让人想到沉重的青铜器？","a":"鼎。鼎是古代青铜器，形体厚重。"},
{"c":"经典急转弯","q":"什么字一出现，就让人想到轻飘飘的羽毛？","a":"羽。羽字本义是鸟的羽毛。"},
{"c":"经典急转弯","q":"什么字本身就有缓慢、不急的意思？","a":"缓。缓表示慢、不急。"},
{"c":"经典急转弯","q":"哪个字加一笔，就变成“本”？","a":"木。木字下面加一横，就是本。"},
{"c":"经典急转弯","q":"什么动物能站着睡觉，腿部有锁定结构？","a":"马。马能站着睡觉，腿部关节可以锁定。"},
{"c":"经典急转弯","q":"什么动物一生都穿着黑白条纹的衣服？","a":"斑马。斑马皮毛黑白相间。"},
{"c":"经典急转弯","q":"什么动物和狗同属犬科，常被说长得像狗？","a":"狼。狼和狗同属犬科，外形相近。"},
{"c":"经典急转弯","q":"什么动物没有脚，却靠腹部鳞片和肌肉起伏行走？","a":"蛇。蛇靠腹部鳞片和肌肉收缩向前移动。"},
{"c":"经典急转弯","q":"什么动物没有嘴，却能用腹部鼓膜发出响亮的叫声？","a":"蝉。蝉靠腹部鼓膜振动发声。"},
{"c":"经典急转弯","q":"什么植物一碰，叶片就会合拢低头？","a":"含羞草。含羞草叶片受触碰会闭合。"},
{"c":"经典急转弯","q":"什么植物空心有节，常长成一片竹林？","a":"竹子。竹子茎中空有节，成片生长。"},
{"c":"经典急转弯","q":"什么东西长在树上是绿的，落在地上会变黄？","a":"树叶。叶绿素分解后，叶片变黄。"},
{"c":"经典急转弯","q":"什么东西避光生长时是白的，见光后会变绿？","a":"豆芽。豆芽避光时白嫩，见光后叶绿素增加变绿。"},
{"c":"经典急转弯","q":"什么东西煮之前是硬的，煮熟后会变软？","a":"面条。面条的淀粉吸水糊化后变软。"},
{"c":"经典急转弯","q":"什么东西生的时候很小，受热后会膨胀变大？","a":"爆米花。玉米粒受热膨胀，变成爆米花。"},
{"c":"经典急转弯","q":"什么东西点燃后越烧越短，最后只剩一摊蜡？","a":"蜡烛。蜡烛燃烧时蜡不断消耗。"},
{"c":"经典急转弯","q":"什么东西常温是固体，遇热会融化，常做甜食？","a":"巧克力。巧克力常温是固体，受热融化。"},
{"c":"经典急转弯","q":"什么东西越削越短，却能写字？","a":"铅笔。铅笔削去外皮和笔芯后变短。"},
{"c":"经典急转弯","q":"什么东西湿的时候能写字，干的时候不能写？","a":"毛笔。毛笔蘸墨后才能书写。"},
{"c":"经典急转弯","q":"什么东西干的时候能吃，湿的时候不能吃？","a":"饼干。饼干吸水后变软烂。"},
{"c":"经典急转弯","q":"什么东西熟的能吃，生的不能吃？","a":"米饭。稻米生吃难消化，煮熟后才能吃。"},
{"c":"经典急转弯","q":"什么东西打开之前是长的，打开之后是圆的？","a":"雨伞。雨伞收起是柱状，打开是圆形。"},
{"c":"经典急转弯","q":"什么东西用之前是满的，用之后是空的？","a":"牙膏。牙膏挤出后变空。"},
{"c":"经典急转弯","q":"什么东西用之前是空的，用之后是满的？","a":"垃圾桶。垃圾桶用完时装满垃圾。"},
{"c":"经典急转弯","q":"什么东西买来是满的，用完是空的？","a":"洗发水。洗发水用完后瓶子变空。"},
{"c":"经典急转弯","q":"什么东西买来是空的，用完是满的？","a":"储蓄罐。储蓄罐投满硬币。"},
{"c":"逻辑陷阱","q":"一个人空肚子能吃几个鸡蛋？","a":"一个。吃完一个就不是空肚子。"},
{"c":"逻辑陷阱","q":"你能用左手画圆右手画方吗？","a":"可以。先画一个再画另一个，不必同时。"},
{"c":"逻辑陷阱","q":"一本本写下去，页数越来越多，是什么书？","a":"日记。日记一页页写下去，越写越厚。"},
{"c":"逻辑陷阱","q":"什么球不用手拍，用脚踢？","a":"足球。足球主要用脚踢。"},
{"c":"逻辑陷阱","q":"雪地里滚一个球，越滚越大，是什么球？","a":"雪球。雪球在雪地上滚动，会粘上更多雪，越滚越大。"},
{"c":"逻辑陷阱","q":"小明从1楼到3楼用了2分钟，照这样的速度，他从1楼到6楼要用几分钟？","a":"5分钟。1楼到3楼走2层楼梯，每层1分钟；1楼到6楼走5层楼梯，需要5分钟。"},
{"c":"逻辑陷阱","q":"什么东西越学越多，越用越活？","a":"知识。学习和实践让知识增加。"},
{"c":"逻辑陷阱","q":"什么东西每个人都拥有，却总有人觉得不够用？","a":"时间。时间对每个人一样多，但总有人觉得不够。"}
  ],
  zimi:[
{"c":"打一字","q":"一口咬掉牛尾巴","a":"告。「牛」下边的一竖像尾巴，换成「口」就是「告」。"},
{"c":"打一字","q":"一口吃掉多半截","a":"名。「多」咬掉一半剩「夕」，加「口」成「名」。"},
{"c":"打一字","q":"一箭穿心","a":"必。一撇穿过「心」字，正像一箭穿心，成「必」。"},
{"c":"打一字","q":"七十二小时","a":"晶。七十二小时是三天，三个「日」叠成「晶」。"},
{"c":"打一字","q":"一家十一口","a":"吉。「十」「一」加「口」，合起来是「吉」。"},
{"c":"打一字","q":"一人在内","a":"肉。「内」字里加个「人」，就是「肉」。"},
{"c":"打一字","q":"一斗米","a":"料。「斗」加「米」，合成「料」。"},
{"c":"打一字","q":"一月一日非今天","a":"明。「日」加「月」是「明」，说的不是今天。"},
{"c":"打一字","q":"需要一半留下一半","a":"雷。「需」取「雨」、「留」取「田」，合为「雷」。"},
{"c":"打一字","q":"一只黑狗不叫不吼","a":"默。「黑」加「犬」是「默」，不叫不吼正合字义。"},
{"c":"打一字","q":"一边绿一边红一边喜雨一边喜风","a":"秋。「禾」喜雨、「火」喜风，左绿右红合成「秋」。"},
{"c":"打一字","q":"七人头上长了草","a":"花。「七」「人」头上加草字头，就是「花」。"},
{"c":"打一字","q":"九十九","a":"白。「百」减去最上面的一，正好剩「白」。"},
{"c":"打一字","q":"人不在其位","a":"立。「位」字去掉单人旁，剩「立」。"},
{"c":"打一字","q":"人有他则变大","a":"一。「人」字加上一横，就变成「大」。"},
{"c":"打一字","q":"刀出鞘","a":"力。「刀」的撇尖出头，写成「力」。"},
{"c":"打一字","q":"十个哥哥","a":"克。「十」个「兄」合起来，是「克」。"},
{"c":"打一字","q":"十二点","a":"斗。「十」「二」加两点，是「斗」。"},
{"c":"打一字","q":"十张口一颗心","a":"思。「十」「口」底下放「心」，合为「思」。"},
{"c":"打一字","q":"又进村里","a":"树。「又」放进「村」中，组成「树」。"},
{"c":"打一字","q":"三水相连","a":"淼。三个「水」叠在一起就是「淼」。"},
{"c":"打一字","q":"上下合","a":"卡。「上」「下」接起来，正是「卡」。"},
{"c":"打一字","q":"千里挑一百里挑一","a":"伯。「千」去一为「亻」，「百」去一为「白」，合为「伯」。"},
{"c":"打一字","q":"大丈夫不得出头","a":"天。「夫」字头顶不出头，便成「天」。"},
{"c":"打一字","q":"大雨下在横山上","a":"雪。「雨」压在横写的「山」（彐）上，是「雪」。"},
{"c":"打一字","q":"小姑娘","a":"妙。「少」「女」合起来就是「妙」。"},
{"c":"打一字","q":"山上还有山","a":"出。两座「山」叠起来是「出」。"},
{"c":"打一字","q":"不要讲话","a":"吻。「勿」加「口」是「吻」，正好是「不讲话」。"},
{"c":"打一字","q":"太阳王","a":"旺。「日」（太阳）加「王」，是「旺」。"},
{"c":"打一字","q":"夫人何处去","a":"二。「夫」字里的「人」走了，只剩「二」。"},
{"c":"打一字","q":"水上工程","a":"汞。「水」上做「工」，合成「汞」。"},
{"c":"打一字","q":"水落石出","a":"泵。「水」落在下、「石」露在上，合为「泵」。"},
{"c":"打一字","q":"手提包","a":"抱。「提手旁」加「包」，就是「抱」；用手把东西包住，正是抱。"},
{"c":"打一字","q":"日复一日","a":"昌。两个「日」上下相叠，日复一日，就是「昌」。"},
{"c":"打一字","q":"月落鸟啼","a":"鹃。「月」落在「口」上，再加「鸟」，合成「鹃」。"},
{"c":"打一字","q":"文武双全","a":"斌。「文」与「武」合在一起，就是「斌」。"},
{"c":"打一字","q":"上面小，下面大，打一字。","a":"尖。“小”在上、“大”在下，合起来就是“尖”。"},
{"c":"打一字","q":"半青半紫","a":"素。取「青」的上半和「紫」的下半「糸」，合成「素」。"},
{"c":"打一字","q":"半推半就","a":"掠。「推」取提手旁，「就」取「京」，合起来是「掠」。"},
{"c":"打一字","q":"半真半假","a":"值。「真」取上半，「假」取人旁，合成「值」。"},
{"c":"打一字","q":"古时候的月亮","a":"胡。「古」加「月」，就是「胡」。"},
{"c":"打一字","q":"左看二十日右看三十天","a":"朝。「朝」字拆开有「十」「日」「十」「月」，左右都成日子。"},
{"c":"打一字","q":"石头成堆","a":"磊。三个「石」叠在一起，就是石头成堆的「磊」。"},
{"c":"打一字","q":"失去凡心","a":"几。「凡」去掉中间一点，剩下「几」。"},
{"c":"打一字","q":"四个晚上","a":"罗。「四」加「夕」，夕是晚上，合成「罗」。"},
{"c":"打一字","q":"四方来合作贡献大一点","a":"器。四个「口」加「大」再加一点，合成「器」。"},
{"c":"打一字","q":"用心就懂","a":"董。「懂」去掉竖心旁，就是「董」。"},
{"c":"打一字","q":"正月无初一","a":"肯。「正」去掉一横成「止」，加「月」，就是「肯」。"},
{"c":"打一字","q":"田中","a":"十。「田」字中间的一竖一横，正是「十」。"},
{"c":"打一字","q":"目字加两点","a":"贺。「加」加「贝」，贝像「目」加两点，合成「贺」。"},
{"c":"打一字","q":"禾中长草","a":"菌。「禾」上加草字头，外面再加「囗」，就是「菌」。"},
{"c":"打一字","q":"半耕半读","a":"讲。「耕」取右边的「井」，「读」取言字旁，合成「讲」。"},
{"c":"打一字","q":"有人偷了一头牛","a":"牵。「牛」上面加「冖」，再加「大」，像人牵牛，就是「牵」。"},
{"c":"打一字","q":"有口难言","a":"哑。有「口」旁却说不出话，就是「哑」。"},
{"c":"打一字","q":"有目共睹","a":"者。「睹」去掉目字旁，剩下「者」。"},
{"c":"打一字","q":"旭日不出","a":"九。「旭」去掉「日」，剩下「九」。"},
{"c":"打一字","q":"池里不见水地里不见泥","a":"也。「池」去掉三点水，「地」去掉提土旁，都是「也」。"},
{"c":"打一字","q":"白字加七，打一字。","a":"皂。“白”下加“七”，就是“皂”。"},
{"c":"打一字","q":"自己话","a":"语。「吾」是自己的意思，加言字旁，就是「语」。"},
{"c":"打一字","q":"西瓜里有子","a":"孤。「瓜」加「子」，就是「孤」。"},
{"c":"打一字","q":"两人十四心","a":"德。双人旁、十、四、心合在一起，就是「德」。"},
{"c":"打一字","q":"两狗谈天","a":"狱。两个「犬」加「言」，像两只狗在说话，就是「狱」。"},
{"c":"打一字","q":"八十八","a":"米。「八」「十」「八」三部分合起来，就是「米」。"},
{"c":"打一字","q":"公而忘私","a":"八。「公」去掉「厶」，剩下「八」。"},
{"c":"打一字","q":"再会","a":"观。「又」加「见」，再次相见，就是「观」。"},
{"c":"打一字","q":"出工出力","a":"功。「工」加「力」，就是「功」。"},
{"c":"打一字","q":"六十天","a":"朋。六十天是两个月，「月」加「月」，就是「朋」。"},
{"c":"打一字","q":"门里有集市，打一字。","a":"闹。“门”里加“市”，就是“闹”。"},
{"c":"打一字","q":"功过各一半","a":"边。「功」取「力」，「过」取走之底，合成「边」。"},
{"c":"打一字","q":"半朋半友","a":"有。「朋」取「月」，「友」取上面一横，合成「有」。"},
{"c":"打一字","q":"去一人还有口去一口还有人","a":"合。「合」去掉「人」剩下「口」，去掉「口」剩下「人」。"},
{"c":"打一字","q":"古字刚分开豆字挤进来","a":"喜。「古」拆成「十」和「口」，「豆」挤在中间，就是「喜」。"},
{"c":"打一字","q":"台上长草","a":"苔。「台」上加草字头，就是「苔」。"},
{"c":"打一字","q":"多出一半","a":"岁。「多」由两个「夕」组成，取一半「夕」，加「山」，就是「岁」。"},
{"c":"打一字","q":"如出一口","a":"女。「如」去掉「口」，剩下「女」。"},
{"c":"打一字","q":"安心度日","a":"宴。「安」加「日」，就是「宴」。"},
{"c":"打一字","q":"守门员","a":"闪。「门」里加「人」，就是「闪」。"},
{"c":"打一字","q":"宋字去盖莫作木猜","a":"李。「宋」去掉宝盖头是「木」，再加「子」，就是「李」。"},
{"c":"打一字","q":"找字去掉提手旁，打一字。","a":"戈。“找”字去掉提手旁，剩下“戈”。"},
{"c":"打一字","q":"打断念头","a":"心。「念」去掉上面的「今」，剩下「心」。"},
{"c":"打一字","q":"早天雷","a":"田。「雷」去掉雨字头，剩下「田」；天早无雨，正是田。"},
{"c":"打一字","q":"有手就打","a":"丁。「打」去掉提手旁，剩下「丁」。"},
{"c":"打一字","q":"有水能养鱼，打一字。","a":"池。“水”加“也”，就是“池”。"},
{"c":"打一字","q":"有心记不住","a":"亡。「忘」去掉心字底，剩下「亡」。"},
{"c":"打一字","q":"有马能跑，打一字。","a":"驰。“马”加“也”，就是“驰”。"},
{"c":"打一字","q":"江水流","a":"工。「江」去掉三点水，剩下「工」。"},
{"c":"打一字","q":"竹林中的小屋，打一字。","a":"简。“竹”加“间”（门里有日），像竹林中的小屋，合起来就是“简”。"},
{"c":"打一字","q":"米老鼠","a":"籽。「米」加「子」，就是「籽」。"},
{"c":"打一字","q":"红娘","a":"姝。「朱」是红色，「女」是姑娘，合起来是「姝」。"},
{"c":"打一字","q":"缺乏资金","a":"次。「资」去掉「贝」，剩下「次」；贝代表钱财。"},
{"c":"打一字","q":"表里如一","a":"回。「回」字里外两个口一样，正是表里如一。"},
{"c":"打一字","q":"言及他人","a":"认。「言」加「人」，说到别人，就是「认」。"},
{"c":"打一字","q":"走错路了","a":"赵。「走」加「乂」，像走岔了路，就是「赵」。"},
{"c":"打一字","q":"走出深闺人结识","a":"佳。「闺」去掉门是「圭」，加单人旁，就是「佳」。"},
{"c":"打一字","q":"车上有车","a":"轰。两个「车」叠在一起，就是「轰」。"},
{"c":"打一字","q":"雨下有务，打一字。","a":"雾。“雨”字头下加“务”，就是“雾”。"},
{"c":"打一字","q":"金木水火","a":"坎。金木水火五行缺土，「欠土」加土旁，就是「坎」。"},
{"c":"打一字","q":"门里阳光照门外雨飘飘","a":"涧。「门」里加「日」，门外加三点水，合成「涧」。"},
{"c":"打一字","q":"闺中少女","a":"娃。「闺」去掉门是「圭」，加「女」，就是「娃」。"},
{"c":"打一字","q":"一口吃下一条虫","a":"虽。「口」加「虫」，一口吃下虫，就是「虽」。"},
{"c":"打一字","q":"一点一横长口字在中央","a":"言。一点一横，下面一个口，就是「言」。"},
{"c":"打一字","q":"千里姻缘一线牵","a":"重。「千」加「里」，就是「重」。"},
{"c":"打一字","q":"大点","a":"太。「大」加一点，就是「太」。"},
{"c":"打一字","q":"小口","a":"京。上面一点一横，中间口，下面小，合成「京」。"},
{"c":"打一字","q":"山边泉水","a":"汕。「山」加三点水，就是「汕」。"},
{"c":"打一字","q":"青天挂太阳，打一字。","a":"晴。“日”加“青”，就是“晴”。"},
{"c":"打一字","q":"心有余力不足","a":"忍。「刃」加「心」，心里有余，力却不足，就是「忍」。"},
{"c":"打一字","q":"日加一笔有十日","a":"早。「日」加「十」，就是「早」。"},
{"c":"打一字","q":"木偶","a":"休。「人」靠在「木」旁，像木偶，就是「休」。"},
{"c":"打一字","q":"水上人家","a":"沪。三点水加「户」，水边人家，就是「沪」。"},
{"c":"打一字","q":"牛过独木桥","a":"生。「牛」下面加一横，像牛过独木桥，就是「生」。"},
{"c":"打一字","q":"王先生白先生坐在石头上","a":"碧。「王」「白」「石」三部分合起来，就是「碧」。"},
{"c":"打一字","q":"东西南北无弯路","a":"置。上面「四」像四方，下面「直」是没有弯路，合成「置」。"},
{"c":"打一字","q":"出口成章","a":"吝。「文」加「口」，出口成章，就是「吝」。"},
{"c":"打一字","q":"半硬半软","a":"砍。「硬」取「石」，「软」取「欠」，合成「砍」。"},
{"c":"打一字","q":"去头是字去尾是字","a":"申。「申」去掉上面一竖是「田」，去掉下面一竖是「日」。"},
{"c":"打一字","q":"一点一横长，一撇到南洋，南洋有个人，只有一寸长。","a":"府。广字头下有「付」，「付」中藏「寸」，合起来就是府。"},
{"c":"打一字","q":"一点一横长，二字口四方，两边丝绕绕，中间马大王。","a":"弯。繁体「彎」由「糸」「言」「弓」组成；简化后写作「弯」。"},
{"c":"打一字","q":"良宵伴月，打一字。","a":"朗。“良”加“月”，就是“朗”。"},
{"c":"打一字","q":"一字生得巧，四面八只脚。","a":"井。四面伸出八只脚，像井字。"},
{"c":"打一字","q":"一字有六笔，笔笔是斜的。","a":"众。三个人叠在一起，六笔都是斜的。"},
{"c":"打一字","q":"一字十八口。","a":"杏。「十」「八」组成木，下面加口，就是杏。"},
{"c":"打一字","q":"一字六口，书中常有。","a":"典。上面像六口，下面是书架，书里常见。"},
{"c":"打一字","q":"一点一横，两眼一瞪。","a":"六。一点一横，下面两撇像两眼一瞪。"},
{"c":"打一字","q":"两棵树并排，打一字。","a":"林。两个“木”并排，就是“林”。"},
{"c":"打一字","q":"言成即诚，打一字。","a":"诚。“言”旁加“成”，就是“诚”。"},
{"c":"打一字","q":"十张口。","a":"古。十加口，就是古。"},
{"c":"打一字","q":"三张纸。","a":"顺。三张纸像三页，页加川，合成顺。"},
{"c":"打一字","q":"三金相连。","a":"鑫。三个金叠在一起，就是鑫。"},
{"c":"打一字","q":"三木相连。","a":"森。三个木叠在一起，就是森。"},
{"c":"打一字","q":"三火相连。","a":"焱。三个火叠在一起，就是焱。"},
{"c":"打一字","q":"三牛在一起。","a":"犇。三头牛在一起，就是犇。"},
{"c":"打一字","q":"水上加一点，打一字。","a":"永。“水”字上加一点，就是“永”。"},
{"c":"打一字","q":"三口重叠，莫把品字猜。","a":"目。三个口竖着叠，不是品，是目。"},
{"c":"打一字","q":"不正就是它，打一字。","a":"歪。“不”和“正”上下相合，就是“歪”。"},
{"c":"打一字","q":"上有二十万大军，下有四个小兵，打开北边城门，中间一口大井。","a":"燕。廿像二十万大军，灬像四个小兵，北像城门，口像井。"},
{"c":"打一字","q":"头上一横，中间一竖，末尾一点。","a":"下。「下」字上面一横、中间一竖、下面一点，正是“下”。"},
{"c":"打一字","q":"不字加一点，莫当玉字猜。","a":"卞。不字加一点，不是玉，是卞。"},
{"c":"打一字","q":"真心待人。","a":"慎。真加竖心旁，真心待人，就是慎。"},
{"c":"打一字","q":"庄稼长得高，打一字。","a":"稿。左边“禾”代表庄稼，右边“高”表示长得高，合起来就是“稿”。"},
{"c":"打一字","q":"二山在一起，猜出便错了。","a":"击。二山叠在一起，不是出，是击。"},
{"c":"打一字","q":"二人力大冲破天。","a":"夫。二加人，二人力大冲破天，就是夫。"},
{"c":"打一字","q":"五个兄弟，住在一起，名字不同，高矮不齐。","a":"手。五个指头住在一起，名字不同，高矮不齐。"},
{"c":"打一字","q":"人人离座。","a":"庄。座字去掉两个人，剩广和土，就是庄。"},
{"c":"打一字","q":"太阳落在正下方，打一字。","a":"是。上面是“日”，下面是“正”，合起来就是“是”。"},
{"c":"打一字","q":"人言可畏。","a":"信。人加言，人言可畏，就是信。"},
{"c":"打一字","q":"今字多一横。","a":"令。今字多一横，就是令。"},
{"c":"打一字","q":"付出爱心。","a":"受。爱字去掉心，剩下受。"},
{"c":"打一字","q":"人旁有尔，打一字。","a":"你。“人”旁加“尔”，就是“你”。"},
{"c":"打一字","q":"你多心了。","a":"您。你加心，就是您。"},
{"c":"打一字","q":"值钱不值钱，全在这两点。","a":"金。值钱不值钱，全在金字头上两点。"},
{"c":"打一字","q":"山下面有块石头，打一字。","a":"岩。“山”下面加“石”，合起来就是“岩”。"},
{"c":"打一字","q":"一人一张口，口下长只手，打一字。","a":"拿。上面是“合”，下面加一个“手”，合起来就是“拿”。"},
{"c":"打一字","q":"门里有只耳朵，打一字。","a":"闻。“门”里加“耳”，合起来就是“闻”。"},
{"c":"打一字","q":"画时圆，写时方，冬时短，夏时长，打一字。","a":"日。太阳画出来是圆的，写“日”字是方的；冬天白昼短、夏天白昼长。"},
{"c":"打一字","q":"手搭在眼睛上，打一字。","a":"看。上面是“手”，下面是“目”，合起来就是“看”。"},
{"c":"打一字","q":"田边长草，打一字。","a":"苗。“田”上面加草字头，就是“苗”。"},
{"c":"打一字","q":"左边鱼右边羊，打一字。","a":"鲜。左边是“鱼”，右边是“羊”，两种味道鲜美的食材合在一起就是“鲜”。"},
{"c":"打一字","q":"山上有只鸟，打一字。","a":"岛。“山”上有“鸟”，合起来就是“岛”。"}
  ],
  miyu:[
{"c":"动物谜语","q":"耳朵长，尾巴短，红眼睛，白毛衫，三瓣嘴儿胆子小，蹦蹦跳跳惹人爱。","a":"兔子。长耳、短尾、三瓣嘴、白毛，都是兔子的特征。"},
{"c":"动物谜语","q":"身穿黄衣裳，头戴大花冠，天亮就唱歌，催人早早起。","a":"公鸡。黄羽、鸡冠、天亮打鸣，说的是公鸡。"},
{"c":"动物谜语","q":"嘴像小铲子，脚像小扇子，走路左右摆，水上划船子。","a":"鸭子。扁嘴、蹼足、摇摆着游水，指的是鸭子。"},
{"c":"动物谜语","q":"身披花棉袄，唱歌呱呱叫，田里捉害虫，丰收立功劳。","a":"青蛙。花绿皮肤、呱呱叫、田里吃虫，是青蛙。"},
{"c":"动物谜语","q":"头小颈长四脚短，硬壳壳里把身安，别看平时走得慢，寿命可长不一般。","a":"乌龟。硬壳、短腿、走得慢又长寿，指乌龟。"},
{"c":"动物谜语","q":"八字须往上翘，说话好像娃娃叫，只洗脸不梳头，夜行不用灯光照。","a":"猫。翘胡须、爱洗脸、夜里活动，是猫。"},
{"c":"动物谜语","q":"粽子脸梅花脚，前面喊叫后面舞刀。","a":"狗。见人就叫、尾巴摇得像舞刀，说的是狗。"},
{"c":"动物谜语","q":"小小诸葛亮，稳坐中军帐，摆下八卦阵，专捉飞来将。","a":"蜘蛛。结网像八卦阵，专等飞虫自投，是蜘蛛。"},
{"c":"动物谜语","q":"远看像黄球，近看毛茸茸，叽叽叽叽叫，最爱吃小虫。","a":"小鸡。黄绒球、叽叽叫、啄小虫，指小鸡。"},
{"c":"动物谜语","q":"黑毛黑白毛白，圆圆胖胖惹人爱，攀得高爬得快，嫩竹野果当饭菜。","a":"熊猫。黑白毛、圆胖、爬树吃竹，是熊猫。"},
{"c":"动物谜语","q":"头戴红缨帽，身穿绿战袍，说话音清脆，动不动就把人咬。","a":"鹦鹉。红冠绿羽、学人说话、会啄人，指鹦鹉。"},
{"c":"动物谜语","q":"身子细长一条线，没有脚儿跑得欢，草丛里面常出没，吐着舌头好吓人。","a":"蛇。细长无足、草丛出没、吐信，是蛇。"},
{"c":"动物谜语","q":"耳朵像蒲扇，身子像小山，鼻子长又长，帮人把活干。","a":"大象。蒲扇耳、山样身、长鼻能干活，指大象。"},
{"c":"动物谜语","q":"头戴红冠帽，身穿白布袍，走路像摇船，游泳像飞鸟。","a":"鹅。红冠白羽、摇摆走路、善游，是鹅。"},
{"c":"动物谜语","q":"尾巴一根钉，眼睛两粒豆，有翅没有毛，有脚不会走。","a":"蜻蜓。细尾、大复眼、薄翅悬停，指蜻蜓。"},
{"c":"动物谜语","q":"说它是马猜错了，穿的衣服净道道，放进动物园，大人小孩都爱瞧。","a":"斑马。像马却满身黑白条纹，是斑马。"},
{"c":"动物谜语","q":"尖尖牙齿大盆嘴，短短腿儿长长尾，捕捉食物流眼泪，人人知它假慈悲。","a":"鳄鱼。大嘴长尾、捕食时「流泪」，指鳄鱼。"},
{"c":"动物谜语","q":"模样像狗不是狗，狡猾多疑四处走，拖着一条大尾巴，兔子见它抖三抖。","a":"狐狸。像狗非狗、狡猾、大尾巴，是狐狸。"},
{"c":"动物谜语","q":"周身银甲耀眼明，浑身上下冷冰冰，有翅不能飞，没脚却能行。","a":"鱼。银鳞、有鳍无足、水中游，指鱼。"},
{"c":"动物谜语","q":"生在大海岩石旁，身体柔软甲似钢，八条长腿围一圈，横行霸道谁敢挡。","a":"螃蟹。海边硬甲、八足横着走，是螃蟹。"},
{"c":"动物谜语","q":"身穿绿衣裳，肩扛两把刀，庄稼地里走，害虫吓得跑。","a":"螳螂。绿衣、两把「大刀」、田间捕虫，指螳螂。"},
{"c":"动物谜语","q":"叫牛不是牛，不爱拉犁头，虽说力气小，背着房子走。","a":"蜗牛。名带「牛」却背壳慢行，是蜗牛。"},
{"c":"动物谜语","q":"团结劳动是模范，全家住在格子间，常到花丛去工作，造出产品比糖甜。","a":"蜜蜂。群居格巢、花间采蜜，指蜜蜂。"},
{"c":"动物谜语","q":"一个黑大汉，腰插两把扇，走一步扇几扇。","a":"鸵鸟。黑羽、翅膀当扇、快步疾走，是鸵鸟。"},
{"c":"动物谜语","q":"身穿黄袍带黑杠，大叫一声震山冈，百兽闻声都逃命，威风凛凛山中王。","a":"老虎。黄底黑纹、一啸镇山，指老虎。"},
{"c":"动物谜语","q":"小小飞贼武器是针，抽别人血养自己身。","a":"蚊子。针样口器吸血，说的是蚊子。"},
{"c":"动物谜语","q":"天热爬上树梢，总爱大喊大叫，明明啥也不懂，偏说知道知道。","a":"蝉。盛夏树上高鸣「知了」，指蝉。"},
{"c":"动物谜语","q":"红领圈儿小黑袄，尾巴尖尖像剪刀，飞在蓝天剪春色，屋檐底下把窝造。","a":"燕子。红喉、剪形尾、檐下筑巢，是燕子。"},
{"c":"动物谜语","q":"身手矫健到处跑，深山老林逞英豪，别看平时都叫好，屁股红红惹人笑。","a":"猴子。林间灵巧、红屁股，指猴子。"},
{"c":"动物谜语","q":"一个医生嘴巴尖，天天出诊到林间，敲敲听听多仔细，要动手术把头点。","a":"啄木鸟。尖嘴敲树、捉虫像动手术，是啄木鸟。"},
{"c":"动物谜语","q":"面孔像猫起飞像鸟，天天上夜班，捉鼠本领高。","a":"猫头鹰。面似猫、夜出捕鼠，指猫头鹰。"},
{"c":"动物谜语","q":"弯弯曲曲一座山，小姐登在绣房间，无聊男子来捞我，小姐就把房门关。","a":"田螺。螺旋壳一碰就闭厣，说的是田螺。"},
{"c":"动物谜语","q":"春到它来临催唤播种人，秋后它返回遍传丰收音。","a":"布谷鸟。春天催人播种，秋后叫声像丰收，就是布谷鸟。"},
{"c":"动物谜语","q":"小小身躯真灵巧，尾巴蓬松像扫帚，松树林里蹦蹦跳，过冬储粮早准备。","a":"松鼠。尾巴蓬松像扫帚，松林里蹦跳，过冬储粮。"},
{"c":"动物谜语","q":"头戴红缨帽，身穿绿罗袍，背上生双翅，爱脏腿长毛。","a":"苍蝇。红帽绿袍、背生双翅、腿上有毛，就是苍蝇。"},
{"c":"动物谜语","q":"腿长胳膊短，眉毛盖着眼，有人不吱声，无人爱叫唤。","a":"蝈蝈。腿长、眉毛盖眼，没人时爱叫，就是蝈蝈。"},
{"c":"动物谜语","q":"一身白袍衣，两只红眼睛，是和平化身，人人喜欢它。","a":"鸽子。白羽、红眼，象征和平，就是鸽子。"},
{"c":"动物谜语","q":"头戴双尖帽缨，身穿黄色皮袄，说话带鼻音，人人听得清。","a":"牛。头上有尖角、黄皮袄、叫声带鼻音，就是牛。"},
{"c":"动物谜语","q":"身体似雪白，肚里比墨黑，从来不偷窃，硬说它是贼。","a":"乌贼。身体雪白、肚里墨黑，从不偷东西却被叫贼。"},
{"c":"动物谜语","q":"嘴长腿高身披金，走起路来晃悠悠，脖子长长望远方，爱吃树叶不喝酒。","a":"长颈鹿。嘴长腿高、脖子长、爱吃树叶。"},
{"c":"动物谜语","q":"鼻子粗又长，两牙赛钢刀，双耳如蒲扇，身子似水缸","a":"大象。长鼻、长牙、大耳、大身子，就是大象。"},
{"c":"动物谜语","q":"身子细长尾巴大，沟里洞里它安家，虽有一身好皮毛，偶尔偷鸡名声差。","a":"黄鼠狼。身子细长、尾巴大，住沟洞，偶尔偷鸡。"},
{"c":"动物谜语","q":"两撇小胡子，油嘴小牙齿，贼头又贼脑，喜欢偷油吃。","a":"老鼠。小胡子、油嘴、贼头贼脑，爱偷油。"},
{"c":"动物谜语","q":"小时穿黑衣，大时换白袍，造间小屋子，里面睡大觉。","a":"蚕。小时黑衣，长大白袍，吐丝结茧睡大觉。"},
{"c":"动物谜语","q":"头生双角细微微，身穿花衣到处飞，说话唱歌它不会，跳起舞来姿势美。","a":"蝴蝶。头有触角、花衣、会飞，跳舞姿势美。"},
{"c":"动物谜语","q":"小飞虫尾巴明，黑夜闪闪像盏灯，古人读书曾借用，刻苦钻研当明灯。","a":"萤火虫。尾巴发光，夜里像小灯，古人借光读书。"},
{"c":"动物谜语","q":"身小力不小，团结又勤劳，有时搬粮食，有时挖地道。","a":"蚂蚁。身小力大、团结勤劳，会搬粮、挖地道。"},
{"c":"动物谜语","q":"头黑肚白尾巴长，传说娶妻忘了娘，生活之中人喜爱，因为常来报吉祥。","a":"喜鹊。头黑、肚白、尾长；民间把它看作报喜鸟，所以说它常来报吉祥。"},
{"c":"动物谜语","q":"面孔像狮子，尾巴像大鱼，身披铁甲衣，水中称霸王。","a":"鲨鱼。面孔像狮子、尾巴像鱼，披甲，在海里称霸。"},
{"c":"动物谜语","q":"头戴花冠鸟中少，身穿锦袍好炫耀，尾巴似扇能开屏，展开尾巴真俊俏。","a":"孔雀。花冠、锦羽，尾巴能开屏。"},
{"c":"动物谜语","q":"老家在非洲，力大赛过牛，张口一声吼，百兽都发抖。","a":"狮子。非洲草原，力大，吼一声百兽发抖。"},
{"c":"动物谜语","q":"身体长又圆，无脚走天涯，田里翻泥土，庄稼笑哈哈。","a":"蚯蚓。身体长圆、没有脚，在田里翻土。"},
{"c":"动物谜语","q":"身穿大皮袄，野草吃个饱，过了严冬天，献出一身毛。","a":"绵羊。大皮袄、吃野草，冬天过后献毛。"},
{"c":"动物谜语","q":"吃进是草，挤出是宝，养分高又高，我们少不了。","a":"奶牛。吃草，挤出牛奶，营养高。"},
{"c":"动物谜语","q":"家住青山顶，身披破蓑衣，常在天上游，爱吃兔和鸡。","a":"老鹰。住山顶、披蓑衣般的羽，天上飞，爱吃兔和鸡。"},
{"c":"动物谜语","q":"身穿梅花袍，头上顶双角，穿山又越岭，全身都是宝。","a":"鹿。梅花袍、头顶双角，穿山越岭。"},
{"c":"动物谜语","q":"叫马不像马，地上没有它，若用它做药，要到海中抓。","a":"海马。叫马不像马，地上没有，在海里，可入药。"},
{"c":"动物谜语","q":"有枪不能放，有腿不能走，天天弯着腰，总在水里游。","a":"虾。有枪不能放、有腿不能走，弯着腰在水里游。"},
{"c":"动物谜语","q":"背上背着一座山，身体长得笨又圆，大海深处它游泳，沙滩上面它产蛋。","a":"海龟。背上有壳像山，身体笨圆，在海里游，沙滩产蛋。"},
{"c":"动物谜语","q":"一条牛真厉害，猛兽见它也避开，皮厚毛稀少，长出角来当药材。","a":"犀牛。皮厚毛少、头上有角，猛兽也避开。"},
{"c":"动物谜语","q":"白衬衣黑大褂，走起路来左右摆，冰天雪地也不怕。","a":"企鹅。白衬衣黑大褂，走路摇摆，不怕冰天雪地。"},
{"c":"动物谜语","q":"面孔像老虎，身量像只猫，上树本领高，夜里到处跑。","a":"豹子。脸像虎、身像猫，会上树，夜里跑。"},
{"c":"动物谜语","q":"有个妈妈真奇怪，身上带个大口袋，不放萝卜不放菜，里面放个小乖乖。","a":"袋鼠。身上有口袋，里面装小袋鼠。"},
{"c":"动物谜语","q":"小货郎不挑担，背着针满处窜。","a":"刺猬。像小货郎，背着针到处窜。"},
{"c":"动物谜语","q":"身上滑溜溜，爱在泥里走，喜欢吐气泡，能够测气候。","a":"泥鳅。身上滑、爱钻泥、会吐泡，能测气候。"},
{"c":"动物谜语","q":"长得像黄狗，草原是故乡，成群一起走，专吃小绵羊。","a":"狼。像黄狗，草原成群，专吃小羊。"},
{"c":"动物谜语","q":"身长近一丈，鼻在头顶上，腹白背青黑，安家在海洋。","a":"海豚。身长、鼻在头顶、腹白背青黑，住在海里。"},
{"c":"动物谜语","q":"小时像逗号，大时像跳高，水里游得快，吃虫本领高。","a":"蝌蚪。小时候像逗号，长大变青蛙，水里游、吃虫。"},
{"c":"动物谜语","q":"不识字把字排，秋天去春天来，排队飞成行，团结又友爱。","a":"大雁。不识字却排成行，秋天南飞、春天回来。"},
{"c":"动物谜语","q":"两只翅膀难飞翔，既作衣裳又作房，宁让大水推倒墙，不让太阳晒破房。","a":"蚌。两片壳像翅膀，壳是衣裳也是房，怕太阳晒。"},
{"c":"动物谜语","q":"一条大军舰，能浮又能潜，吃鱼不喝水，喷水不吸烟。","a":"鲸鱼。像大军舰，能浮能潜，吃鱼，头顶喷水。"},
{"c":"植物谜语","q":"一个小姑娘，生在水中央，身穿粉红衫，坐在绿船上。","a":"荷花。长在水中央，粉红花瓣，绿叶像船。"},
{"c":"植物谜语","q":"头戴黄草帽，身穿绿旗袍，见风点点头，朝着太阳笑。","a":"向日葵。黄草帽、绿旗袍，见风点头，朝着太阳。"},
{"c":"植物谜语","q":"青藤挂满棚，结果像青龙，嫩时当菜吃，老了也有用。","a":"丝瓜。青藤挂棚，结的瓜像青龙，嫩时做菜，老了有用。"},
{"c":"植物谜语","q":"红口袋，绿口袋，有人害怕有人爱。","a":"辣椒。红绿口袋，有人怕辣，有人爱吃。"},
{"c":"植物谜语","q":"小时青青腹中空，长大头发蓬蓬松，姐姐撑船不离它，哥哥钓鱼抓手中。","a":"竹子。小时空心，长大蓬松，能撑船、能钓鱼。"},
{"c":"植物谜语","q":"架上爬身结绿瓜，瓜头顶上开黄花，生着吃来鲜又脆，炒熟做菜味道佳。","a":"黄瓜。架上爬藤，瓜顶开黄花，生吃脆，炒菜香。"},
{"c":"植物谜语","q":"冬天蟠龙卧，夏天枝叶开，龙须往上长，珍珠往下排。","a":"葡萄。藤像蟠龙，卷须往上，果实像珍珠往下排。"},
{"c":"植物谜语","q":"兄弟七八个，围着柱子坐，大家一分手，衣服就扯破。","a":"大蒜。兄弟七八个围柱子坐，分开时外衣破。"},
{"c":"植物谜语","q":"紫色树，开紫花，紫花落了结紫瓜，紫瓜里面装芝麻。","a":"茄子。紫树紫花，结紫瓜，里面装芝麻般的籽。"},
{"c":"植物谜语","q":"青青藤儿开黄花，地上开花不结果，地下结果不开花。","a":"花生。地上开花不结果，地下结果不开花。"},
{"c":"植物谜语","q":"长得像竹不是竹，周身有节不太粗，又是紫来又是绿，只吃生来不吃熟。","a":"甘蔗。像竹有节，紫绿相间，只吃生不吃熟。"},
{"c":"植物谜语","q":"红关公，白刘备，黑张飞，三结义。","a":"荔枝。红壳、白肉、黑核，像红关公、白刘备、黑张飞。"},
{"c":"植物谜语","q":"黄瓷瓶，口儿小，里面装着红珠宝，打开瓶口尝一尝，酸甜可口营养好。","a":"石榴。黄瓶口小，里面装红珠宝，酸甜营养好。"},
{"c":"植物谜语","q":"身穿绿衣裳，肚里水汪汪，生的子儿多，个个黑脸膛。","a":"西瓜。绿衣、水多、黑籽，夏天解渴。"},
{"c":"植物谜语","q":"小小金坛子，装着金饺子，吃掉金饺子，吐出白珠子。","a":"橘子。小金坛子，里面金饺子，吃完吐白珠。"},
{"c":"植物谜语","q":"皮儿有红又有黄，身子圆圆好模样，连皮带肉一起啃，味甜多汁有营养。","a":"苹果。红黄圆脸，连皮吃，甜多汁。"},
{"c":"植物谜语","q":"黄金布，包银条，中间弯弯两头翘。","a":"香蕉。黄金布包银条，弯弯两头翘。"},
{"c":"植物谜语","q":"粉脸红唇模样美，偏偏是个大歪嘴。","a":"桃子。粉脸红唇，歪嘴，身上有绒毛。"},
{"c":"植物谜语","q":"小刺猬，毛外套，脱了外套露紫袍，袍里套着红绒袄，袄里睡个白宝宝。","a":"栗子。刺猬壳、紫袍、红绒袄，里面白宝宝。"},
{"c":"植物谜语","q":"红漆桶，黑漆盖，里面装着甜酒菜。","a":"柿子。成熟柿子外皮红、果蒂黑，像红桶配黑盖；果肉软甜，像甜酒菜。"},
{"c":"植物谜语","q":"红木盒儿圆，四面封得严，打开木盒看，装个黄蜡丸。","a":"桂圆。红木盒圆、封得严，打开是黄蜡丸。"},
{"c":"植物谜语","q":"海南岛上是我家，能耐风吹和雨打，四季棉衣不离身，肚里有肉又有茶。","a":"椰子。海南长大，耐风雨，四季棉衣，肚里有肉有汁。"},
{"c":"植物谜语","q":"红丝线，吊绿球，人人见了口水流。","a":"杨梅。红丝线吊绿球，看了流口水。"},
{"c":"植物谜语","q":"小时青青老来红，立夏时节招顽童，手舞竹竿请下地，吃完两手红彤彤。","a":"桑葚。小时青、老来红，立夏招孩子，吃完手红。"},
{"c":"植物谜语","q":"四季常青绿，只是花开难，摊开一只手，尖针已扎满。","a":"仙人掌。四季常青，花开难，手掌状，尖针扎满。"},
{"c":"植物谜语","q":"说它是棵苗，为啥有知觉，轻轻一碰它，低头叶合了。","a":"含羞草。一碰就低头，叶子合起来。"},
{"c":"植物谜语","q":"小小伞兵随风飞，飞到东来飞到西，降落路边田野里，安家落户扎根基。","a":"蒲公英。小伞兵随风飞，落地扎根。"},
{"c":"植物谜语","q":"空心苗，叶儿长，挺直腰杆一两丈，老时花白飘满地，纺车里面把身藏。","a":"芦苇。空心、叶长、挺直，老时花白，能编席造纸。"},
{"c":"自然谜语","q":"银色带子天上挂，雨后斜阳才见它，赤橙黄绿青蓝紫，人人夸它真美丽。","a":"彩虹。雨后斜阳，七色像带子挂天上。"},
{"c":"自然谜语","q":"看不见来摸不着，不香不臭没味道，动物植物都需要，一时一刻离不了。","a":"空气。看不见摸不着，没味道，动植物都离不开。"},
{"c":"自然谜语","q":"小白花，天上栽，一夜北风遍地开，无根无叶六个瓣，太阳一出就不见。","a":"雪花。小白花天上栽，北风一吹遍地开，六瓣，太阳一出就不见。"},
{"c":"自然谜语","q":"忽然不见忽然有，像虎像龙又像狗，太阳出来它不怕，大风一吹它就走。","a":"云。忽有忽无，像虎像龙像狗，太阳不怕，大风一吹就走。"},
{"c":"自然谜语","q":"一匹白马跑上山，没有笼头没有鞍，谁要抓住这匹马，不是神仙也是仙。","a":"雾。像白马跑上山，没有笼头鞍，抓不住。"},
{"c":"自然谜语","q":"生来本无形，走动便有声，夏天无它热，冬天有它冷。","a":"风。无形，走动有声，夏天无它热，冬天有它冷。"},
{"c":"自然谜语","q":"一道银光一条线，划过长空似利剑，霎时跑了千万里，眨下眼睛看不见。","a":"闪电。银光一线，划过长空，眨眼不见。"},
{"c":"自然谜语","q":"天上有面鼓，藏在云深处，响时先冒火，声音震山谷。","a":"雷。天上有鼓藏云里，响时先冒火，声音震山谷。"},
{"c":"自然谜语","q":"有时落在山腰，有时挂在树梢，有时像面圆镜，有时像把镰刀。","a":"月亮。有时山腰、有时树梢，有时圆镜、有时镰刀。"},
{"c":"自然谜语","q":"东边升起西边落，又圆又红像团火，万物生长都靠它，黑暗见了就逃走。","a":"太阳。东升西落，又圆又红像火，万物靠它生长。"},
{"c":"自然谜语","q":"青石板，板石青，青石板上钉银钉，银钉个个会眨眼，一闪一闪亮晶晶。","a":"星星。青石板上钉银钉，一闪一闪会眨眼。"},
{"c":"自然谜语","q":"小珍珠，真可爱，只能看来不能戴，清晨落在草丛里，太阳一出就不在。","a":"露珠。小珍珠，只能看不能戴，清晨在草上，太阳一出就不见。"},
{"c":"自然谜语","q":"上去一团烟，下来一条线，冷了又改样，变成玻璃片。","a":"水。上去像烟，下来像线，冷了变玻璃片。"},
{"c":"自然谜语","q":"热天看不见，冷天才出现，倒挂玉筷子，根根屋檐悬。","a":"冰凌。热天不见，冷天出现，像玉筷倒挂屋檐。"},
{"c":"自然谜语","q":"远看是白银，近看是水纹，太阳一出来，悄悄就隐身。","a":"霜。远看白银，近看水纹，太阳一出就隐身。"},
{"c":"自然谜语","q":"天上有对亲兄弟，一个走东一个西，一个能照亮天地，一个只能在夜里。","a":"太阳和月亮。一个走东一个走西，一个照白天，一个在夜里。"},
{"c":"自然谜语","q":"蓝蓝天上一片海，海里飘着白帆船，帆船从来不靠岸，随风飘荡永不停。","a":"白云。蓝天上像海，白云像帆船，随风飘。"},
{"c":"自然谜语","q":"一条大河天上挂，风吹不走浪不翻，夜晚不见白天见，没有水来没有船。","a":"银河。一条大河天上挂，风吹不走，夜里可见，没有水船。"},
{"c":"自然谜语","q":"悬崖挂块大白布，千万只手抓不住，轰隆轰隆如雷响，疑是银河落山谷。","a":"瀑布。悬崖挂白布，手抓不住，轰隆如雷，像银河落山谷。"},
{"c":"物品谜语","q":"远看山有色，近听水无声，春去花还在，人来鸟不惊。","a":"画。画里的山水花鸟是静态的，所以远看有颜色、近听没有水声，人来鸟也不会飞走。"},
{"c":"自然谜语","q":"不速之客游天外，偶尔闯进大气来，熊熊烈火烧不尽，长留人间几千载。","a":"陨石。天外来客闯进大气，燃烧后落在地上。"},
{"c":"自然谜语","q":"从低到高，由浓到淡，忽左忽右，跟着风走。","a":"烟。从低到高、由浓到淡，忽左忽右跟着风。"},
{"c":"自然谜语","q":"金灿灿，圆滚滚，半个浮在海面，半个跳上天庭。","a":"日出。金灿灿圆滚滚，半个浮海面，半个升上天。"},
{"c":"自然谜语","q":"红日东升照四方，万道金光洒地上，傍晚时分落西山，留下晚霞映天光。","a":"夕阳。红日东升西落，傍晚留下晚霞。"},
{"c":"物品谜语","q":"背上还有一个背，腿边还有四条腿，走路睡觉用不着，写字画画要它陪。","a":"椅子。背上有靠背，腿边四条腿，写字画画时坐。"},
{"c":"物品谜语","q":"一只绵羊四只角，白天饿来夜晚饱，夏天没它还能过，冬天没它受不了。","a":"棉被。像四角绵羊，白天叠着饿，夜里盖着饱，冬天少不了。"},
{"c":"物品谜语","q":"有门无窗，有顶无墙，人在其中，可卧可躺。","a":"床。有门无窗、有顶无墙，人在里面躺卧。"},
{"c":"物品谜语","q":"一位老师不说话，肚里学问倒挺大，有字不认识，你就去问他。","a":"字典。不说话的老师，肚里学问大，不认识的字可以查。"},
{"c":"物品谜语","q":"千层宝库翻开来，漆黑纵横一片排，历代事情它记载，知识没它传不开。","a":"书。千层宝库，翻开漆黑一片，记载历代知识。"},
{"c":"物品谜语","q":"小画片，镶花边，五颜六色真鲜艳，天南海北到处飞，没有翅膀飞得远。","a":"邮票。小画片、花边、五颜六色，贴信上能飞远方。"},
{"c":"物品谜语","q":"有个大肚皮，真是怪脾气，张着大嘴街上站，专门吞食废东西。","a":"垃圾桶。大肚皮、怪脾气，张嘴站街上，专吞废物。"},
{"c":"物品谜语","q":"一物生来真稀奇，身穿三百多件衣，每天给它脱一件，年底剩下一张皮。","a":"日历。三百多件衣，每天脱一件，年底只剩一张皮。"},
{"c":"物品谜语","q":"小小骏马不停蹄，日日夜夜不休息，蹄声哒哒似战鼓，提醒人们争朝夕。","a":"钟表。小骏马不停蹄，日夜走，蹄声哒哒提醒时间。"},
{"c":"物品谜语","q":"弟弟长，哥哥短，两人赛跑大家看，弟弟跑了十二圈，哥哥一圈才跑完。","a":"钟表。长针弟弟跑十二圈，短针哥哥才走一圈。"},
{"c":"物品谜语","q":"无脚会走路，说话不用口，发出命令来，人人都遵守。","a":"闹钟。无脚会走，无口会说话，发出命令人人遵守。"},
{"c":"物品谜语","q":"小小玻璃房，外面有围墙，屋里热烘烘，墙外冰凉凉。","a":"热水瓶。玻璃房、外有围墙，里面热、外面凉。"},
{"c":"物品谜语","q":"叮铃铃，叮铃铃，一头说话一头听，两人不见面，说话听得清。","a":"电话。叮铃铃，一头说话一头听，两人不见面也能通话。"},
{"c":"物品谜语","q":"长方盒子墙上挂，一根线儿通天下，古今中外多少事，打开一看全知啦。","a":"电视机。长方盒子墙上挂，一根线通天下，打开知天下事。"},
{"c":"物品谜语","q":"小小盒子随身带，能说话来能唱歌，天涯海角都能联，千里之外见亲人。","a":"手机。小盒子随身带，能说话唱歌，天涯海角能联系。"},
{"c":"物品谜语","q":"方方一块板，上面有按键，连着全世界，信息传得快。","a":"电脑。方板上有按键，连着全世界，信息传得快。"},
{"c":"物品谜语","q":"一只箱子靠着墙，不放衣服不放粮，夏天降温送凉爽，冬天升温送暖阳。","a":"空调。箱子靠墙，夏天降温，冬天升温。"},
{"c":"物品谜语","q":"一朵花儿开得大，藤儿牵着高高挂，没有香味没有叶，会唱歌来会说话。","a":"喇叭。大花挂高处，没香味没叶，会唱歌说话。"},
{"c":"物品谜语","q":"一间房，亮堂堂，房里没有床和窗，老师讲课在房里，学生听课在远方。","a":"广播。亮堂堂的房，老师在里面讲，学生在远方听。"},
{"c":"物品谜语","q":"学问大，不说话，你要学知识，一定要找它。","a":"书。学问大不说话，要学知识就找它。"},
{"c":"物品谜语","q":"长长一条龙，走路轰隆隆，跨江又过河，钻山又进洞。","a":"火车。长长一条龙，轰隆隆走，跨江过河、钻山进洞。"},
{"c":"物品谜语","q":"一间小屋真稀奇，有门无窗有楼梯，楼上楼下都住人，两排座位排得密。","a":"公共汽车。小屋有门有楼梯，两排座位，载很多人。"},
{"c":"物品谜语","q":"四脚圆滚滚，眼睛亮晶晶，嘀嘀叫一声，招手过路人。","a":"汽车。四脚圆滚滚，眼睛亮，嘀嘀叫，招手就停。"},
{"c":"物品谜语","q":"一只大雁真稀奇，只喝油来不吃米，银光闪闪飞得高，穿云破雾行万里。","a":"飞机。大雁只喝油不吃米，银光闪闪，穿云破雾飞万里。"},
{"c":"物品谜语","q":"水面一座楼，没腿四处走，四海传友谊，它是好帮手。","a":"轮船。水面一座楼，没腿会走，四海传友谊。"},
{"c":"自然谜语","q":"不用发动昼夜转，春夏秋冬自己变，每天能行八万里，满载人类千千万。","a":"地球。不用发动昼夜转，四季自己变，每天行八万里，载着全人类。"},
{"c":"物品谜语","q":"两条铁轨长又长，一直伸向大海洋，火车奔跑在它上，运送货物和人忙。","a":"铁路。两条铁轨长又长，伸向大海，火车在上面跑。"},
{"c":"物品谜语","q":"高高一座塔，上面有针插，传播电视和广播，千家万户都靠它。","a":"电视塔。高塔上有针，传播电视广播，千家万户靠它。"},
{"c":"物品谜语","q":"一座桥，长又长，跨过大河连两岸，汽车火车上面跑，轮船从下穿行忙。","a":"大桥。长桥跨河连两岸，汽车火车上面跑，轮船下面穿。"},
{"c":"物品谜语","q":"一根线，细又长，连着万户和千家，白天黑夜送光明，没有它来黑麻麻。","a":"电线。细线连万家，白天黑夜送电，没它一片黑。"},
{"c":"物品谜语","q":"一个巨人真高大，钢铁骨骼水泥身，顶上冒烟轰轰响，发出电来亮万家。","a":"发电厂。钢铁水泥的巨人，顶上冒烟，发出电亮万家。"},
{"c":"物品谜语","q":"一物生来真稀奇，铜头铁臂笑嘻嘻，力大无穷推山倒，修路盖房全靠你。","a":"推土机。铜头铁臂，力大无穷，修路盖房全靠它。"},
{"c":"物品谜语","q":"长长手臂高高举，一抓就是几吨重，建筑工地上常见，吊起楼板真威风。","a":"起重机。长臂高举，一抓几吨，工地上吊楼板。"},
{"c":"物品谜语","q":"说是牛，不是牛，不吃草，光喝油，农民伯伯有了它，耕田耙地不用愁。","a":"拖拉机。说是牛不是牛，不吃草喝油，耕田耙地不用愁。"},
{"c":"动物谜语","q":"有头无颈，有眼无眉，有翅不飞，无脚能行。","a":"鱼。鱼有头无颈、有眼无眉，鳍像翅但不能飞，没有脚却靠鳍和身体摆动在水里前行。"},
{"c":"物品谜语","q":"一个箱子肚里凉，食物药品它储藏，保证不坏不变质，使用起来真便当。","a":"冰箱。箱子肚里凉，储藏食物药品，保鲜不变质。"},
{"c":"食物谜语","q":"白白一片似雪花，落下水里不见它，单独吃它会皱眉，放进菜里味更佳。","a":"盐。白得像雪花，落水就不见，单吃皱眉，做菜提味。"},
{"c":"食物谜语","q":"颜色白如雪，味道甜如蜜，炒菜少不了，调出好滋味。","a":"白糖。白如雪、甜如蜜，炒菜调味少不了。"},
{"c":"食物谜语","q":"生在西山，落在平地，又白又嫩，又甜又脆。","a":"萝卜。萝卜的根埋在土里，叶子在地面上；根身白嫩，吃起来脆甜。"},
{"c":"食物谜语","q":"一群白鹅，漂水过河，红棍挑起，送到庙里。","a":"饺子。白鹅漂水过河，红棍挑起，送到庙里，就是饺子。"},
{"c":"食物谜语","q":"白纸包松香，抛在海中央，听得潮水涨，连忙把网张。","a":"馄饨。白纸包松香，抛在海中央，潮水涨时下网，就是馄饨。"},
{"c":"食物谜语","q":"白白胖胖小宝宝，一煮浮起水上漂，有甜有咸味道好，元宵佳节少不了。","a":"汤圆。白胖小宝宝，一煮浮起来，有甜有咸，元宵节少不了。"},
{"c":"食物谜语","q":"三角四楞长，珍珠里面藏，想尝珍珠味，解带脱衣裳。","a":"粽子。三角四棱，里面藏珍珠，吃前解带脱衣。"},
{"c":"食物谜语","q":"白胖子，软又香，北方人最爱它，夹上肉来更美味。","a":"馒头。白胖子，软又香，北方人爱吃，夹肉更美味。"},
{"c":"食物谜语","q":"白又方，嫩又香，能做菜来能做汤，豆子做来营养好，每天吃它身体强。","a":"豆腐。白方嫩香，能做菜做汤，豆子做来营养好。"},
{"c":"食物谜语","q":"本来一大片，变成千条线，是线不缝衣，只在锅里见。","a":"面条。本来一大片，切成千条线，不缝衣，只在锅里见。"},
{"c":"食物谜语","q":"白如雪，细如丝，下到锅里漂起来，捞到碗里配菜吃，滑溜顺口真不赖。","a":"米线。白如雪、细如丝，下锅漂起来，捞到碗里配菜。"},
{"c":"食物谜语","q":"金枝玉叶山上飘，流到人间锅里捞，白白胖胖真可爱，又香又软味道好。","a":"米饭。金枝玉叶山上飘，流到人间锅里捞，白胖香软。"},
{"c":"食物谜语","q":"圆圆乎乎好东西，谁见谁说真稀奇，人家都是皮包骨，它却生来骨包皮。","a":"鸡蛋。圆圆乎乎，人家皮包骨，它却骨包皮。"},
{"c":"食物谜语","q":"一物生来真奇怪，白白嫩嫩像牛奶，没有腿来没有眼，水中生来桌上摆。","a":"豆芽。白嫩像牛奶，没腿没眼，水中生、桌上摆。"},
{"c":"食物谜语","q":"白布包红布，红布包猪油，猪油包颗核。","a":"荔枝。最外是红壳，壳内一层白膜，膜里是白润的果肉，正中包着黑褐色的核。"},
{"c":"食物谜语","q":"一只圆饼圆又圆，面上芝麻撒得全，贴在炉里烤一烤，出炉喷香人人馋。","a":"烧饼。圆烧饼撒芝麻，贴炉烤，出炉喷香。"},
{"c":"食物谜语","q":"白面棒，扭成双，放油锅里炸金黄，早餐桌上最常见，配碗豆浆味道香。","a":"油条。白面棒扭成双，油锅炸金黄，早餐配豆浆。"},
{"c":"食物谜语","q":"红红脸蛋像苹果，咬它一口酸溜溜，冰糖葫芦串起来，小孩见了口水流。","a":"山楂。红脸像苹果，咬一口酸，冰糖葫芦串起来。"},
{"c":"食物谜语","q":"一根金箍棒，红珠串在上，入口酸又甜，吃来真是爽。","a":"冰糖葫芦。金箍棒上串红珠，入口酸又甜。"},
{"c":"动物谜语","q":"四四方方一座城，里面住着千万兵，个个穿着黄马褂，不知谁是大将军。","a":"蜂巢。四方城，住千万兵，个个黄马褂，不知谁是将。"},
{"c":"食物谜语","q":"白罐子，装黑枣，又甜又香味道好。","a":"黑芝麻糊。白罐装黑枣，又甜又香。"},
{"c":"食物谜语","q":"黑黑一颗豆，种在田里头，成熟磨成浆，煮来甜又香。","a":"黑芝麻。黑豆种田里，成熟磨浆，煮来甜又香。"},
{"c":"人体谜语","q":"高高山上一蓬草，密密麻麻长得好，年年月月常整理，黑变白来再变少。","a":"头发。高山上一蓬草，密密麻麻，月月整理，黑变白、白变少。"},
{"c":"人体谜语","q":"两间房，一样宽，白天开门夜关门，房里住着两兄弟，睁眼看世界万象。","a":"眼睛。两间房一样宽，白天开、夜里关，里面两兄弟看世界。"},
{"c":"人体谜语","q":"上面短短毛，下面短短毛，中间夹颗黑葡萄。","a":"眼睛。上下短毛，中间夹颗黑葡萄。"},
{"c":"人体谜语","q":"一座山两个洞，进进出出都是风，洞里虽小却重要，闻香辨臭全靠它。","a":"鼻子。一座山两个洞，进进出出都是风，闻香辨臭靠它。"},
{"c":"人体谜语","q":"高高山顶两孔洞，不冒泉水只透风，人间百味它先知，酸甜苦辣它不懂。","a":"鼻子。山顶两孔，不冒泉水只透风，人间百味它先知。"},
{"c":"人体谜语","q":"红门楼白院墙，里面坐个红姑娘，能说会道本领强，吃饭说话它最忙。","a":"舌头。红门楼白院墙，里面红姑娘，能说会道，吃饭最忙。"},
{"c":"人体谜语","q":"红门楼白围墙，里面住个红姑娘，不言不语会品滋味，酸甜苦辣她先尝。","a":"舌头。红门楼白围墙，红姑娘不说话，却能品酸甜苦辣。"},
{"c":"人体谜语","q":"一堵白墙两排砖，砖头三十二三块，每天都要刷一刷，咬碎食物不嫌烦。","a":"牙齿。白墙两排砖，三十二三块，天天刷，咬碎食物。"},
{"c":"人体谜语","q":"两排小兵整整齐，白白硬硬守阵地，天天摩擦日日磨，嚼烂食物不费力。","a":"牙齿。两排小兵，白白硬硬，天天磨，嚼烂食物不费力。"},
{"c":"动物谜语","q":"身穿黑白衣，圆脸爱吃竹","a":"熊猫。黑白毛色、圆脸和爱吃竹子，都是熊猫的特征。"},
{"c":"动物谜语","q":"耳朵像蒲扇，鼻子能卷起，腿像四根柱","a":"大象。大耳朵、长鼻子和粗腿，都是大象的特征。"},
{"c":"动物谜语","q":"像猫不是猫森林里称王额上有王字","a":"老虎。额头有「王」字纹，森林里称王，就是老虎。"},
{"c":"动物谜语","q":"脖子长又长身穿花衣裳爱吃树叶","a":"长颈鹿。脖子长、花衣裳、吃树叶，就是长颈鹿。"},
{"c":"动物谜语","q":"身穿白衣裳红掌拨清波曲项向天歌","a":"鹅。白毛、红掌、曲项向天歌，正是鹅。"},
{"c":"动物谜语","q":"头戴红帽子身穿花衣裳每天喔喔叫","a":"公鸡。红冠、花羽、每天打鸣，就是公鸡。"},
{"c":"动物谜语","q":"嘴像小铲子脚像小扇子走路左右摆","a":"鸭子。扁嘴像铲、脚像扇、走路摇摆，就是鸭子。"},
{"c":"动物谜语","q":"眼睛像灯泡白天睡大觉晚上抓老鼠","a":"猫头鹰。眼睛大、白天睡、夜里抓老鼠，就是猫头鹰。"},
{"c":"动物谜语","q":"小小姑娘满身黑秋去江南春来归","a":"燕子。浑身黑、秋去江南、春来归，就是燕子。"},
{"c":"动物谜语","q":"有种鸟本领高尖嘴爱给树开刀","a":"啄木鸟。尖嘴在树上敲洞捉虫，就是啄木鸟。"},
{"c":"动物谜语","q":"头长两根树杈身穿斑点花褂","a":"梅花鹿。头上树杈状角、身上斑点，就是梅花鹿。"},
{"c":"动物谜语","q":"身披绿铠甲眼睛圆溜溜水里游得快","a":"青蛙。绿皮、圆眼、水里游得快，就是青蛙。"},
{"c":"动物谜语","q":"八只脚抬面鼓两把剪刀鼓前舞","a":"螃蟹。八只脚、两把钳，像在鼓前舞，就是螃蟹。"},
{"c":"动物谜语","q":"弯弯背上一座山渡河渡海不费难","a":"乌龟。背上有壳像山，渡水不费力，就是乌龟。"},
{"c":"动物谜语","q":"说它是马猜错了穿的衣服净道道","a":"斑马。身上一道道条纹，像穿着道道衣服的马。"},
{"c":"动物谜语","q":"身上滑溜溜爱在泥里钻见人就钻洞","a":"泥鳅。身上滑、爱钻泥、见人就钻洞，就是泥鳅。"},
{"c":"动物谜语","q":"身体半球形背上七颗星蚜虫怕见它","a":"七星瓢虫。半球形身体、背上有七星，专吃蚜虫。"},
{"c":"动物谜语","q":"小小飞机大眼睛两对翅膀轻又轻","a":"蜻蜓。大眼睛、两对轻翅膀，像小飞机。"},
{"c":"动物谜语","q":"身穿黄衣裳嗡嗡把歌唱采蜜忙又忙","a":"蜜蜂。黄衣裳、嗡嗡叫、采蜜忙，就是蜜蜂。"},
{"c":"动物谜语","q":"身子细长条躲在草丛叫秋天常听到","a":"蟋蟀。身子细长、躲在草丛里叫，秋天常听到。"},
{"c":"动物谜语","q":"说它是牛不耕田背着房子到处走","a":"蜗牛。背着自己的壳，像背着房子走，不耕田。"},
{"c":"动物谜语","q":"胡子不多两边翘开口总说妙妙妙","a":"猫。胡子两边翘，开口「妙妙妙」，就是猫。"},
{"c":"动物谜语","q":"粽子头梅花脚屁股挂把指挥刀","a":"狗。头像粽子、脚像梅花，尾巴像指挥刀。"},
{"c":"动物谜语","q":"脊背突起似山峰沙漠之舟能负重","a":"骆驼。背上有驼峰，能在沙漠里负重。"},
{"c":"动物谜语","q":"有头没有颈身体冷冰冰没手也没脚","a":"鱼。有头没有脖子，身体冷，没手没脚，在水里游。"},
{"c":"动物谜语","q":"身穿皮袄黄又黄呼啸一声百兽慌","a":"狮子。黄毛、吼声大，百兽听了都慌。"},
{"c":"动物谜语","q":"嘴长耳朵大，一条小尾巴，爱吃不爱动","a":"猪。嘴长、耳大、尾巴小，爱吃不爱动，就是猪。"},
{"c":"动物谜语","q":"身穿白皮袄山坡啃青草为了他人暖","a":"绵羊。白毛、山坡吃草，毛能给人做衣服。"},
{"c":"动物谜语","q":"头长两尖角身披白棉袄吃草产奶好","a":"奶牛。头上有角、白毛、吃草产奶，就是奶牛。"},
{"c":"动物谜语","q":"灰背白肚皮，水里游得快，会跳又会唱","a":"海豚。灰背白肚、游泳快、会跳跃，就是海豚。"},
{"c":"动物谜语","q":"身体虽不大钢针满身插遇敌蜷一团","a":"刺猬。身上长满钢针，遇敌缩成一团。"},
{"c":"动物谜语","q":"一只大鸟真奇怪不会飞来跑得快","a":"鸵鸟。大鸟不会飞，腿长跑得快，就是鸵鸟。"},
{"c":"动物谜语","q":"身穿银甲亮晶晶海里游来游去快","a":"带鱼。银白色、身体长，在海里游得快。"},
{"c":"动物谜语","q":"大眼睛阔嘴巴尾巴要比身体大","a":"金鱼。大眼睛、大尾巴，尾巴比身体还大。"},
{"c":"动物谜语","q":"尖尖牙齿大盆嘴短短腿儿长长尾","a":"鳄鱼。尖牙、大嘴、短腿、长尾，就是鳄鱼。"},
{"c":"成语谜语","q":"最反常的天气。","a":"晴天霹雳。晴天突然打雷，天气反常。"},
{"c":"成语谜语","q":"最昂贵的稿费。","a":"一字千金。一个字值千金，稿费昂贵。"},
{"c":"成语谜语","q":"最大的手。","a":"一手遮天。一只手把天遮住，夸张手大。"},
{"c":"成语谜语","q":"最长的腿。","a":"一步登天。一步就跨上天，夸张腿长。"},
{"c":"成语谜语","q":"最干净的地方。","a":"一尘不染。一点灰尘都不沾，最干净。"},
{"c":"成语谜语","q":"最穷的人。","a":"一无所有。什么都没有，最穷。"},
{"c":"成语谜语","q":"古时有人给画好的蛇添上脚，结果这幅画落选了。打一成语。","a":"画蛇添足。蛇本来没有脚，添脚反而多余。"},
{"c":"成语谜语","q":"一个人坐船过江，剑掉进水里，他在船舷上刻记号，等船停后再找。打一成语。","a":"刻舟求剑。船在动而记号不动，比喻方法僵化。"},
{"c":"成语谜语","q":"最宽的视野。","a":"一览无余。一眼看过去全看见，视野最宽。"},
{"c":"成语谜语","q":"最重的话。","a":"一言九鼎。一句话像九鼎一样重。"},
{"c":"成语谜语","q":"一个人捂着耳朵去偷铃铛，以为自己听不见，别人也听不见。打一成语。","a":"掩耳盗铃。捂住耳朵并不能让铃声消失。"},
{"c":"成语谜语","q":"最快的阅读。","a":"一目十行。一眼看十行，阅读最快。"},
{"c":"成语谜语","q":"最有价值的话。","a":"一诺千金。一句承诺值千金，话最有价值。"},
{"c":"成语谜语","q":"最长的寿命。","a":"万寿无疆。寿命没有尽头，最长寿。"},
{"c":"成语谜语","q":"最大的家。","a":"四海为家。把四海都当作家，家最大。"},
{"c":"成语谜语","q":"最远的地方。","a":"天涯海角。天的尽头、海的角落，最远。"},
{"c":"成语谜语","q":"最爱学习的人。","a":"如饥似渴。像饿极渴极一样学习，最爱学习。"},
{"c":"成语谜语","q":"最爱工作的人。","a":"废寝忘食。忘了睡觉吃饭，最爱工作。"},
{"c":"成语谜语","q":"最吝啬的人。","a":"一毛不拔。一根毛都不肯拔，最吝啬。"},
{"c":"成语谜语","q":"一个人担心天会塌下来，整天吃不下饭、睡不着觉。打一成语。","a":"杞人忧天。没有根据的忧虑。"},
{"c":"成语谜语","q":"一个人买鞋时只相信量好的尺码，不肯用自己的脚试。打一成语。","a":"郑人买履。宁可相信尺码，也不相信脚。"},
{"c":"成语谜语","q":"最惨的结局。","a":"一败涂地。败到地上都涂满，结局最惨。"},
{"c":"成语谜语","q":"最彻底的劳动。","a":"斩草除根。草连根拔掉，劳动最彻底。"},
{"c":"成语谜语","q":"最多的颜色。","a":"万紫千红。紫红颜色成千上万，颜色最多。"},
{"c":"成语谜语","q":"一个人看见兔子撞死在树桩上，就放下农具天天守在树桩旁等。打一成语。","a":"守株待兔。把偶然当成必然。"},
{"c":"成语谜语","q":"最繁忙的季节。","a":"多事之秋。秋天事情多，季节最繁忙。"},
{"c":"成语谜语","q":"最公开的事情。","a":"尽人皆知。所有人都知道，事情最公开。"},
{"c":"成语谜语","q":"最高明的医术。","a":"药到病除。药一用病就好，医术最高明。"},
{"c":"成语谜语","q":"最高超的技术。","a":"鬼斧神工。像鬼神做的，技术最高超。"},
{"c":"成语谜语","q":"最好的记忆。","a":"过目成诵。看一遍就能背，记忆最好。"},
{"c":"成语谜语","q":"最大的变化。","a":"翻天覆地。天翻过来地覆过去，变化最大。"},
{"c":"成语谜语","q":"古时有人为了让庄稼长得快，把每一棵都往上提了一截，结果庄稼全枯了。打一成语。","a":"拔苗助长。违反生长规律反而坏事。"},
{"c":"成语谜语","q":"最宽阔的胸怀。","a":"虚怀若谷。胸怀像山谷一样空，最宽阔。"},
{"c":"成语谜语","q":"最长的一天。","a":"度日如年。一天像一年那么长，日子最长。"},
{"c":"成语谜语","q":"最长的夜晚。","a":"长夜难明。夜晚长得难到天明，夜晚最长。"},
{"c":"成语谜语","q":"越王勾践每天睡在柴草上，吃饭前先尝苦胆，提醒自己不忘耻辱。打一成语。","a":"卧薪尝胆。刻苦自励，发愤图强。"},
{"c":"成语谜语","q":"项羽渡河后砸破锅、沉掉船，只带三天粮，表示决一死战。打一成语。","a":"破釜沉舟。下决心决一死战。"},
{"c":"成语谜语","q":"最大的容量。","a":"包罗万象。把万象都包进去，容量最大。"},
{"c":"成语谜语","q":"最大的差别。","a":"天壤之别。天和地差得远，差别最大。"},
{"c":"成语谜语","q":"最难做的饭。","a":"无米之炊。没有米还要做饭，饭最难做。"},
{"c":"成语谜语","q":"最大的手术。","a":"脱胎换骨。换掉胎骨，手术最大。"},
{"c":"成语谜语","q":"最大的被子。","a":"铺天盖地。铺满天地，被子最大。"},
{"c":"成语谜语","q":"最大的空间。","a":"无边无际。没有边没有际，空间最大。"},
{"c":"成语谜语","q":"蔺相如把和氏璧完好地从秦国带回赵国。打一成语。","a":"完璧归赵。把原物完好归还。"},
{"c":"成语谜语","q":"最好的生意。","a":"一本万利。一份本钱万份利，生意最好。"},
{"c":"成语谜语","q":"最绝望的前途。","a":"山穷水尽。山穷了水尽了，前途最绝望。"},
{"c":"成语谜语","q":"最彻底的整容。","a":"面目全非。脸全变了，整容最彻底。"},
{"c":"成语谜语","q":"最深的缘分。","a":"不解之缘。解不开的缘分，缘分最深。"},
{"c":"成语谜语","q":"最高的巨人。","a":"顶天立地。头顶天脚立地，巨人最高。"},
{"c":"成语谜语","q":"最多的资源。","a":"取之不尽。怎么取都取不完，资源最多。"},
{"c":"成语谜语","q":"最重的头发。","a":"一发千钧。一根头发吊千钧，头发最重。"},
{"c":"成语谜语","q":"廉颇背着荆条到蔺相如门前认错。打一成语。","a":"负荆请罪。主动向人认错赔礼。"},
{"c":"成语谜语","q":"赵括只会背兵书，不会实际打仗，结果在长平大败。打一成语。","a":"纸上谈兵。空谈理论，不能解决实际问题。"},
{"c":"成语谜语","q":"赵高把鹿说成马，试探大臣是否服从。打一成语。","a":"指鹿为马。故意颠倒黑白，混淆是非。"},
{"c":"成语谜语","q":"最大的谎言。","a":"弥天大谎。谎言大得满天，谎言最大。"},
{"c":"成语谜语","q":"最安静的地方。","a":"万籁俱寂。所有声音都静了，地方最安静。"},
{"c":"成语谜语","q":"最快的流水。","a":"一泻千里。水一冲就下千里，流水最快。"},
{"c":"动物谜语","q":"尾巴像把伞，树上跳来跳去，爱吃松果","a":"松鼠。大尾巴、树上跳、吃松果，就是松鼠。"},
{"c":"动物谜语","q":"虽然不识字能把字儿排空中写人字","a":"大雁。不识字，却能排成「人」字或「一」字飞。"},
{"c":"动物谜语","q":"小飞虫尾巴明黑夜闪闪像盏灯","a":"萤火虫。小飞虫，尾巴发光，夜里像小灯。"},
{"c":"植物谜语","q":"一个小姑娘，坐在水中央，身穿粉红衫","a":"荷花。长在水中央，粉红花瓣，就是荷花。"},
{"c":"植物谜语","q":"有根不沾泥，有叶不开花，水上漂呀漂","a":"浮萍。根不沾泥，叶子不开花，漂在水面上。"},
{"c":"植物谜语","q":"小时青蛋蛋，长大红蛋蛋，穿着绿衣裳","a":"枣。小时候青、长大红，外面还穿着绿衣裳。"},
{"c":"植物谜语","q":"红口袋绿口袋，有人怕有人爱","a":"辣椒。红绿两种口袋，有人怕辣，有人爱吃。"},
{"c":"植物谜语","q":"紫色树紫色花，紫色果里装芝麻","a":"茄子。紫色树、紫色花，果子里装着小芝麻般的籽。"},
{"c":"植物谜语","q":"青藤爬满架，绿瓜挂满架，小时绿长大黄","a":"黄瓜。青藤上挂绿瓜，小时候绿，长大变黄。"},
{"c":"植物谜语","q":"红公鸡绿尾巴，一头扎在泥底下","a":"胡萝卜。红身子、绿尾巴，一头扎在泥里。"},
{"c":"植物谜语","q":"圆圆脸像苹果，又酸又甜营养多","a":"番茄。圆脸像苹果，又酸又甜，营养丰富。"},
{"c":"植物谜语","q":"兄弟七八个，围着柱子坐，一旦要分开，衣服就扯破","a":"蒜。兄弟七八个围着柱子坐，分开时外衣就破了。"},
{"c":"植物谜语","q":"青竹竿挑铜盆，开黄花结鱼鳞","a":"向日葵。青杆托着大花盘，开黄花，结的籽像鱼鳞。"},
{"c":"植物谜语","q":"头戴黄草帽，身穿绿色袍，见风点点头","a":"水稻。头戴黄穗，身穿绿袍，风一吹就点头。"},
{"c":"植物谜语","q":"小时青青地中埋，长大变成黄金海","a":"小麦。小时候青，长大后变成一片金黄。"},
{"c":"植物谜语","q":"麻屋子红帐子，里面住个白胖子","a":"花生。麻屋子、红帐子，里面住着白胖子。"},
{"c":"植物谜语","q":"冬天蟠龙卧，夏天枝叶开，龙须往上长","a":"葡萄。藤像蟠龙，夏天枝叶展开，卷须往上长。"},
{"c":"植物谜语","q":"一物生来真奇怪，腰里长出胡子来","a":"玉米。腰里长出胡子，剥开外衣是一排排玉米粒。"},
{"c":"植物谜语","q":"青藤绿叶开黄花，地上结果不结瓜","a":"土豆。青藤绿叶开黄花，果实结在土里，不结瓜。"},
{"c":"植物谜语","q":"身穿绿衣裳，肚里水汪汪，生的儿子多","a":"西瓜。绿皮、肚里水多，里面有很多黑籽。"},
{"c":"植物谜语","q":"小小金坛子，装着金饺子，吃掉金饺子","a":"橘子。小金坛子，里面一瓣瓣像金饺子。"},
{"c":"植物谜语","q":"黄皮包着红珍珠，颗颗珍珠有骨头","a":"石榴。黄皮里包着红珍珠般的籽，每颗都有小骨头。"},
{"c":"植物谜语","q":"海南岛上长，外壳硬邦邦，里面白又甜","a":"椰子。海南常见，外壳硬，里面有白肉和甜汁。"},
{"c":"植物谜语","q":"胖娃娃没手脚，红尖嘴一身毛","a":"桃子。胖娃娃没手脚，红尖嘴，一身绒毛。"},
{"c":"植物谜语","q":"身穿黄衣裳，弯弯像月牙，兄弟排排坐","a":"香蕉。黄衣裳、弯弯像月牙，兄弟们排排坐。"},
{"c":"植物谜语","q":"身体有节像根竹，削去青皮见白玉","a":"甘蔗。身体有节像竹，削去青皮露出白玉般的肉。"},
{"c":"植物谜语","q":"紫红藤地上爬，藤上长绿叶，地下结红瓜","a":"红薯。紫红藤在地上爬，地下结红瓜。"},
{"c":"植物谜语","q":"叶儿长长像麦苗，身子一直长不高","a":"韭菜。叶子长长像麦苗，身子一直长不高，割了还能再长。"},
{"c":"植物谜语","q":"青皮包白肉，像个小枕头，莫听名字冷","a":"冬瓜。青皮包白肉，像个小枕头，名字虽冷却是夏天的菜。"},
{"c":"植物谜语","q":"身体细长绿油油，一头圆来一头尖","a":"豆角。身体细长绿油油，一头圆一头尖。"},
{"c":"植物谜语","q":"生在山里，死在锅里，藏在瓶里","a":"茶叶。生在山里，采下后在锅里炒，最后藏在瓶里。"},
{"c":"地名谜语","q":"日比日月共争辉，春城四季花不谢","a":"昆明。「日」「比」「日」「月」合成「昆」「明」；春城四季花开，就是昆明。"},
{"c":"地名谜语","q":"千里广大，双重喜庆","a":"重庆。「千里广大」取「重」，「双重喜庆」取「庆」，合成重庆。"},
{"c":"地名谜语","q":"一大雨水从天降，陇上江南美名扬","a":"天水。「天」上加「水」，雨水从天降；陇上江南，就是天水。"},
{"c":"地名谜语","q":"四季如春暖，北国春城冰雪香","a":"长春。四季如春，北国春城，冰雪也有香气，就是长春。"},
{"c":"物品谜语","q":"你哭它也哭，你笑它也笑，正面看得见，背面找不到","a":"镜子。你哭它也哭，你笑它也笑，正面能照见，背面找不到。"},
{"c":"物品谜语","q":"一把小梳尺，专梳头发丝，每天梳一梳，头发顺又直","a":"梳子。齿像小梳尺，专门梳理头发。"},
{"c":"物品谜语","q":"小小一把刷，每天嘴里插，挤出白泡沫，牙齿白花花","a":"牙刷。小小一把刷，放进嘴里，挤出白泡沫。"},
{"c":"物品谜语","q":"不是甜品不是糖，挤出白膏嘴里放，天天用它刷牙齿，口气清新又健康","a":"牙膏。不是糖，挤出来是白膏，用来刷牙。"},
{"c":"物品谜语","q":"四四方方一块布，洗脸洗澡都用它，吸水柔软又舒服，每天早晚陪伴你","a":"毛巾。四四方方一块布，洗脸洗澡都靠它吸水。"},
{"c":"物品谜语","q":"一块东西滑溜溜，洗手洗澡起泡泡，去污除垢本领大，用完变小不见了","a":"肥皂。滑溜溜，遇水起泡泡，去污后越用越小。"},
{"c":"物品谜语","q":"圆圆一个盆，洗脸又洗手，装满清清水，映出笑脸来","a":"脸盆。圆盆装清水，洗脸洗手，还能照出笑脸。"},
{"c":"物品谜语","q":"有口没有牙，有盖没有把，装水又装茶，每天手中拿","a":"水杯。有口没牙，有盖没把，装水装茶。"},
{"c":"物品谜语","q":"大口朝上装饭菜，陶瓷铁皮塑料做，三餐离不开它，盛饭盛菜盛汤水","a":"碗。大口朝上，装饭装菜，三餐都离不开。"},
{"c":"物品谜语","q":"两个兄弟一样长，夹菜夹饭忙又忙，国人吃饭少不了，成双成对不分家","a":"筷子。两根一样长，成双成对夹菜夹饭。"},
{"c":"物品谜语","q":"一个凹凹头，一个长长把，舀汤舀饭都靠它，吃饭喝汤少不了","a":"勺子。凹头长把，舀汤舀饭。"},
{"c":"物品谜语","q":"圆圆扁扁一个盘，盛菜盛鱼盛肉丸，瓷的塑料不锈钢，摆在桌上真好看","a":"盘子。圆圆扁扁，盛菜盛鱼盛肉丸。"},
{"c":"物品谜语","q":"铁打身体长把柄，炒菜煮汤样样行，放在火上不怕热，厨房里面它最忙","a":"锅。铁身子长把，放在火上炒菜煮汤。"},
{"c":"物品谜语","q":"一把利器真锋利，切菜切肉切水果，厨房里面少不了，用时小心别伤手","a":"刀。锋利，切菜切肉切水果，用时要小心。"},
{"c":"物品谜语","q":"一块木板厚又实，切菜剁肉上面放，任劳任怨不叫苦，伤痕累累不抱怨","a":"砧板。厚木板，切菜剁肉垫在下面，伤痕累累也不抱怨。"},
{"c":"物品谜语","q":"四季里面凉飕飕，保鲜食物本领大，站在墙边不占地","a":"冰箱。里面常年低温，能保鲜食物，站在墙边不占地。"},
{"c":"物品谜语","q":"一个箱子四方方，衣服脏了放进去，转啊转啊洗干净，省时省力好帮手","a":"洗衣机。方箱子，脏衣服放进去，转一转就洗干净。"},
{"c":"物品谜语","q":"夏天送来清凉风，冬天吹出温暖气，挂在墙上不占地，遥控一按就工作","a":"空调。夏天送凉风，冬天送暖风，挂在墙上，遥控一按就工作。"},
{"c":"物品谜语","q":"三片叶子转啊转，送来凉风阵阵爽，夏天它是最受欢迎，摇头晃脑不停歇","a":"电风扇。三片叶子转，送来凉风，夏天受欢迎。"},
{"c":"物品谜语","q":"一个大方盒，有影又有声，世界各地事，全能看得清","a":"电视机。大方盒，有影有声，能看到世界各地的事。"},
{"c":"物品谜语","q":"小小方块掌中宝，能打电话能上网，聊天拍照玩游戏，现代人离不开它","a":"手机。小方块，能打电话、上网、拍照、玩游戏。"},
{"c":"物品谜语","q":"一个屏幕一个键盘，工作学习都靠它，上网查资料看电影，现代办公少不了","a":"电脑。屏幕加键盘，工作学习、上网查资料都靠它。"},
{"c":"物品谜语","q":"上面很多小方块，每个方块一个字，敲敲打打出文章，电脑离不了它","a":"键盘。很多小方块，每个方块一个字，敲出文章。"},
{"c":"物品谜语","q":"一只小老鼠，没有尾巴没有脚，连着电脑跑得快，点来点去真灵活","a":"鼠标。像小老鼠，没有尾巴，连着电脑点来点去。"},
{"c":"物品谜语","q":"一盏小灯桌上放，夜里读书它照亮，开关一按就发光，眼睛累了它帮忙","a":"台灯。小灯桌上放，夜里读书照亮。"},
{"c":"物品谜语","q":"滴答滴答不停走，准时叫醒梦中人，床头桌上它站岗，提醒时间不迟到","a":"闹钟。滴答走，准时叫醒人，提醒时间。"},
{"c":"物品谜语","q":"小小圆圆戴手腕，时针分针转圈圈，告诉你时间不耽误，手腕上的计时器","a":"手表。圆圆戴手腕，时针分针转圈，随时看时间。"},
{"c":"物品谜语","q":"两个圆圈架上鼻梁，透过它看世界清，近视老花都能帮，玻璃片片功劳大","a":"眼镜。两个圆圈架鼻梁，透过镜片看世界更清楚。"},
{"c":"物品谜语","q":"一根杆子能伸缩，晴天收起雨天撑，为你遮风又挡雨，花花绿绿真好看","a":"雨伞。杆子能伸缩，晴天收、雨天撑，遮风挡雨。"},
{"c":"物品谜语","q":"一个袋子背肩上，书本文具里面装，上学上班都带着，陪伴学生好时光","a":"书包。袋子背肩上，装书本文具，上学上班都带着。"},
{"c":"物品谜语","q":"小小一根杆，细又长，写出字来一行行，肚里藏着黑墨水，纸上留下好文章。","a":"笔。细长笔杆，肚里装墨水，纸上写字。"},
{"c":"物品谜语","q":"白白一张薄又薄，能写能画能折叠，知识在上面传播，书籍报刊全靠它","a":"纸。白白薄薄，能写能画能折，书报都靠它。"},
{"c":"物品谜语","q":"一块小东西，擦掉错别字，铅笔的好伙伴，越擦它越小","a":"橡皮。擦错别字，铅笔的好伙伴，越擦越小。"},
{"c":"物品谜语","q":"一把直直尺，量长短高低，画线做图都用它，刻度分明不差毫厘","a":"尺子。直直一把，量长短、画直线，刻度分明。"},
{"c":"物品谜语","q":"两片刀刃交叉装，剪纸剪布裁衣裳，张开嘴巴咔嚓响，锋利无比要小心","a":"剪刀。两片刀刃交叉，剪纸剪布，张开嘴咔嚓响。"},
{"c":"物品谜语","q":"小小身子亮闪闪，尖尖一头把孔穿，衣裳破了它来补，缝缝补补它最忙。","a":"针。细小尖头，穿上线缝衣裳。"},
{"c":"物品谜语","q":"细细长长一根，穿过小孔缝衣裳，五颜六色样样有，缝缝补补少不了。","a":"线。细细长长，穿过针眼，五颜六色，缝补少不了。"},
{"c":"物品谜语","q":"小小一粒圆又圆，衣服上面常看见，扣上扣眼不松开，整整齐齐真好看","a":"纽扣。小小圆圆，扣住扣眼，衣服整齐。"},
{"c":"物品谜语","q":"一条牙齿排排站，拉上拉下开关忙，衣服包包都用它，开合方便真利索","a":"拉链。一排牙齿，拉上拉下，衣服包包都能开合。"},
{"c":"自然谜语","q":"看不见摸不着，吹得树叶沙沙响，夏天送来清凉意，冬天刮来刺骨寒","a":"风。看不见摸不着，吹得树叶响，夏天送凉，冬天刺骨。"},
{"c":"自然谜语","q":"天上掉下银丝丝，落到地上湿漉漉，庄稼见了笑哈哈，行人见了躲屋檐","a":"雨。天上落下银丝，地上湿漉漉，庄稼喜欢，行人躲屋檐。"},
{"c":"自然谜语","q":"白色花瓣天上来，飘飘洒洒落满地，堆个娃娃真可爱，太阳一出化水流。","a":"雪。白色花瓣从天上来，落满地上，能堆雪人，太阳一出就化。"},
{"c":"自然谜语","q":"一道亮光划破天，轰隆巨响震耳边，吓得娃娃捂耳朵，大雨随后哗哗下","a":"雷电。一道亮光划破天，接着轰隆巨响，大雨随后下。"},
{"c":"自然谜语","q":"高高天上飘棉花，变来变去真奇妙，有时像马有时像狗，风一吹就跑远了","a":"云。天上飘的棉花，变来变去，风一吹就跑。"},
{"c":"自然谜语","q":"白茫茫一片看不清，伸手不见五指影，汽车开了双闪灯，太阳一出就消散。","a":"雾。白茫茫看不清，伸手不见五指，太阳一出就散。"},
{"c":"自然谜语","q":"清晨草上挂珍珠，太阳一出不见了，晶莹剔透真好看，脚踩过去鞋打湿","a":"露水。清晨草上挂珍珠，太阳一出就不见，踩过去鞋会湿。"},
{"c":"自然谜语","q":"冬天早晨一片白，铺在草地像白纱，太阳出来就化水，冷飕飕的早晨景","a":"霜。冬天早晨草地一片白，像铺了白纱，太阳出来就化。"},
{"c":"自然谜语","q":"水变成的硬邦邦，冬天河面结一层，孩子们在上面溜，春天一来就融化","a":"冰。水变的硬邦邦，冬天河面结一层，孩子能在上面溜。"},
{"c":"自然谜语","q":"天上掉下冰疙瘩，砸到头上疼又疼，夏天雷雨伴它来，噼里啪啦一阵响","a":"冰雹。天上掉下的冰疙瘩，夏天雷雨时常有，砸到头会疼。"},
{"c":"自然谜语","q":"雨后天空一座桥，红橙黄绿青蓝紫，挂在天边真好看，太阳出来慢慢消","a":"彩虹。雨后天空一座桥，红橙黄绿青蓝紫，太阳出来慢慢消。"},
{"c":"自然谜语","q":"一道亮光划破天，一闪一闪亮晶晶，打雷之前它先到，照亮夜空一瞬间","a":"闪电。一道亮光，一闪一闪，打雷之前先到，照亮夜空。"},
{"c":"自然谜语","q":"轰隆隆响震天响，好像天上敲大鼓，吓得小孩躲被窝，伴着闪电一起来","a":"打雷。轰隆隆像天上敲大鼓，伴着闪电，小孩吓得躲被窝。"},
{"c":"自然谜语","q":"海上生起大风暴，狂风暴雨巨浪翻，气象台发红色警，船只赶紧躲港湾","a":"台风。海上大风暴，狂风暴雨巨浪，气象台发警报。"},
{"c":"自然谜语","q":"一根柱子天上转，从云层里伸下来，卷起地上万般物，威力无比真可怕","a":"龙卷风。云里伸下柱子，转着卷起地上东西，威力可怕。"},
{"c":"自然谜语","q":"漫天黄沙遮天日，风沙吹得睁不开眼，春天北方常常见，出门要戴口罩帽","a":"沙尘暴。漫天黄沙，风沙吹得睁不开眼，春天北方常见。"},
{"c":"自然谜语","q":"哗啦啦下个不停，街道变成小河流，下水道都排不及，出门要穿大雨靴","a":"暴雨。哗啦啦下不停，街道成小河，下水道排不及。"},
{"c":"自然谜语","q":"鹅毛大片满天飞，一夜之间全白了，树枝压弯了腰，孩子们院中嬉闹。","a":"大雪。鹅毛大雪满天飞，一夜全白，树枝压弯，孩子打雪仗。"},
{"c":"自然谜语","q":"白茫茫一片罩大地，能见度低路难行，空气中灰尘水汽多，冬天常见这天气","a":"雾霾。白茫茫罩大地，能见度低，空气里灰尘水汽多。"},
{"c":"自然谜语","q":"太阳被月亮挡住了，大白天天突然黑，星星出来了鸟儿归巢，百年难得一见","a":"日食。太阳被月亮挡住，大白天突然变黑，星星出现，鸟儿归巢。"},
{"c":"自然谜语","q":"月亮被地球影子遮，圆圆月儿缺了一块，古时候人说天狗吃月亮，敲锣打鼓要救月","a":"月食。月亮被地球影子遮住，圆月缺一块，古人说天狗吃月亮。"},
{"c":"自然谜语","q":"一道亮光划过夜空，赶紧许个愿望吧，转瞬即逝真短暂，星空中最美的过客","a":"流星。一道亮光划过夜空，转瞬即逝，人们赶紧许愿。"},
{"c":"自然谜语","q":"拖着长长尾巴，从遥远太空来，千百年才见一面，人们说它扫把星","a":"彗星。拖着长尾巴从太空来，千百年才见一面，人称扫把星。"},
{"c":"自然谜语","q":"极地夜空舞彩带，绿色红色变幻美，太阳风与磁场相遇，北极南极都能见","a":"极光。极地夜空彩带，绿红变幻，太阳风与磁场相遇形成。"},
{"c":"成语谜语","q":"半夜听见鸡叫，立刻起身舞剑，打一成语。","a":"闻鸡起舞。祖逖和刘琨立志报国，听到鸡叫就起床练剑，后来形容有志者及时奋发。"},
{"c":"成语谜语","q":"一篇赋写成，洛阳的纸都涨价了，打一成语。","a":"洛阳纸贵。左思写成《三都赋》，人们争相传抄，洛阳的纸因此供不应求。"},
{"c":"成语谜语","q":"站在老师门外，雪积了一尺深，打一成语。","a":"程门立雪。杨时和游酢拜见程颐，在门外等候时雪深一尺，形容尊师重道。"},
{"c":"成语谜语","q":"把萤火虫装进袋子，借雪光读书，打一成语。","a":"囊萤映雪。车胤囊萤、孙康映雪，都是家贫仍刻苦读书的典故。"},
{"c":"成语谜语","q":"头发吊在梁上，用锥子刺大腿，打一成语。","a":"悬梁刺股。孙敬悬梁、苏秦刺股，形容用极端方式督促自己勤学。"},
{"c":"成语谜语","q":"在墙上凿一个洞，借邻居家的灯光读书，打一成语。","a":"凿壁偷光。匡衡家贫，凿壁引邻舍烛光读书，形容条件艰苦仍好学。"},
{"c":"成语谜语","q":"为了孩子读书，搬了三次家，打一成语。","a":"孟母三迁。孟母为让孟子有好的成长环境，三次搬家，后来形容重视教育。"},
{"c":"成语谜语","q":"琴声里听出高山和流水，打一成语。","a":"高山流水。俞伯牙弹琴，钟子期能听出高山流水之意，比喻知音难遇。"},
{"c":"成语谜语","q":"曹操带兵行军，士兵口渴，他指着前方说前面有梅林。打一成语。","a":"望梅止渴。曹操用前面有梅子林的想象激励口渴的士兵，士兵想到酸梅就分泌唾液，暂时缓解口渴；比喻用空想安慰自己。"},
{"c":"成语谜语","q":"苻坚在淝水之战登城远望，把山上的草木都当成晋军。打一成语。","a":"草木皆兵。苻坚见八公山上草木晃动，以为都是晋军，形容惊慌时疑神疑鬼。"},
{"c":"成语谜语","q":"项羽被围垓下，夜里听到四周汉军唱楚歌。打一成语。","a":"四面楚歌。项羽以为楚地已被汉军占领，形容孤立无援、四面受敌。"},
{"c":"成语谜语","q":"韩信率军背靠河水列阵，让士兵无路可退，最终取胜。打一成语。","a":"背水一战。韩信在井陉背水列阵，激发将士死战；比喻决一死战。"},
{"c":"成语谜语","q":"徐德言与乐昌公主把铜镜破成两半，各执一半，后来凭半镜重逢。打一成语。","a":"破镜重圆。陈朝将亡，夫妻破镜为信，后来重聚合镜；比喻夫妻失散或离散后重新团聚。"},
{"c":"成语谜语","q":"刘备三次到隆中拜访诸葛亮，请他出山。打一成语。","a":"三顾茅庐。刘备三次到草庐拜访诸葛亮，形容诚心诚意邀请贤才。"},
{"c":"成语谜语","q":"平原君选人赴楚，毛遂主动请求同行。打一成语。","a":"毛遂自荐。毛遂是平原君门客，主动推荐自己随行，比喻自告奋勇。"},
{"c":"成语谜语","q":"虞国和虢国互相依存，晋国先借道灭虢，回师又灭虞。打一成语。","a":"唇亡齿寒。嘴唇没有了，牙齿就会冷；比喻关系密切、互相依存。"},
{"c":"成语谜语","q":"西施心痛皱眉，邻居东施觉得美，也捂着胸口皱眉，结果更难看。打一成语。","a":"东施效颦。东施盲目模仿西施的病态美，反而更丑；比喻生硬模仿。"},
{"c":"成语谜语","q":"燕国少年到邯郸学赵国人走路，没学会，连原来的走法也忘了，只好爬回去。打一成语。","a":"邯郸学步。比喻盲目模仿别人，反而丢掉自己的本领。"},
{"c":"成语谜语","q":"江淹晚年梦见郭璞索回五色笔，此后写诗再无佳句。打一成语。","a":"江郎才尽。江淹年轻时文采出众，晚年才思衰退；比喻才华耗尽。"},
{"c":"成语谜语","q":"蜀汉灭亡后，刘禅在洛阳说这里很快乐，不想念蜀国。打一成语。","a":"乐不思蜀。刘禅被迁洛阳，司马昭问他想不想蜀，他说此间乐，不思蜀；比喻乐而忘返。"},
{"c":"成语谜语","q":"来俊臣问周兴：犯人不说实话怎么办？周兴说用大瓮烤。来俊臣照做，请周兴进去。打一成语。","a":"请君入瓮。来俊臣用周兴自己的酷刑办法对付他；比喻用对方的手段整治对方。"},
{"c":"成语谜语","q":"荆轲献燕国地图给秦王，地图展到最后露出匕首。打一成语。","a":"图穷匕见。图卷展尽，匕首出现；比喻事情发展到最后，真相或本意暴露。"},
{"c":"成语谜语","q":"孔子晚年读《易经》，穿竹简的皮绳断了三次。打一成语。","a":"韦编三绝。韦指熟牛皮绳，三绝是断了三次；形容读书勤奋。"},
{"c":"成语谜语","q":"班超家境贫寒，常替官府抄书，后来掷笔说大丈夫应去边疆立功。打一成语。","a":"投笔从戎。班超扔掉笔去参军，比喻弃文从武。"},
{"c":"成语谜语","q":"卢生在客栈枕着道士的枕头入睡，梦里享尽荣华，醒来小米饭还没熟。打一成语。","a":"黄粱一梦。黄粱是小米；比喻虚幻的好事或欲望破灭。"},
{"c":"成语谜语","q":"曹丕命曹植七步成诗，曹植以煮豆燃豆萁作诗。打一成语。","a":"煮豆燃萁。豆萁是豆茎，煮豆时烧豆茎；比喻兄弟相残。"},
{"c":"成语谜语","q":"楚庄王即位三年不理政事，后来一出手就震惊全国。打一成语。","a":"一鸣惊人。楚庄王以鸟自喻，三年不飞不鸣，一飞冲天、一鸣惊人；比喻平时无声，突然做出惊人成绩。"}
  ],
  iq:[
{"c":"数学思维","q":"如果A@B定义为A×B+A+B，那么(4)@(5)等于多少？","a":"29。4×5+4+5=29。"},
{"c":"逻辑推理","q":"如果P→Q为真，Q→R为假，以下哪个一定正确？A.P为真 B.P为假 C.R为真 D.R为假","a":"D.R为假。Q→R为假意味着Q真且R假。因此R一定为假。"},
{"c":"数学思维","q":"6个人围着一张圆桌坐，只考虑相邻关系、不区分旋转，有多少种坐法？","a":"120种。圆排列数为（6-1）！=5！=120种。"},
{"c":"数学思维","q":"一个水池有甲、乙两个进水管，甲管单独注满需6小时，乙管单独需12小时。两管同时开，几小时注满？","a":"4小时。甲管每小时注入1/6，乙管1/12，合起来1/4，所以4小时注满。"},
{"c":"逻辑推理","q":"下列命题与「只有努力才能成功」等价的是？A.如果努力就能成功 B.如果不努力就不能成功 C.如果成功就努力了 D.B和C都对","a":"D.B和C都对。只有P才Q等价于如果Q则P也等价于如果不P则不Q。"},
{"c":"数学思维","q":"一个2×3的方格网，从左下角走到右上角，每次只能向右或向上走一格，最短路线有多少条？","a":"10条。从5步中选2步向右，路线数为C（5，2）=10条。"},
{"c":"逻辑推理","q":"「并非所有人都通过了考试」的等价命题是？","a":"「有些人没有通过考试」。逻辑上并非所有人都是等价于存在某些人不是。"},
{"c":"逻辑推理","q":"如果A包含于B且B包含于C，以下哪个正确？A.A包含于C B.C包含于A C.A=C D.无法确定","a":"A.A包含于C。集合包含具有传递性。"},
{"c":"数学思维","q":"甲乙两人下棋，胜一局得2分负一局得0分平局各得1分。下了10局后甲得14分。甲至少赢了几局？","a":"4 局。设甲赢 x 局、平 y 局：2x+y=14，x+y≤10。x=4、y=6 时正好 10 局；x=3 时 y=8，超过 10 局，所以至少赢 4 局。"},
{"c":"数学思维","q":"一个数的3倍减去5等于16，这个数是多少？","a":"7。设这个数为x，3x-5=16，3x=21，x=7。"},
{"c":"逻辑推理","q":"一个人说「我正在说谎」，这句话是否构成悖论？为什么？","a":"构成悖论。如果为真则他在说谎所以为假；如果为假则他没有说谎所以为真。无法自洽。"},
{"c":"逻辑推理","q":"甲乙丙三人身高各不相同。甲比乙高，乙比丙矮，丙比甲矮。从高到矮排序。","a":"甲＞丙＞乙。甲比乙高、丙比甲矮，说明甲最高；乙又比丙矮，所以丙居中、乙最矮。"},
{"c":"数学思维","q":"甲、乙、丙三数的平均数是18，甲是乙的2倍，丙比乙多6，乙是多少？","a":"12。三数总和54，设乙为x，甲为2x，丙为x+6，4x+6=54，x=12。"},
{"c":"逻辑推理","q":"已知所有A是B和有些B不是C都为真。以下哪个一定正确？A.有些A不是C B.有些A是C C.所有A是C D.无法确定","a":"D.无法确定。所有A是B，有些B不是C。A全在B中，那些不是C的B可能包含A也可能不包含。"},
{"c":"数学思维","q":"某次会议100人每人至少会英法德语之一。会英语70人会法语50人会德语40人。会英法30人会英德20人会法德15人。三语都会10人。只会英语多少人？","a":"30人。用容斥原理：只会英语=70-30-20+10=30人。"},
{"c":"数学思维","q":"6个人围成一圈，甲和乙必须相邻，有多少种坐法（旋转视为相同）？","a":"48种。把甲乙看成一个整体，圆排列有（5-1）！=24种，甲乙内部2种，共48种。"},
{"c":"逻辑推理","q":"甲乙丙三人排队。甲不在最前，乙不在最后，丙在甲后面。谁排第一？","a":"乙第一。丙在甲后面，而甲又不在最前，所以甲只能排第二、丙排第三；剩下的第一就是乙。"},
{"c":"逻辑推理","q":"「如果明天下雨我就不去公园」的逆否命题是？","a":"「如果我去公园则明天没下雨」。原命题：下雨则不去。逆否：去公园则没下雨。"},
{"c":"逻辑推理","q":"五个海盗分100金币，按等级从高到低依次提议。方案需至少半数赞成（含自己）否则被淘汰。最高等级海盗最多拿多少？","a":"98枚。倒推：剩DE时D提(100,0)通过；剩CDE时C提(99,0,1)通过；剩BCDE时B提(97,0,1,0)通过；A提(98,0,1,0,1)通过。"},
{"c":"逻辑推理","q":"如果所有的A都是B，所有的B都是C，那么以下哪个一定正确？A.所有C都是A B.有些C是A C.所有A都是C D.没有A是C","a":"C.所有A都是C。三段论推理：A包含于B，B包含于C，则A包含于C。"},
{"c":"逻辑推理","q":"甲乙丙丁四人赛跑。已知甲在乙前面，乙在丙前面，丁既不是第一也不是最后。谁第一？","a":"甲第一。甲在乙前、乙在丙前，所以甲、乙、丙三人的先后是甲→乙→丙；丁只能插在中间，无法改变甲第一。"},
{"c":"数学思维","q":"某班男生人数是女生的1.5倍，男生比女生多百分之几？","a":"50%。设女生为100人，男生为150人，多50人，占女生的50%。"},
{"c":"逻辑推理","q":"已知：有些A是B，所有B是C。以下哪个一定正确？A.有些A是C B.所有A是C C.有些C不是A D.没有A是C","a":"A.有些A是C。有些A是B且所有B是C，则有些A是C。这是有效的三段论。"},
{"c":"数学思维","q":"规定A⊕B=A+B-A×B，那么2⊕3等于多少？","a":"-1。2+3-2×3=5-6=-1。"},
{"c":"数学思维","q":"从5名男生和4名女生中选3人，要求至少有1名女生，有多少种选法？","a":"74种。总选法C（9，3）=84，减去全选男生的C（5，3）=10，得74种。"},
{"c":"数学思维","q":"一份稿件，甲单独打需10天，乙单独打需15天。两人合打，几天完成？","a":"6天。两人合打每天完成1/10+1/15=1/6，所以6天完成。"},
{"c":"数学思维","q":"一个3×3方格，从左下角走到右上角，只能向右或向上，且必须经过中心格，有多少条最短路线？","a":"4条。起点到中心有2条，中心到终点有2条，共2×2=4条。"},
{"c":"数学思维","q":"篮球比赛胜一场得2分，负一场得1分。某队比赛10场共得16分，胜了几场？","a":"6场。设胜x场，负10-x场，2x+（10-x）=16，解得x=6。"},
{"c":"数学思维","q":"一个长方形宽是5厘米，长是宽的2倍，周长是多少？","a":"30厘米。长为5×2=10厘米，周长=2×(10+5)=30厘米。"},
{"c":"数学思维","q":"一个分数的分子分母之和是28，约分后是3/4，原分数是多少？","a":"12/16。设原分数为3k/4k，3k+4k=28，k=4，原分数为12/16。"},
{"c":"数学思维","q":"4个人排成一排拍照，甲和乙必须相邻。有多少种排法？","a":"12种。将甲乙看作一人，3个元素排列6种，甲乙内部交换2种，共12种。"},
{"c":"数学思维","q":"甲比乙大6岁，乙比丙大5岁，三人年龄之和为49岁。甲多少岁？","a":"22岁。设丙x岁，则乙x+5岁、甲x+11岁；3x+16=49，x=11，所以甲22岁。"},
{"c":"数学思维","q":"规定 A△B=A×B-A-B，那么 4△3 等于多少？","a":"5。4×3-4-3=5。"},
{"c":"数学思维","q":"4对夫妇围着一张圆桌坐，每对夫妇必须相邻，有多少种坐法？","a":"96种。把每对夫妇看成一个整体，圆排列有3！=6种，每对内部有2种顺序，共6×2⁴=96种。"},
{"c":"数学思维","q":"甲、乙合作6天完成一项工程，甲单独做需10天，乙单独做需几天？","a":"15天。合作每天完成1/6，甲每天1/10，乙每天1/6-1/10=1/15，所以需15天。"},
{"c":"数学思维","q":"一个4×4方格，从左下角走到右上角，只能向右或向上，必须经过正中央的格点，有多少条最短路线？","a":"36条。起点到中央格点有C（4，2）=6条，中央到终点也有6条，共6×6=36条。"},
{"c":"数学思维","q":"足球比赛胜一场得3分，平一场得1分，负一场得0分。某队赛8场保持不败，共得18分，胜了几场？","a":"5场。设胜x场，平8-x场，3x+（8-x）=18，解得x=5。"},
{"c":"数学思维","q":"一个比的比值是3/5，前项和后项之和是32，前项是多少？","a":"12。前项:后项=3:5，共8份，32÷8=4，前项=3×4=12。"},
{"c":"数学思维","q":"一项工程，甲单独做6天完成，乙单独做4天完成，两人合作几天完成？","a":"12/5天（2.4天）。合作效率=1/6+1/4=5/12，时间=1÷5/12=12/5天。"},
{"c":"数学思维","q":"5个人排成一排，甲必须站在正中间，有多少种排法？","a":"24种。甲位置固定，其余4人任意排列，共4！=24种。"},
{"c":"数学思维","q":"规定 A◇B=A²+B²，那么 3◇4 等于多少？","a":"25。3²+4²=25。"},
{"c":"数学思维","q":"从1、2、3、4、5中任取3个不同数字，能组成多少个三位数？","a":"60个。百位有5种选法，十位4种，个位3种，共5×4×3=60个。"},
{"c":"数学思维","q":"一项工程，甲队单独做12天完成，乙队单独做18天完成。甲先做4天后，两队合作，还需几天？","a":"4.8天。甲先完成4/12=1/3，剩2/3；两队合做每天完成1/12+1/18=5/36，需（2/3）÷（5/36）=4.8天。"},
{"c":"数学思维","q":"一个4×4方格，从左下角走到右上角，只能向右或向上，不能经过正中央的格点，有多少条最短路线？","a":"34条。总路线为C（8，4）=70条；经过中央格点的路线有6×6=36条，所以不经过中央格点的有70-36=34条。"},
{"c":"数学思维","q":"甲乙下棋，胜一局得2分，负一局得0分，平局各得1分。下了12局，甲负2局，共得16分，平了几局？","a":"4局。甲胜和平共10局，设胜x局，则平10-x局，2x+（10-x）=16，解得x=6，平4局。"},
{"c":"数学思维","q":"甲乙两地相距240千米，一辆汽车前3小时行了180千米，照这样速度，行完全程还要几小时？","a":"1小时。速度=180÷3=60千米/小时，剩余240-180=60千米，还要1小时。"},
{"c":"数学思维","q":"6个人排成一排，甲和乙不能相邻，有多少种排法？","a":"480种。总排法6！=720，甲乙相邻的排法有2×5！=240，所以不相邻有480种。"},
{"c":"数学思维","q":"4本不同的书分给3个人，每人至少分到1本，有多少种分法？","a":"36种。按2、1、1分：先选拿2本的人3种，再选书C（4，2）=6种，剩下两本分给两人2种，共3×6×2=36种。"},
{"c":"数学思维","q":"甲每小时打60页，乙每小时打40页。一份500页的稿子，两人合打几小时完成？","a":"5小时。两人每小时共打100页，500÷100=5小时。"},
{"c":"数学思维","q":"一个3×4方格中，一共有多少个长方形（含正方形）？","a":"60个。横向4条线选2条有C（4，2）=6种，纵向5条线选2条有C（5，2）=10种，共6×10=60个。"},
{"c":"数学思维","q":"某队比赛9场，胜一场得3分，平一场得1分，负一场得0分，只负1场，共得20分，胜了几场？","a":"6场。胜和平共8场，设胜x场，则平8-x场，3x+（8-x）=20，解得x=6。"},
{"c":"数学思维","q":"一个数的40%是24，这个数是多少？","a":"60。设这个数为x，40%x=24，x=24÷0.4=60。"},
{"c":"数学思维","q":"7个人排成一排，甲必须站在乙的左边（不一定相邻），有多少种排法？","a":"2520种。甲乙左右顺序各占一半，总排法7！=5040，所以甲在乙左边有2520种。"},
{"c":"数学思维","q":"哥哥今年比弟弟大8岁，3年前哥哥的年龄是弟弟的3倍。弟弟今年多少岁？","a":"7岁。设弟弟x岁，哥哥x+8岁；3年前x+5=3（x-3），解得x=7。"},
{"c":"数学思维","q":"6个人分成两组，每组3人，有多少种不同的分法？","a":"10种。从6人中选3人有C（6，3）=20种，两组交换重复计算，所以20÷2=10种。"},
{"c":"数学思维","q":"一个装满水的水池，甲管单独放空需8小时，乙管单独放空需12小时。两管同时开，几小时放空？","a":"4.8小时。两管每小时放掉1/8+1/12=5/24，放空需1÷（5/24）=4.8小时。"},
{"c":"数学思维","q":"把5个相同的小球排成一排，从中选2个涂成红色，有多少种选法？","a":"10种。从5个位置中选2个，组合数C（5，2）=10。"},
{"c":"数学思维","q":"甲乙比赛10局，胜一局得2分，负一局得0分，平局各得1分。甲得16分，且平局比负局多4局，胜了几局？","a":"6局。设负l局，则平l+4局、胜6-2l局，2（6-2l）+（l+4）=16，解得l=0，胜6局。"},
{"c":"数学思维","q":"某商品先涨价20%，再降价20%，现价是原价的百分之几？","a":"96%。设原价100元，涨后120元，再降20%为96元，是原价的96%。"},
{"c":"数学思维","q":"8个人排成一排，甲、乙、丙三人的先后顺序固定，有多少种排法？","a":"6720种。8人全排列8！，甲乙丙三人的相对顺序有3！种，只保留一种，所以8！÷3！=6720。"},
{"c":"数学思维","q":"从A、B、C、D、E五人中选正、副队长各一名，有多少种选法？","a":"20种。正队长5种选法，副队长从剩下4人中选，共5×4=20种。"},
{"c":"数学思维","q":"一项工程，甲单独做15天完成，乙单独做10天完成。甲先做3天，剩下由乙做，乙需几天？","a":"8天。甲3天完成3/15=1/5，剩4/5；乙每天完成1/10，需（4/5）÷（1/10）=8天。"},
{"c":"数学思维","q":"足球赛胜一场3分，平一场1分，负0分。某队赛10场，负2场，得20分，胜了几场？","a":"6场。胜和平共8场，设胜x场，则平8-x场，3x+（8-x）=20，解得x=6。"},
{"c":"数学思维","q":"一个长方形长增加10%，宽减少10%，面积变为原来的百分之几？","a":"99%。设原长10、宽10，面积100；长变11、宽变9，面积99，是原来的99%。"},
{"c":"数学思维","q":"父亲今年40岁，儿子今年12岁。几年后父亲的年龄是儿子的2倍？","a":"16年后。设x年后，40+x=2（12+x），解得x=16。"},
{"c":"数学思维","q":"用0、1、2、3四个数字组成没有重复数字的两位数，有多少个？","a":"9个。十位不能为0，有1、2、3三种；个位从剩下3个数字中选，共3×3=9个。"},
{"c":"数学思维","q":"甲、乙合作4天完成一项工程，甲单独做需12天，乙单独做需几天？","a":"6天。合作每天完成1/4，甲每天1/12，乙每天1/4-1/12=1/6，所以需6天。"},
{"c":"数学思维","q":"甲乙下棋，胜2分负0分平1分。下10局甲得12分，负局比平局少2局，胜了几局？","a":"4局。设负l局，则平l+2局、胜8-2l局，2（8-2l）+（l+2）=12，解得l=2，胜4局。"},
{"c":"数学思维","q":"一个三角形的两个内角分别是65°和45°，第三个角是多少度？","a":"70°。三角形内角和180°，180°-65°-45°=70°。"},
{"c":"数学思维","q":"一个空水池，进水管单独注满需5小时，排水管单独排空需10小时。两管同时开，几小时注满？","a":"10小时。进水管每小时注入1/5，排水管排出1/10，净注入1/10，所以10小时注满。"},
{"c":"数学思维","q":"一个正六边形的每个内角是多少度？","a":"120°。正六边形内角和=(6-2)×180°=720°，每个内角=720°÷6=120°。"},
{"c":"数学思维","q":"甲4分钟做3个零件，乙6分钟做5个零件。两人一起做19个零件，需要几分钟？","a":"12分钟。甲每分钟做3/4个，乙5/6个，合做每分钟19/12个；19÷（19/12）=12分钟。"},
{"c":"数学思维","q":"一个正方体的表面积是54平方厘米，棱长是多少？","a":"3厘米。正方体表面积=6a²，6a²=54，a²=9，a=3。"},
{"c":"数学思维","q":"姐姐今年15岁，妹妹今年9岁。几年前姐姐的年龄是妹妹的3倍？","a":"6年前。设x年前，15-x=3（9-x），解得x=6。"},
{"c":"数学思维","q":"一项工程，甲单独做20天完成，乙单独做30天完成。两人合作，中途甲休息5天，共用几天完成？","a":"15天。设共用t天，乙做t天、甲做t-5天，列式（t-5）/20+t/30=1，解得t=15。"},
{"c":"数学思维","q":"一个圆柱的底面半径是3，高是2，体积是多少？","a":"18π（约56.5）。圆柱体积=πr²h=π×3²×2=18π。"},
{"c":"数学思维","q":"一项工程，甲单独做12天完成，乙单独做24天完成，丙单独做8天完成。三人合作，几天完成？","a":"4天。三人每天完成1/12+1/24+1/8=1/4，所以4天完成。"},
{"c":"数学思维","q":"一个球的半径是3，体积是多少？","a":"36π（约113.1）。球体积=4/3πr³=4/3π×3³=36π。"},
{"c":"数学思维","q":"甲、乙两人的年龄和是35岁，甲比乙大5岁。甲今年多少岁？","a":"20岁。设乙x岁，则甲x+5岁，x+x+5=35，解得x=15，甲20岁。"},
{"c":"数学思维","q":"两个连续奇数的和是48，较小的奇数是多少？","a":"23。设较小为x，较大为x+2，x+x+2=48，x=23。"},
{"c":"数学思维","q":"计算1!+2!+3!+...+4!的和。","a":"33。1!+2!+3!+4!=1+2+6+24=33。"},
{"c":"数学思维","q":"甲、乙两数之和是36，甲是乙的3倍，甲是多少？","a":"27。设乙为x，甲为3x，x+3x=36，x=9，甲=27。"},
{"c":"数学思维","q":"206的各位数字之和是多少？","a":"8。2+0+6=8。"},
{"c":"数学思维","q":"14是质数吗？","a":"不是质数，14=2×7。14除了1和自身，还能被2和7整除。"},
{"c":"数学思维","q":"15的二进制表示是什么？","a":"1111。15=8+4+2+1，对应二进制1111。"},
{"c":"数学思维","q":"286除以8的商和余数分别是多少？","a":"商35余6。35×8=280，286-280=6。"},
{"c":"数学思维","q":"根号71的整数部分是多少？","a":"8。8²=64<=71<81。"},
{"c":"数学思维","q":"解方程：4x+4=7x+15","a":"-11/3。移项得 -3x=11，所以 x=-11/3，约等于 -3.67。"},
{"c":"数学思维","q":"29的3次方是多少？","a":"24389。29^3=24389。"},
{"c":"数学思维","q":"22和28的最大公约数是多少？","a":"2。28=22×1+6，22=6×3+4，6=4×1+2，4=2×2+0，所以最大公约数是2。"},
{"c":"数学思维","q":"如果a=5,b=5,c=8，计算(a²+b²)×c的值。","a":"400。(5²+5²)×8=400。"},
{"c":"数学思维","q":"把32写成几个连续自然数之和（至少2个），有多少种写法？","a":"0 种。32 的奇数因数只有 1，连续和表示只有“32”本身这一项；要求至少 2 项时无解。"},
{"c":"数学思维","q":"243的各位数字的乘积是多少？","a":"24。2×4×3=24。"},
{"c":"数学思维","q":"0.1+0.2等于0.3吗？为什么？","a":"不等于。0.1 和 0.2 在二进制中是无限循环小数，相加得到约 0.30000000000000004；这是浮点数精度误差，不是数学上真的不相等。"},
{"c":"数学思维","q":"25和30的最小公倍数是多少？","a":"150。25×30/gcd=150。"},
{"c":"数学思维","q":"计算C(10,5)的值。","a":"252。组合数C(10,5)=252。"},
{"c":"数学思维","q":"13个人相互握手，每两人握一次。总共握手多少次？","a":"78次。C(13,2)=13×12/2=78次。"},
{"c":"数学思维","q":"求1到70中所有奇数的和。","a":"1225。前35个奇数的和为35²=1225。"},
{"c":"数学思维","q":"3603四舍五入到百位是多少？","a":"3600。看十位3，小于5，百位不变，约3600。"},
{"c":"数学思维","q":"圆周率π的小数点后第21位数字是什么？","a":"2。π≈3.1415926535...第21位是2。"},
{"c":"数学思维","q":"9边形有多少条对角线？","a":"27条。n(n-3)/2=27。"},
{"c":"数学思维","q":"第11个三角数是多少？（三角数：1,3,6,10...）","a":"66。Tn=n(n+1)/2。"},
{"c":"数学思维","q":"计算2^8+3^8+4^8除以5的余数。","a":"3。2^8=256≡1，3^8=6561≡1，4^8=65536≡1；1+1+1=3，3≡3 (mod5)。"},
{"c":"数学思维","q":"求1²+2²+3²+...+4²的和。","a":"30。平方和公式：n(n+1)(2n+1)/6。"},
{"c":"数学思维","q":"一个质数加上2后仍是质数，这个质数最小是多少？","a":"3。2+2=4不是质数；3+2=5是质数，所以最小是3。"},
{"c":"数学思维","q":"计算1!+2!+3!+...+5!的和。","a":"153。前面33加5!=120，总和153。"},
{"c":"数学思维","q":"三个连续整数之和是48，最大的整数是多少？","a":"17。设中间数为x，三数为x-1、x、x+1，和为3x=48，x=16，最大17。"},
{"c":"数学思维","q":"781的各位数字之和是多少？","a":"16。7+8+1=16。"},
{"c":"数学思维","q":"两个质数的和是15，这两个质数的积是多少？","a":"26。15以内的质数中，2+13=15，积为2×13=26。"},
{"c":"数学思维","q":"二进制数1011对应的十进制数是多少？","a":"11。1×2³+0×2²+1×2+1=8+0+2+1=11。"},
{"c":"数学思维","q":"1061除以8的商和余数分别是多少？","a":"商132余5。132×8=1056，1061-1056=5。"},
{"c":"数学思维","q":"根号196的整数部分是多少？","a":"14。14²=196<=196<225。"},
{"c":"数学思维","q":"解方程：5x+8=7x+20","a":"x=-6。移项得-2x=12，x=-6。"},
{"c":"数学思维","q":"11的4次方是多少？","a":"14641。11^4=14641。"},
{"c":"数学思维","q":"把24个苹果和36个梨平均分给若干人，每人分到的苹果和梨同样多，最多能分给多少人？","a":"12人。人数必须是24和36的最大公约数，gcd（24，36）=12。"},
{"c":"数学思维","q":"当x=3时，x²+2x+1等于多少？","a":"16。3²+2×3+1=9+6+1=16。"},
{"c":"数学思维","q":"把57写成几个连续自然数之和（至少2个），有多少种写法？","a":"3 种。57=28+29=18+19+20=7+8+9+10+11+12，共 3 种。"},
{"c":"数学思维","q":"518的各位数字的乘积是多少？","a":"40。5×1×8=40。"},
{"c":"数学思维","q":"一个数除以6余3，除以9也余3，这个数最小是多少？","a":"21。减去3后是6和9的公倍数，最小公倍数18，所以最小是21。"},
{"c":"数学思维","q":"计算C(11,6)的值。","a":"462。组合数C(11,6)=462。"},
{"c":"数学思维","q":"3封不同的信投入4个不同的邮筒，每封信任意投一个邮筒，有多少种投法？","a":"64种。每封信有4种选择，3封信共有4³=64种投法。"},
{"c":"数学思维","q":"1+3+5+...+19等于多少？","a":"100。这是前10个奇数的和，等于10²=100。"},
{"c":"数学思维","q":"7028四舍五入到百位是多少？","a":"7000。看十位2，小于5，百位不变，约7000。"},
{"c":"数学思维","q":"圆周率π的小数点后第16位数字是什么？","a":"2。π≈3.1415926535...第16位是2。"},
{"c":"数学思维","q":"14边形有多少条对角线？","a":"77条。n(n-3)/2=77。"},
{"c":"数学思维","q":"第12个三角数是多少？（三角数：1,3,6,10...）","a":"78。Tn=n(n+1)/2。"},
{"c":"数学思维","q":"计算2^3+3^3+4^3除以5的余数。","a":"4。2^3=8≡3，3^3=27≡2，4^3=64≡4；3+2+4=9，9≡4 (mod5)。"},
{"c":"数学思维","q":"2²+3²+4²等于多少？","a":"29。4+9+16=29。"},
{"c":"数学思维","q":"一个数既是2的倍数又是3的倍数，还是5的倍数，这个数最小是多少？","a":"30。同时是2、3、5的倍数，最小公倍数是30。"},
{"c":"数学思维","q":"6个人排成一排照相，一共有多少种不同排法？","a":"720种。6个人全排列，6!=720。"},
{"c":"数学思维","q":"一件商品先涨价10%，再降价10%，现价是原价的百分之几？","a":"99%。设原价100元，涨后110元，再降10%为99元，是原价的99%。"},
{"c":"数学思维","q":"一张存单编号是1356，四个数字相加是多少？","a":"15。1+3+5+6=15。"},
{"c":"数学思维","q":"最小的三个质数的和是多少？","a":"10。最小的三个质数是2、3、5，和为10。"},
{"c":"数学思维","q":"十进制数12的二进制表示是什么？","a":"1100。12=8+4，对应二进制位从高到低为1100。"},
{"c":"数学思维","q":"1836个苹果，每8个装一袋，能装满多少袋，还剩几个？","a":"商229余4。229×8=1832，1836-1832=4。"},
{"c":"数学思维","q":"一个正方形花坛面积321平方米，边长最多是几米的整数部分？","a":"17米。17²=289≤321<18²=324，整数部分是17。"},
{"c":"数学思维","q":"某数的3倍加5等于它的2倍加12，这个数是多少？","a":"7。设这个数为x，3x+5=2x+12，解得x=7。"},
{"c":"数学思维","q":"2的10次方等于多少？","a":"1024。2的10次方就是10个2相乘，结果是1024。"},
{"c":"数学思维","q":"用长18厘米、宽24厘米的长方形砖铺成一个正方形，最少需要多少块？","a":"12块。正方形边长取18和24的最小公倍数72，需要（72÷18）×（72÷24）=4×3=12块。"},
{"c":"数学思维","q":"一个正方形边长7厘米，它的面积是多少？","a":"49平方厘米。正方形面积等于边长×边长，7×7=49平方厘米。"},
{"c":"数学思维","q":"三个连续自然数的和是42，最小的数是多少？","a":"13。设最小为x，则x+（x+1）+（x+2）=42，解得x=13。"},
{"c":"数学思维","q":"一个保险柜密码是793，三个数字相乘是多少？","a":"189。7×9×3=189。"},
{"c":"数学思维","q":"两个数的最大公约数是4，最小公倍数是24，其中一个数是8，另一个数是多少？","a":"12。两数乘积等于最大公约数×最小公倍数=4×24=96，另一个数96÷8=12。"},
{"c":"数学思维","q":"从12名同学中选7名参加竞赛，有多少种选法？","a":"792种。C(12,7)=792。"},
{"c":"数学思维","q":"前12个正奇数的和是多少？","a":"144。前n个奇数之和为n²，12²=144。"},
{"c":"数学思维","q":"某镇有10453人，精确到百人约多少人？","a":"10500人。十位是5，向百位进1。"},
{"c":"数学思维","q":"半径2厘米的圆，周长约是多少厘米？（π取3.14）","a":"12.56厘米。2×3.14×2=12.56。"},
{"c":"数学思维","q":"从6种不同的水果中选3种做拼盘，有多少种选法？","a":"20种。只选不排序，组合数为C（6，3）=20种。"},
{"c":"数学思维","q":"计算2^4+3^4+4^4除以5的余数。","a":"3。2^4=16≡1，3^4=81≡1，4^4=256≡1；1+1+1=3，3≡3 (mod5)。"},
{"c":"数学思维","q":"3²+4²+5²等于多少？","a":"50。9+16+25=50。"},
{"c":"数学思维","q":"一个三位数，各位数字之和是15，百位数字是4，十位数字比个位数字大1，这个三位数是多少？","a":"465。设个位为x，十位为x+1；4+(x+1)+x=15，x=5，十位为6，数是465。"},
{"c":"数学思维","q":"7种不同颜色的珠子排成一排，有多少种排法？","a":"42种。7!/5!=7×6=42。"},
{"c":"数学思维","q":"正方形边长增加20%，面积增加百分之几？","a":"44%。设原边长1，新边长1.2，面积1.44，比原来增加44%。"},
{"c":"数学思维","q":"一本书的页码是1931，各位数字之和是多少？","a":"14。1+9+3+1=14。"},
{"c":"数学思维","q":"一个质数加上10后仍是质数，这个质数最小是多少？","a":"3。2+10=12不是质数，3+10=13是质数，所以最小是3。"},
{"c":"数学思维","q":"二进制数1011与110相加，结果是多少？","a":"10001。1011（二进制）=11，110（二进制）=6，11+6=17，写成二进制是10001。"},
{"c":"数学思维","q":"2611本练习册，每8本捆一包，能捆多少包，还剩几本？","a":"商326余3。326×8=2608，2611-2608=3。"},
{"c":"数学思维","q":"446块正方形瓷砖拼成一个大正方形，每边最多用多少块整砖？","a":"21块。21²=441≤446<22²=484，所以最多21块。"},
{"c":"数学思维","q":"一个数的4倍减7等于它的2倍加9，求这个数。","a":"8。4x-7=2x+9，移项得2x=16，x=8。"},
{"c":"数学思维","q":"3的5次方等于多少？","a":"243。3×3×3×3×3=243。"},
{"c":"数学思维","q":"把36支铅笔和48本练习本平均奖给若干学生，最多能奖给多少人？","a":"12人。人数取36和48的最大公约数，gcd（36，48）=12。"},
{"c":"数学思维","q":"一个长方形长8厘米、宽6厘米，它的面积比周长多多少？","a":"20。面积8×6=48，周长2×（8+6）=28，相差20。"},
{"c":"数学思维","q":"四个连续自然数的和是58，最大的数是多少？","a":"16。设最小为x，4x+6=58，解得x=13，最大16。"},
{"c":"数学思维","q":"一张卡号1068，四个数字相乘是多少？","a":"0。1×0×6×8=0。"},
{"c":"数学思维","q":"甲每隔6天去一次图书馆，乙每隔9天去一次，今天两人同去，至少几天后再次同去？","a":"18天。再次同去经过的天数是6和9的最小公倍数，lcm（6，9）=18。"},
{"c":"数学思维","q":"从13种颜料中选8种调色，有多少种选法？","a":"1287种。C(13,8)=1287。"},
{"c":"数学思维","q":"从1开始，连续7个奇数的和是多少？","a":"49。连续n个奇数之和为n²，7²=49。"},
{"c":"数学思维","q":"某校有13878名学生，精确到百人约多少名？","a":"13900名。十位7，向百位进1。"},
{"c":"数学思维","q":"直径10厘米的圆，面积约是多少平方厘米？（π取3.14）","a":"78.5平方厘米。半径5厘米，3.14×5²=78.5。"},
{"c":"数学思维","q":"3个人见面时每两人握手一次，一共握手多少次？","a":"3次。3×2÷2=3。"},
{"c":"数学思维","q":"计算2^5+3^5+4^5除以5的余数。","a":"4。2^5=32≡2，3^5=243≡3，4^5=1024≡4；2+3+4=9，9≡4 (mod5)。"},
{"c":"数学思维","q":"一个长方形长9厘米、宽4厘米，面积是多少？","a":"36平方厘米。面积=长×宽=9×4=36平方厘米。"},
{"c":"数学思维","q":"一个数除以3余2，除以4余3，除以5余4，这个最小正整数是多少？","a":"59。这个数加1后同时被3、4、5整除，最小公倍数是60，所以数是60-1=59。"},
{"c":"数学思维","q":"8!的末尾有几个0？","a":"1个。8!=40320，末尾有1个0。"},
{"c":"数学思维","q":"一个数除以5余3，除以7余2，这个最小正整数是多少？","a":"23。5的倍数加3：3、8、13、18、23；其中23除以7余2，最小是23。"},
{"c":"数学思维","q":"某户门牌号2506，各位数字之和是多少？","a":"13。2+5+0+6=13。"},
{"c":"数学思维","q":"20以内最大的质数是多少？","a":"19。20以内比19大的数没有质数，19只能被1和19整除。"},
{"c":"数学思维","q":"十进制数50的二进制表示是什么？","a":"110010。50=32+16+2，对应二进制位为110010。"},
{"c":"数学思维","q":"3386块积木，每8块装一盒，能装满多少盒，还剩几块？","a":"商423余2。423×8=3384，3386-3384=2。"},
{"c":"数学思维","q":"一块正方形菜地面积571平方米，边长整数部分是多少米？","a":"23米。23²=529≤571<24²=576，整数部分23。"},
{"c":"数学思维","q":"某数的5倍加3等于它的3倍加17，求这个数。","a":"7。5x+3=3x+17，2x=14，x=7。"},
{"c":"数学思维","q":"5的4次方等于多少？","a":"625。5×5×5×5=625。"},
{"c":"数学思维","q":"当a=5、b=2时，a²-b²等于多少？","a":"21。5²-2²=25-4=21。"},
{"c":"数学思维","q":"五个连续奇数的和是55，中间的数是多少？","a":"11。五个连续奇数关于中间数对称，平均数就是中间数，55÷5=11。"},
{"c":"数学思维","q":"一个快件编号1343，数字相乘是多少？","a":"36。1×3×4×3=36。"},
{"c":"数学思维","q":"从14本不同的书中选9本带走，有多少种选法？","a":"2002种。C(14,9)=2002。"},
{"c":"数学思维","q":"1+3+5+...+99等于多少？","a":"2500。这是前50个奇数的和，50²=2500。"},
{"c":"数学思维","q":"某地年产量17303吨，精确到百吨约多少吨？","a":"17300吨。看十位是0，小于5，百位不变，所以约17300吨。"},
{"c":"数学思维","q":"半径3厘米的圆，面积约是多少平方厘米？（π取3.14）","a":"28.26平方厘米。3.14×3²=28.26。"},
{"c":"数学思维","q":"5个人排成一排，甲不站在两端，有多少种排法？","a":"72种。甲可站中间3个位置，其余4人任意排列，共3×4！=72种。"},
{"c":"数学思维","q":"计算2^6+3^6+4^6除以5的余数。","a":"4。2^6=64≡4，3^6=729≡4，4^6=4096≡1；4+4+1=9，9≡4 (mod5)。"},
{"c":"数学思维","q":"一个直角三角形两条直角边分别是5和12，斜边是多少？","a":"13。由勾股定理，斜边为√（5²+12²）=√169=13。"},
{"c":"数学思维","q":"一个两位数，个位数字是十位数字的2倍，两个数字之和是9，这个两位数是多少？","a":"36。设十位为x，个位为2x，x+2x=9，x=3，数是36。"},
{"c":"数学思维","q":"9!的各位数字之和是多少？","a":"27。9!=362880，各位数字之和为3+6+2+8+8+0=27。"},
{"c":"数学思维","q":"从1到100中，能被3和5同时整除的数有多少个？","a":"6个。同时被3和5整除即被15整除：15、30、45、60、75、90。"},
{"c":"数学思维","q":"一张发票编号3081，各位数字之和是多少？","a":"12。3+0+8+1=12。"},
{"c":"数学思维","q":"19是质数吗？","a":"是质数。19只能被1和19整除，没有别的因数。"},
{"c":"数学思维","q":"20的二进制表示是什么？","a":"10100。20=16+4，对应二进制10100。"},
{"c":"数学思维","q":"4161张纸，每8张叠成一摞，能叠多少摞，还剩几张？","a":"商520余1。520×8=4160，4161-4160=1。"},
{"c":"数学思维","q":"用696个同样的小正方形拼成尽量大的正方形，每边最多几个？","a":"26个。26²=676≤696<27²=729。"},
{"c":"数学思维","q":"一个数的2倍加10，比它的4倍少6，求这个数。","a":"8。设这个数为x，2x+10=4x-6，16=2x，x=8。"},
{"c":"数学思维","q":"2的6次方乘2的3次方等于2的几次方？","a":"2的9次方。同底数幂相乘指数相加，6+3=9，所以等于2的9次方，即512。"},
{"c":"数学思维","q":"一个正方形边长9厘米，它的周长是多少？","a":"36厘米。正方形周长等于边长×4，9×4=36厘米。"},
{"c":"数学思维","q":"三个连续偶数的和是36，最大的数是多少？","a":"14。三个连续偶数平均数为12，最大为14。"},
{"c":"数学思维","q":"一个储物柜密码1618，数字相乘是多少？","a":"48。1×6×1×8=48。"},
{"c":"数学思维","q":"从15名队员中选10名上场，有多少种选法？","a":"3003种。C(15,10)=3003。"},
{"c":"数学思维","q":"从1到25中所有奇数的和是多少？","a":"169。1到25有13个奇数，和为13²=169。"},
{"c":"数学思维","q":"某市有20728辆车，精确到百辆约多少辆？","a":"20700辆。看十位是2，小于5，百位不变，所以约20700辆。"},
{"c":"数学思维","q":"一个圆的周长是31.4厘米，半径是多少厘米？（π取3.14）","a":"5厘米。2×3.14×r=31.4，r=5。"},
{"c":"数学思维","q":"10条直线两两相交，且没有三条交于同一点，最多有多少个交点？","a":"45个。每两条直线产生一个交点，共C（10，2）=45个。"},
{"c":"数学思维","q":"计算2^7+3^7+4^7除以5的余数。","a":"4。2^7=128≡3，3^7=2187≡2，4^7=16384≡4；3+2+4=9，9≡4 (mod5)。"},
{"c":"数学思维","q":"一个圆的半径是5，面积是多少？","a":"25π（约78.5）。圆面积=πr²=π×5²=25π。"},
{"c":"数学思维","q":"一个数的2/5是30，这个数是多少？","a":"75。这个数=30÷(2/5)=30×5/2=75。"},
{"c":"数学思维","q":"10!等于多少？","a":"3628800。10!=10×9×…×1=3628800。"},
{"c":"数学思维","q":"甲比乙多20%，乙比丙少20%，甲是丙的百分之几？","a":"96%。设丙为100，乙为80，甲比乙多20%为96，所以甲是丙的96%。"},
{"c":"数学思维","q":"一辆车的车牌号3656，数字之和是多少？","a":"20。3+6+5+6=20。"},
{"c":"数学思维","q":"两个连续质数的和是12，这两个质数分别是多少？","a":"5和7。连续质数5和7的和是12，且都只能被1和自身整除。"},
{"c":"数学思维","q":"4936个零件，每8个装一箱，能装多少箱，还剩几个？","a":"商617余0。617×8=4936，正好装完。"},
{"c":"数学思维","q":"正方形广场面积821平方米，边长整数部分是多少米？","a":"28米。28²=784≤821<29²=841。"},
{"c":"数学思维","q":"某数的7倍减5，比它的4倍多16，求这个数。","a":"7。7x-5=4x+16，3x=21，x=7。"},
{"c":"数学思维","q":"10的6次方等于多少？","a":"1000000。10的6次方是1后面6个0，即1000000。"},
{"c":"数学思维","q":"当x=2、y=5时，3x²+y等于多少？","a":"17。3×2²+5=3×4+5=17。"},
{"c":"数学思维","q":"两个连续自然数的积是30，较小的数是多少？","a":"5。5×6=30，且两数连续，所以较小的是5。"},
{"c":"数学思维","q":"一张票据编号1893，数字相乘是多少？","a":"216。1×8×9×3=216。"},
{"c":"数学思维","q":"从16道题中选11道作答，有多少种选法？","a":"4368种。C(16,11)=4368。"},
{"c":"数学思维","q":"1+3+5+...+31等于多少？","a":"256。1到31有16个奇数，和为16²=256。"},
{"c":"数学思维","q":"某场馆有24153个座位，精确到百个约多少个？","a":"24200个。十位5，向百位进1。"},
{"c":"数学思维","q":"6个点中任意三点不共线，两两连线，一共能连多少条线段？","a":"15条。C(6,2)=15。"},
{"c":"数学思维","q":"一个2×2方格中，所有正方形（含大小两种）的面积之和是多少？每小格面积为1。","a":"5。4个小正方形面积各1，外框大正方形面积4，共5。"},
{"c":"数学思维","q":"某商品打七折后是63元，原价是多少？","a":"90元。七折即原价的70%，63÷0.7=90。"},
{"c":"数学思维","q":"11!除以9!等于多少？","a":"110。11!/9!=11×10=110。"},
{"c":"数学思维","q":"一个两位数，十位数字比个位数字大3，两个数字之和是11，这个两位数是多少？","a":"74。设个位为x，十位为x+3，x+x+3=11，x=4，十位为7，数是74。"},
{"c":"数学思维","q":"一个储物柜编号4231，各位数字之和是多少？","a":"10。4+2+3+1=10。"},
{"c":"数学思维","q":"一个两位数，十位和个位都是质数，且这个两位数本身也是质数，最小是多少？","a":"23。个位和十位只能取2、3、5、7；从小到大检验，23是第一个本身也为质数的两位数。"},
{"c":"数学思维","q":"5711枚硬币，每8枚卷成一卷，能卷多少卷，还剩几枚？","a":"商713余7。713×8=5704，5711-5704=7。"},
{"c":"数学思维","q":"946块地砖铺成正方形，每边最多铺多少块整砖？","a":"30块。30²=900≤946<31²=961。"},
{"c":"数学思维","q":"某数的3倍加8，正好是它的5倍减4，求这个数。","a":"6。3x+8=5x-4，12=2x，x=6。"},
{"c":"数学思维","q":"4的3次方等于多少？","a":"64。4×4×4=64。"},
{"c":"数学思维","q":"一个直角三角形两条直角边分别是3和4，斜边是多少？","a":"5。由勾股定理，斜边为√（3²+4²）=√25=5。"},
{"c":"数学思维","q":"三个连续自然数的积是120，最小的数是多少？","a":"4。4×5×6=120，三个数连续，所以最小是4。"},
{"c":"数学思维","q":"一个房间编号2168，数字相乘是多少？","a":"96。2×1×6×8=96。"},
{"c":"数学思维","q":"从17个人中选12个人组成小队，有多少种选法？","a":"6188种。C(17,12)=6188。"},
{"c":"数学思维","q":"某图书印数27578册，精确到百册约多少册？","a":"27600册。十位7，向百位进1。"},
{"c":"数学思维","q":"7支球队进行单循环比赛，每两队赛一场，一共要赛多少场？","a":"21场。7×6÷2=21。"},
{"c":"数学思维","q":"一个3×3方格中，一共有多少个正方形？","a":"14个。边长为1的有9个，边长2的有4个，边长3的有1个，共14个。"},
{"c":"数学思维","q":"一个长方形的长是宽的3倍，周长是48厘米，面积是多少？","a":"108平方厘米。设宽为w，长为3w，2(3w+w)=48，w=6，长18，面积108。"},
{"c":"数学思维","q":"从7个人中选3个人排成一排，有多少种排法？","a":"210种。排列数P（7，3）=7×6×5=210。"},
{"c":"数学思维","q":"一个数的1/3等于另一个数的1/4，这两个数的比是多少？","a":"3:4。设两数为a、b，a/3=b/4，所以a:b=3:4。"},
{"c":"数学思维","q":"一份快递单号4806，数字之和是多少？","a":"18。4+8+0+6=18。"},
{"c":"数学思维","q":"6486颗糖，每8颗装一袋，能装多少袋，还剩几颗？","a":"商810余6。810×8=6480，6486-6480=6。"},
{"c":"数学思维","q":"正方形草地面积1071平方米，边长整数部分是多少米？","a":"32米。32²=1024≤1071<33²=1089。"},
{"c":"数学思维","q":"某数的6倍减2，比它的2倍多18，求这个数。","a":"5。6x-2=2x+18，4x=20，x=5。"},
{"c":"数学思维","q":"6的3次方等于多少？","a":"216。6×6×6=216。"},
{"c":"数学思维","q":"一个正方体棱长4厘米，表面积是多少平方厘米？","a":"96平方厘米。正方体有6个面，每面4×4=16，表面积6×16=96平方厘米。"},
{"c":"数学思维","q":"一个包裹单号2443，数字相乘是多少？","a":"96。2×4×4×3=96。"},
{"c":"数学思维","q":"某水库蓄水31003立方米，精确到百立方米约多少？","a":"31000立方米。看十位是0，小于5，百位不变，所以约31000立方米。"},
{"c":"数学思维","q":"用1、2、3、4组成没有重复数字的四位数，其中偶数有多少个？","a":"12个。个位只能是2或4，有2种；其余三位由剩下3个数字排列，共2×3！=12个。"},
{"c":"数学思维","q":"一个正方体的棱长总和是36厘米，它的体积是多少？","a":"27立方厘米。正方体有12条棱，棱长36÷12=3厘米，体积3³=27。"},
{"c":"数学思维","q":"从10个人中选3个人组成小组，有多少种选法？","a":"120种。组合数C（10，3）=120。"},
{"c":"数学思维","q":"用一根长48厘米的铁丝围成一个正方形，面积是多少？","a":"144平方厘米。周长48厘米，边长48÷4=12厘米，面积12²=144平方厘米。"},
{"c":"数学思维","q":"一张门票编号5381，各位数字之和是多少？","a":"17。5+3+8+1=17。"},
{"c":"数学思维","q":"7261米布，每8米做一套衣服，能做多少套，还剩几米？","a":"商907余5。907×8=7256，7261-7256=5。"},
{"c":"数学思维","q":"1196个小方块拼成正方形，每边最多几个？","a":"34个。34²=1156≤1196<35²=1225。"},
{"c":"数学思维","q":"一个数的2倍加7等于它本身加15，求这个数。","a":"8。2x+7=x+15，x=8。"},
{"c":"数学思维","q":"2的8次方等于多少？","a":"256。2×2×2×2×2×2×2×2=256。"},
{"c":"数学思维","q":"当a=6、b=8时，a²+b²等于多少？","a":"100。6²+8²=36+64=100。"},
{"c":"数学思维","q":"一张借书卡号2718，数字相乘是多少？","a":"112。2×7×1×8=112。"},
{"c":"数学思维","q":"某工厂月产34428件，精确到百件约多少件？","a":"34400件。看十位是2，小于5，百位不变，所以约34400件。"},
{"c":"数学思维","q":"6个点中任意三点不共线，能组成多少个三角形？","a":"20个。每3个点确定一个三角形，组合数C（6，3）=20。"},
{"c":"数学思维","q":"一个等边三角形的周长是18厘米，高是多少厘米？","a":"3√3厘米（约5.2）。边长18÷3=6厘米，高=6×√3/2=3√3。"},
{"c":"数学思维","q":"14!除以12!等于多少？","a":"182。14!/12!=14×13=182。"},
{"c":"数学思维","q":"一个长方形周长40厘米，长比宽多4厘米，面积是多少？","a":"96平方厘米。长+宽=20，长=宽+4，得宽8、长12，面积96平方厘米。"},
{"c":"数学思维","q":"一台机器的编号5956，各位数字之和是多少？","a":"25。5+9+5+6=25。"},
{"c":"数学思维","q":"8036本书，每8本打一包，能打多少包，还剩几本？","a":"商1004余4。1004×8=8032，8036-8032=4。"},
{"c":"数学思维","q":"正方形水池面积1321平方米，边长整数部分是多少米？","a":"36米。36²=1296≤1321<37²=1369。"},
{"c":"数学思维","q":"某数的4倍加6等于它的3倍加13，求这个数。","a":"7。4x+6=3x+13，x=7。"},
{"c":"数学思维","q":"3的4次方乘3的2次方等于3的几次方？","a":"3的6次方。同底数幂相乘指数相加，4+2=6，所以等于3的6次方，即729。"},
{"c":"数学思维","q":"一个长方形长10厘米、宽4厘米，面积是多少？","a":"40平方厘米。面积=长×宽=10×4=40平方厘米。"},
{"c":"数学思维","q":"一个密码锁编号2993，数字相乘是多少？","a":"486。2×9×9×3=486。"},
{"c":"数学思维","q":"某景区年接待37853人，精确到百人约多少人？","a":"37900人。十位5，向百位进1。"},
{"c":"数学思维","q":"5个点中，A、B、C三点在同一直线上，其余任意三点不共线。任取3个点，能组成多少个三角形？","a":"9个。5点取3点共C（5，3）=10组，其中A、B、C一组不能成三角形，所以10-1=9个。"},
{"c":"数学思维","q":"一个圆锥的底面半径是3，高是4，体积是多少？","a":"12π（约37.7）。圆锥体积=1/3πr²h=1/3π×3²×4=12π。"},
{"c":"数学思维","q":"3!加4!等于多少？","a":"30。3!+4!=6+24=30。"},
{"c":"数学思维","q":"一个圆的半径扩大到原来的3倍，面积扩大到原来的几倍？","a":"9倍。圆面积=πr²，半径变3r，面积变9πr²，是原来的9倍。"},
{"c":"数学思维","q":"一张会员卡号6531，各位数字之和是多少？","a":"15。6+5+3+1=15。"},
{"c":"数学思维","q":"8811个瓶盖，每8个装一盒，能装多少盒，还剩几个？","a":"商1101余3。1101×8=8808，8811-8808=3。"},
{"c":"数学思维","q":"1446块瓷砖拼成正方形，每边最多多少块？","a":"38块。38²=1444≤1446<39²=1521。"},
{"c":"数学思维","q":"一个数的5倍减4等于它的2倍加11，求这个数。","a":"5。5x-4=2x+11，3x=15，x=5。"},
{"c":"数学思维","q":"7的3次方等于多少？","a":"343。7×7×7=343。"},
{"c":"数学思维","q":"一个正方形的周长是20厘米，面积是多少？","a":"25平方厘米。边长20÷4=5，面积5×5=25平方厘米。"},
{"c":"数学思维","q":"一张准考证号3268，数字相乘是多少？","a":"288。3×2×6×8=288。"},
{"c":"数学思维","q":"某公司年收入41278元，精确到百元约多少元？","a":"41300元。十位7，向百位进1。"},
{"c":"数学思维","q":"从8名男生和6名女生中选2人，要求至少有1名女生，有多少种选法？","a":"63种。总选法C（14，2）=91，减去全选男生的C（8，2）=28，得63种。"},
{"c":"数学思维","q":"一个扇形所在圆的半径是6，圆心角是60°，面积是多少？","a":"6π（约18.8）。扇形面积=60/360×π×6²=6π。"},
{"c":"数学思维","q":"一个直角三角形的一条直角边是6，斜边是10，另一条直角边是多少？","a":"8。由勾股定理，另一条直角边=√(10²-6²)=√64=8。"},
{"c":"数学思维","q":"一间教室门牌7106，各位数字之和是多少？","a":"14。7+1+0+6=14。"},
{"c":"数学思维","q":"9586颗珠子，每8颗串一串，能串多少串，还剩几颗？","a":"商1198余2。1198×8=9584，9586-9584=2。"},
{"c":"数学思维","q":"正方形果园面积1571平方米，边长整数部分是多少米？","a":"39米。39²=1521≤1571<40²=1600。"},
{"c":"数学思维","q":"一个数的3倍加7不大于22，这个数最大是多少？","a":"5。3x+7≤22，3x≤15，x≤5。"},
{"c":"数学思维","q":"当x=7时，2x²-3等于多少？","a":"95。2×7²-3=2×49-3=98-3=95。"},
{"c":"数学思维","q":"一个货架编号3543，数字相乘是多少？","a":"180。3×5×4×3=180。"},
{"c":"数学思维","q":"某粮库存粮44703公斤，精确到百公斤约多少？","a":"44700公斤。看十位是0，小于5，百位不变，所以约44700公斤。"},
{"c":"数学思维","q":"一个数加上它的25%等于50，这个数是多少？","a":"40。设这个数为x，x+25%x=1.25x=50，x=40。"},
{"c":"数学思维","q":"一个多边形的内角和是720°，它是几边形？","a":"六边形。多边形内角和=(n-2)×180°，(n-2)×180°=720°，n-2=4，n=6。"},
{"c":"数学思维","q":"一张收据编号7681，各位数字之和是多少？","a":"22。7+6+8+1=22。"},
{"c":"数学思维","q":"10361张照片，每8张放一页，能放多少页，还剩几张？","a":"商1295余1。1295×8=10360，10361-10360=1。"},
{"c":"数学思维","q":"1696个棋子摆成正方形，每边最多多少个？","a":"41个。41²=1681≤1696<42²=1764。"},
{"c":"数学思维","q":"一个数的3倍加12，等于它的6倍少3，求这个数。","a":"5。3x+12=6x-3，15=3x，x=5。"},
{"c":"数学思维","q":"一个等腰直角三角形两条直角边都是6厘米，面积是多少？","a":"18平方厘米。面积=6×6÷2=18平方厘米。"},
{"c":"数学思维","q":"一张银行卡尾号3818，数字相乘是多少？","a":"192。3×8×1×8=192。"},
{"c":"数学思维","q":"某路段长48128米，精确到百米约多少米？","a":"48100米。看十位是2，小于5，百位不变，所以约48100米。"},
{"c":"数学思维","q":"一个数减少20%后是48，原数是多少？","a":"60。设这个数为x，x-20%x=0.8x=48，x=60。"},
{"c":"数学思维","q":"一个圆柱的底面半径是2，高是5，侧面积是多少？","a":"20π（约62.8）。圆柱侧面积=2πrh=2π×2×5=20π，约62.8。"},
{"c":"数学思维","q":"一张车票编号8256，各位数字之和是多少？","a":"21。8+2+5+6=21。"},
{"c":"数学思维","q":"11136块砖，每8块码成一垛，能码多少垛，还剩几块？","a":"商1392余0。1392×8=11136，正好码完。"},
{"c":"数学思维","q":"正方形展厅面积1821平方米，边长整数部分是多少米？","a":"42米。42²=1764≤1821<43²=1849。"},
{"c":"数学思维","q":"某数的9倍减4，比它的4倍多21，求这个数。","a":"5。9x-4=4x+21，5x=25，x=5。"},
{"c":"数学思维","q":"当a=4、b=3时，（a+b）²等于多少？","a":"49。先算a+b=7，再平方得49。"},
{"c":"数学思维","q":"一个编号4093，数字相乘是多少？","a":"0。4×0×9×3=0。"},
{"c":"数学思维","q":"某县有51553户，精确到百户约多少户？","a":"51600户。十位5，向百位进1。"},
{"c":"图形推理","q":"3个圆两两相交，最多有几个交点？","a":"6个。每两个圆最多2个交点，C(3,2)×2=6个。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\">\n      <circle cx=\"128\" cy=\"92\" r=\"62\"/>\n      <circle cx=\"232\" cy=\"92\" r=\"62\"/>\n      <circle cx=\"180\" cy=\"158\" r=\"62\"/></svg>","svgAlt":"三个大小相同、两两相交的圆。"},
{"c":"图形推理","q":"5条直线两两相交（无三线共点），形成多少个交点？","a":"10个。C(5,2)=5×4/2=10。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\">\n      <path d=\"M180 28 L228 176 L102 85 L258 85 L132 176 Z\" stroke-width=\"2.4\"/></svg>","svgAlt":"五条直线构成的五角星，任意两条直线都相交且没有三线共点。"},
{"c":"图形推理","q":"正5边形有多少条对称轴？","a":"5条。正5边形有5条对称轴。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"180,27 254,81 226,168 134,168 106,81\"/><line x1=\"180\" y1=\"27\" x2=\"180\" y2=\"168\" stroke-dasharray=\"5 4\" opacity=\".55\"/><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">正五边形与一条对称轴</text></svg>","svgAlt":"一个正五边形，画出一条竖直的对称轴。"},
{"c":"图形推理","q":"两个相似三角形的面积比是1:7，它们的边长比是多少？","a":"1:2.65。边长比等于面积比的平方根，√7≈2.65。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"40,180 120,180 80,80\"/><polygon points=\"150,180 310,180 230,20\"/><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">面积比 1:7</text></svg>","svgAlt":"一大一小两个相似三角形，标注面积比为1比7。"},
{"c":"图形推理","q":"正7边形的每个外角是多少度？","a":"51.4°。外角和360°，每个外角=360°/7≈51.4°。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"180,30 239,58 253,122 213,173 147,173 107,122 121,58\"/><line x1=\"213\" y1=\"173\" x2=\"270\" y2=\"173\" stroke-dasharray=\"5 4\" opacity=\".55\"/><text x=\"285\" y=\"160\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"13\" text-anchor=\"middle\">外角 ?</text><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">正七边形</text></svg>","svgAlt":"一个正七边形，延长一条边并标出外角。"},
{"c":"图形推理","q":"一个三角形三个内角的度数比为4:4:5，最大角约多少度？","a":"约69.2°。总份数13，最大角占5份，180×5/13≈69.2°。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\">\n      <polygon points=\"38,185 322,185 180,35\"/>\n      <text x=\"180\" y=\"26\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">5x</text>\n      <text x=\"62\" y=\"180\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">4x</text>\n      <text x=\"298\" y=\"180\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">4x</text></svg>","svgAlt":"三角形三个内角分别标为4x、4x、5x。"},
{"c":"图形推理","q":"在2×2的方格中，有多少个长方形（含正方形）？","a":"9个。选两横边C(3,2)×选两竖边C(3,2)=9。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\">\n      <line x1=\"80\" y1=\"55\" x2=\"80\" y2=\"175\" opacity=\".55\"/><line x1=\"170\" y1=\"55\" x2=\"170\" y2=\"175\" opacity=\".55\"/><line x1=\"260\" y1=\"55\" x2=\"260\" y2=\"175\" opacity=\".55\"/><line x1=\"80\" y1=\"55\" x2=\"260\" y2=\"55\" opacity=\".55\"/><line x1=\"80\" y1=\"115\" x2=\"260\" y2=\"115\" opacity=\".55\"/><line x1=\"80\" y1=\"175\" x2=\"260\" y2=\"175\" opacity=\".55\"/>\n      <rect x=\"80\" y=\"55\" width=\"180\" height=\"120\" opacity=\".9\"/>\n      <text x=\"170\" y=\"203\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">2×2 方格</text></svg>","svgAlt":"一个2×2的方格图，共4个小方格。"},
{"c":"图形推理","q":"下列哪个图形不是轴对称图形？A.平行四边形 B.等腰梯形 C.菱形 D.正方形","a":"A.平行四边形。一般的平行四边形没有对称轴。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\">\n      <polygon points=\"20,40 100,40 80,95 0,95\"/><text x=\"50\" y=\"115\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">A</text>\n      <polygon points=\"190,95 290,95 270,40 210,40\"/><text x=\"240\" y=\"115\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">B</text>\n      <polygon points=\"60,125 105,165 60,205 15,165\"/><text x=\"60\" y=\"218\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">C</text>\n      <rect x=\"225\" y=\"125\" width=\"60\" height=\"60\"/><text x=\"255\" y=\"205\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">D</text></svg>","svgAlt":"四个候选图形：A平行四边形、B等腰梯形、C菱形、D正方形。"},
{"c":"图形推理","q":"一个6×6的棋盘从左下角到右上角，每次只能向右或向上。有多少种走法？","a":"924种。共需走12步，其中6步向右、6步向上。组合数C(12,6)=924。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\">\n      <line x1=\"45\" y1=\"25\" x2=\"45\" y2=\"205\" opacity=\".55\"/><line x1=\"90\" y1=\"25\" x2=\"90\" y2=\"205\" opacity=\".55\"/><line x1=\"135\" y1=\"25\" x2=\"135\" y2=\"205\" opacity=\".55\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"205\" opacity=\".55\"/><line x1=\"225\" y1=\"25\" x2=\"225\" y2=\"205\" opacity=\".55\"/><line x1=\"270\" y1=\"25\" x2=\"270\" y2=\"205\" opacity=\".55\"/><line x1=\"315\" y1=\"25\" x2=\"315\" y2=\"205\" opacity=\".55\"/><line x1=\"45\" y1=\"25\" x2=\"315\" y2=\"25\" opacity=\".55\"/><line x1=\"45\" y1=\"55\" x2=\"315\" y2=\"55\" opacity=\".55\"/><line x1=\"45\" y1=\"85\" x2=\"315\" y2=\"85\" opacity=\".55\"/><line x1=\"45\" y1=\"115\" x2=\"315\" y2=\"115\" opacity=\".55\"/><line x1=\"45\" y1=\"145\" x2=\"315\" y2=\"145\" opacity=\".55\"/><line x1=\"45\" y1=\"175\" x2=\"315\" y2=\"175\" opacity=\".55\"/><line x1=\"45\" y1=\"205\" x2=\"315\" y2=\"205\" opacity=\".55\"/>\n      <rect x=\"45\" y=\"25\" width=\"270\" height=\"180\" opacity=\".9\"/>\n      <text x=\"45\" y=\"218\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">A</text>\n      <text x=\"315\" y=\"18\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">B</text></svg>","svgAlt":"一个6×6棋盘，左下角标A，右上角标B。"},
{"c":"图形推理","q":"把一个圆等分成7份，每份的圆心角是多少度？","a":"51.4°。360°/7=51.4°。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><circle cx=\"180\" cy=\"110\" r=\"80\"/><line x1=\"180\" y1=\"110\" x2=\"180\" y2=\"30\"/><line x1=\"180\" y1=\"110\" x2=\"243\" y2=\"60\"/><line x1=\"180\" y1=\"110\" x2=\"258\" y2=\"128\"/><line x1=\"180\" y1=\"110\" x2=\"215\" y2=\"182\"/><line x1=\"180\" y1=\"110\" x2=\"145\" y2=\"182\"/><line x1=\"180\" y1=\"110\" x2=\"102\" y2=\"128\"/><line x1=\"180\" y1=\"110\" x2=\"117\" y2=\"60\"/></svg>","svgAlt":"一个圆被7条半径等分成7个扇形。"},
{"c":"图形推理","q":"观察图形规律：正方形、圆形、三角形、正方形、圆形、三角形...第10个是什么？","a":"正方形。周期为3，10÷3=3余1，第10个是周期第一个：正方形。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 230\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><rect x=\"60\" y=\"25\" width=\"40\" height=\"40\" rx=\"4\"/><circle cx=\"180\" cy=\"45\" r=\"20\"/><polygon points=\"280,23 258,63 302,63\"/><rect x=\"60\" y=\"90\" width=\"40\" height=\"40\" rx=\"4\"/><circle cx=\"180\" cy=\"110\" r=\"20\"/><polygon points=\"280,88 258,128 302,128\"/><rect x=\"60\" y=\"155\" width=\"40\" height=\"40\" rx=\"4\"/><circle cx=\"180\" cy=\"175\" r=\"20\"/><polygon points=\"280,153 258,193 302,193\"/></svg>","svgAlt":"正方形、圆形、三角形按顺序重复排列的三行图形。"},
{"c":"图形推理","q":"3个三角形最多能把平面分成多少个区域？","a":"20个。第一个三角形把平面分成2块；第二个三角形最多增加6块；第三个三角形最多增加12块，共20块。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\">\n      <polygon points=\"180,25 70,185 290,185\"/>\n      <polygon points=\"150,48 45,180 255,180\"/>\n      <polygon points=\"210,48 105,180 315,180\" stroke-dasharray=\"7 5\"/>\n      <text x=\"180\" y=\"205\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"13\" text-anchor=\"middle\">三个三角形</text></svg>","svgAlt":"三个相互交叠的三角形，用于说明平面分割。"},
{"c":"图形推理","q":"下列图形中哪个是中心对称但不是轴对称的？A.平行四边形 B.正六边形 C.圆形 D.等边三角形","a":"A.平行四边形。旋转180°重合但无对称轴。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\">\n      <polygon points=\"20,40 100,40 80,95 0,95\"/><text x=\"50\" y=\"115\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">A</text>\n      <polygon points=\"240,26 276,47 276,89 240,110 204,89 204,47\"/><text x=\"240\" y=\"118\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">B</text>\n      <circle cx=\"60\" cy=\"165\" r=\"30\"/><text x=\"60\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">C</text>\n      <polygon points=\"240,140 286,198 194,198\"/><text x=\"240\" y=\"214\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">D</text></svg>","svgAlt":"四个候选图形：A平行四边形、B正六边形、C圆形、D等边三角形。"},
{"c":"图形推理","q":"一个正6边形，从一个顶点出发可以画几条对角线？","a":"3条。除自身和两个相邻顶点外，其余6-3=3个顶点都可连成对角线。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"180,35 245,73 245,148 180,185 115,148 115,73\"/><line x1=\"180\" y1=\"35\" x2=\"245\" y2=\"148\" stroke-dasharray=\"5 4\" opacity=\".55\"/><line x1=\"180\" y1=\"35\" x2=\"180\" y2=\"185\" stroke-dasharray=\"5 4\" opacity=\".55\"/><line x1=\"180\" y1=\"35\" x2=\"115\" y2=\"148\" stroke-dasharray=\"5 4\" opacity=\".55\"/><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">从一个顶点连对角线</text></svg>","svgAlt":"一个正六边形，从顶部顶点向三个非相邻顶点作对角线。"},
{"c":"图形推理","q":"两个全等的等腰直角三角形可以拼成什么图形？列举至少3种。","a":"正方形、更大的等腰直角三角形、平行四边形。斜边相对拼正方形；直角边相对拼大三角形；错位拼平行四边形。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"55,180 135,180 55,80\"/><polygon points=\"185,180 265,180 265,80\"/><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">两个全等三角形</text></svg>","svgAlt":"两个全等的等腰直角三角形，直角边相等。"},
{"c":"图形推理","q":"在一个正方形中画两条对角线，最多能把正方形分成多少个区域？","a":"4个。两条对角线在中心相交，把正方形分成4个三角形区域。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><rect x=\"100\" y=\"40\" width=\"160\" height=\"160\"/><line x1=\"100\" y1=\"40\" x2=\"260\" y2=\"200\"/><line x1=\"260\" y1=\"40\" x2=\"100\" y2=\"200\"/><text x=\"180\" y=\"216\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">两条对角线</text></svg>","svgAlt":"一个正方形，画有两条对角线。"},
{"c":"图形推理","q":"一个非正方形的长方形有多少条对称轴？","a":"2条。非正方形长方形只有横向和纵向两条对称轴。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><rect x=\"100\" y=\"60\" width=\"160\" height=\"120\"/><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">长方形（非正方形）</text></svg>","svgAlt":"一个长大于宽的长方形。"},
{"c":"图形推理","q":"一个三角形的底边扩大到原来的2倍，高缩小到原来的一半，面积怎样变化？","a":"不变。三角形面积=底×高÷2；底变2倍、高变一半，乘积不变。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"40,180 120,180 80,100\"/><line x1=\"80\" y1=\"100\" x2=\"80\" y2=\"180\" stroke-dasharray=\"4 3\" opacity=\".55\"/><polygon points=\"170,180 330,180 250,140\"/><line x1=\"250\" y1=\"140\" x2=\"250\" y2=\"180\" stroke-dasharray=\"4 3\" opacity=\".55\"/><text x=\"80\" y=\"205\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"12\" text-anchor=\"middle\">底 b，高 h</text><text x=\"250\" y=\"205\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"12\" text-anchor=\"middle\">底 2b，高 h/2</text></svg>","svgAlt":"左右两个三角形：左边底为b、高为h；右边底为2b、高为h/2。"},
{"c":"图形推理","q":"一个正八边形的一个内角是多少度？","a":"135°。正八边形内角和(8-2)×180°=1080°，每个内角1080°/8=135°。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"180,30 235,53 258,108 235,163 180,186 125,163 102,108 125,53\"/><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">正八边形</text></svg>","svgAlt":"一个正八边形，标出其中一个内角。"},
{"c":"图形推理","q":"一个三角形三个内角的度数比为4:3:4，最大角约多少度？","a":"约65.5°。总份数11，最大角占4份，180×4/11≈65.5°。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\">\n      <polygon points=\"38,185 322,185 180,35\"/>\n      <text x=\"180\" y=\"26\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">3x</text>\n      <text x=\"62\" y=\"180\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">4x</text>\n      <text x=\"298\" y=\"180\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">4x</text></svg>","svgAlt":"三角形三个内角分别标为4x、3x、4x。"},
{"c":"图形推理","q":"在5×5的方格中，有多少个长方形（含正方形）？","a":"225个。选两横边C(6,2)×选两竖边C(6,2)=225。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 230\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\">\n      <line x1=\"40\" y1=\"20\" x2=\"40\" y2=\"200\" opacity=\".55\"/><line x1=\"96\" y1=\"20\" x2=\"96\" y2=\"200\" opacity=\".55\"/><line x1=\"152\" y1=\"20\" x2=\"152\" y2=\"200\" opacity=\".55\"/><line x1=\"208\" y1=\"20\" x2=\"208\" y2=\"200\" opacity=\".55\"/><line x1=\"264\" y1=\"20\" x2=\"264\" y2=\"200\" opacity=\".55\"/><line x1=\"320\" y1=\"20\" x2=\"320\" y2=\"200\" opacity=\".55\"/><line x1=\"40\" y1=\"20\" x2=\"320\" y2=\"20\" opacity=\".55\"/><line x1=\"40\" y1=\"56\" x2=\"320\" y2=\"56\" opacity=\".55\"/><line x1=\"40\" y1=\"92\" x2=\"320\" y2=\"92\" opacity=\".55\"/><line x1=\"40\" y1=\"128\" x2=\"320\" y2=\"128\" opacity=\".55\"/><line x1=\"40\" y1=\"164\" x2=\"320\" y2=\"164\" opacity=\".55\"/><line x1=\"40\" y1=\"200\" x2=\"320\" y2=\"200\" opacity=\".55\"/>\n      <rect x=\"40\" y=\"20\" width=\"280\" height=\"180\" opacity=\".9\"/>\n      <text x=\"180\" y=\"216\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">5×5 方格</text></svg>","svgAlt":"一个5×5的方格图，共25个小方格。"},
{"c":"图形推理","q":"一个半径为6的圆中，圆心角为60°的扇形面积是多少？","a":"6π（约18.85）。扇形面积=60/360×π×6²=6π，约18.85。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><circle cx=\"180\" cy=\"110\" r=\"80\"/><path d=\"M180,110 L180.0,30.0 A80,80 0 0 1 249.3,70.0 Z\" fill=\"currentColor\" fill-opacity=\".07\" /><text x=\"180\" y=\"96\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">60°</text><text x=\"265\" y=\"130\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"14\" text-anchor=\"middle\">r=6</text><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">60°扇形</text></svg>","svgAlt":"半径为6的圆中，一个圆心角为60°的扇形。"},
{"c":"图形推理","q":"一个正方形沿一条直线切去一个角，剩下的图形最多有多少个角？","a":"5个。沿一条直线切去一个角，原来的一个角变成两个角，边数由4变5。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"140,40 260,40 260,200 100,200 100,80\"/><line x1=\"100\" y1=\"80\" x2=\"140\" y2=\"40\" stroke-dasharray=\"5 4\" opacity=\".55\"/><text x=\"180\" y=\"216\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">切去一个角</text></svg>","svgAlt":"一个正方形，左上角被一条直线切去，剩余五边形。"},
{"c":"图形推理","q":"一个正九边形从一个顶点连对角线，可以分成多少个三角形？","a":"7个。从一个顶点连对角线，可把n边形分成n-2个三角形，9-2=7。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"180,30 230,48 257,94 248,147 207,181 153,181 112,147 103,94 130,48\"/><line x1=\"180\" y1=\"30\" x2=\"257\" y2=\"94\" stroke-dasharray=\"5 4\" opacity=\".55\"/><line x1=\"180\" y1=\"30\" x2=\"248\" y2=\"147\" stroke-dasharray=\"5 4\" opacity=\".55\"/><line x1=\"180\" y1=\"30\" x2=\"207\" y2=\"181\" stroke-dasharray=\"5 4\" opacity=\".55\"/><line x1=\"180\" y1=\"30\" x2=\"153\" y2=\"181\" stroke-dasharray=\"5 4\" opacity=\".55\"/><line x1=\"180\" y1=\"30\" x2=\"112\" y2=\"147\" stroke-dasharray=\"5 4\" opacity=\".55\"/><line x1=\"180\" y1=\"30\" x2=\"103\" y2=\"94\" stroke-dasharray=\"5 4\" opacity=\".55\"/><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">从一个顶点连对角线</text></svg>","svgAlt":"一个正九边形，从顶部顶点向其余非相邻顶点作对角线。"},
{"c":"图形推理","q":"一个直角三角形中，一个锐角是另一个锐角的2倍，较小的锐角是多少度？","a":"30°。两个锐角之和为90°，设较小角为x，则x+2x=90°，x=30°。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"80,180 280,180 280,80\"/><path d=\"M270,180 L270,170 L280,170\" opacity=\".7\"/><text x=\"110\" y=\"168\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">x</text><text x=\"252\" y=\"140\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">2x</text><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">直角三角形</text></svg>","svgAlt":"一个直角三角形，两个锐角分别标为x和2x。"},
{"c":"图形推理","q":"一个半径为4的圆中，圆心角为90°的弧长是多少？","a":"2π（约6.28）。弧长=90/360×2π×4=2π，约6.28。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><circle cx=\"180\" cy=\"110\" r=\"80\"/><path d=\"M180,110 L180.0,30.0 A80,80 0 0 1 260.0,110.0 Z\" fill=\"currentColor\" fill-opacity=\".07\" /><text x=\"180\" y=\"96\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">90°</text><text x=\"265\" y=\"130\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"14\" text-anchor=\"middle\">r=4</text><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">弧长？</text></svg>","svgAlt":"半径为4的圆中，一个90°的圆心角所对的弧。"},
{"c":"图形推理","q":"从一个正方形纸片的四个角各剪去一个小正方形，剩下的图形有多少条边？","a":"12条。四个角各剪去一个小正方形，每个角增加2条边，4+4×2=12。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"110,40 250,40 250,70 280,70 280,170 250,170 250,200 110,200 110,170 80,170 80,70 110,70\"/><text x=\"180\" y=\"216\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"13\" text-anchor=\"middle\">四个角各剪去一个小正方形</text></svg>","svgAlt":"一个正方形，四个角各剪去一个小正方形，剩下十二边形。"},
{"c":"图形推理","q":"一个正三角形绕它的中心至少旋转多少度，才能与原来的图形重合？","a":"120°。正三角形有三重旋转对称，360°/3=120°。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"180,35 80,180 280,180\"/><circle cx=\"180\" cy=\"132\" r=\"4\" fill=\"currentColor\" stroke=\"none\"/>\n      <path d=\"M210,105 A38,38 0 0 1 210,159\" stroke-dasharray=\"5 4\"/><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">绕中心旋转</text></svg>","svgAlt":"一个正三角形，中心有一个旋转箭头。"},
{"c":"图形推理","q":"一个等腰三角形的一个底角是40°，它的顶角是多少度？","a":"100°。等腰三角形两底角相等，顶角=180°-40°-40°=100°。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"180,40 90,180 270,180\"/><text x=\"115\" y=\"168\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">40°</text><text x=\"245\" y=\"168\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">40°</text><text x=\"180\" y=\"72\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"18\" text-anchor=\"middle\">?</text><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">等腰三角形</text></svg>","svgAlt":"一个等腰三角形，两个底角标为40°，顶角标问号。"},
{"c":"图形推理","q":"同一个圆中，100°圆心角所对的弧长是50°圆心角所对弧长的几倍？","a":"2倍。同圆中弧长与圆心角成正比，100°/50°=2。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><circle cx=\"110\" cy=\"110\" r=\"55\"/><path d=\"M110,110 L110.0,55.0 A55,55 0 0 1 164.2,119.6 Z\" fill=\"currentColor\" fill-opacity=\".07\" /><text x=\"110\" y=\"96\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"13\" text-anchor=\"middle\">100°</text><text x=\"110\" y=\"190\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"13\" text-anchor=\"middle\">100°扇形</text>\n      <circle cx=\"250\" cy=\"110\" r=\"55\"/><path d=\"M250,110 L250.0,55.0 A55,55 0 0 1 292.1,74.6 Z\" fill=\"currentColor\" fill-opacity=\".07\" /><text x=\"250\" y=\"96\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"13\" text-anchor=\"middle\">50°</text><text x=\"250\" y=\"190\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"13\" text-anchor=\"middle\">50°扇形</text>\n      <text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"13\" text-anchor=\"middle\">同圆半径</text></svg>","svgAlt":"同半径的两个扇形，圆心角分别为100°和50°。"},
{"c":"图形推理","q":"一个正方形有多少条对称轴？","a":"4条。两条中线和两条对角线都是对称轴。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><rect x=\"120\" y=\"50\" width=\"120\" height=\"120\"/><circle cx=\"180\" cy=\"110\" r=\"4\" fill=\"currentColor\" stroke=\"none\"/>\n      <path d=\"M215,80 A42,42 0 0 1 215,140\" stroke-dasharray=\"5 4\"/><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">绕中心旋转</text></svg>","svgAlt":"一个正方形，中心有一个旋转箭头。"},
{"c":"图形推理","q":"一个圆被半径分成6个面积相等的扇形，每个扇形的面积是圆面积的几分之几？","a":"1/6。6个相等扇形把圆面积平均分成6份。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><circle cx=\"180\" cy=\"110\" r=\"78\"/><line x1=\"180\" y1=\"110\" x2=\"180\" y2=\"32\"/><line x1=\"180\" y1=\"110\" x2=\"248\" y2=\"71\"/><line x1=\"180\" y1=\"110\" x2=\"248\" y2=\"149\"/><line x1=\"180\" y1=\"110\" x2=\"180\" y2=\"188\"/><line x1=\"180\" y1=\"110\" x2=\"112\" y2=\"149\"/><line x1=\"180\" y1=\"110\" x2=\"112\" y2=\"71\"/><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">6等份</text></svg>","svgAlt":"一个圆被6条半径分成6个相等的扇形。"},
{"c":"图形推理","q":"一个正五边形的内角和是多少度？","a":"540°。(5-2)×180°=540°。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"180,30 258,87 228,178 132,178 102,87\"/><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">正五边形</text></svg>","svgAlt":"一个正五边形。"},
{"c":"图形推理","q":"一个圆中，两条半径的夹角为120°，它们与所夹的弧围成的扇形占圆面积的几分之几？","a":"1/3。120°/360°=1/3。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><circle cx=\"180\" cy=\"110\" r=\"80\"/><path d=\"M180,110 L180.0,30.0 A80,80 0 0 1 249.3,150.0 Z\" fill=\"currentColor\" fill-opacity=\".07\" /><text x=\"180\" y=\"96\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">120°</text><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">120°扇形</text></svg>","svgAlt":"一个圆心角为120°的扇形。"},
{"c":"图形推理","q":"一个正六边形从中心连接各顶点，可以分成多少个等边三角形？","a":"6个。中心角360°/6=60°，六条半径相等，所以分成6个等边三角形。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><polygon points=\"180,32 248,71 248,149 180,188 112,149 112,71\"/><circle cx=\"180\" cy=\"110\" r=\"4\" fill=\"currentColor\" stroke=\"none\"/><line x1=\"180\" y1=\"110\" x2=\"180\" y2=\"32\"/><line x1=\"180\" y1=\"110\" x2=\"248\" y2=\"71\"/><line x1=\"180\" y1=\"110\" x2=\"248\" y2=\"149\"/><line x1=\"180\" y1=\"110\" x2=\"180\" y2=\"188\"/><line x1=\"180\" y1=\"110\" x2=\"112\" y2=\"149\"/><line x1=\"180\" y1=\"110\" x2=\"112\" y2=\"71\"/><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">中心连各顶点</text></svg>","svgAlt":"一个正六边形，中心与六个顶点相连，分成六个三角形。"},
{"c":"图形推理","q":"一个圆的直径所对的圆周角是多少度？","a":"90°。直径所对的圆周角是直角。","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 220\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\"><circle cx=\"180\" cy=\"110\" r=\"80\"/><line x1=\"100\" y1=\"110\" x2=\"260\" y2=\"110\"/>\n      <polyline points=\"100,110 180,30 260,110\"/>\n      <text x=\"93\" y=\"125\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"13\" text-anchor=\"middle\">A</text><text x=\"267\" y=\"125\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"13\" text-anchor=\"middle\">B</text><text x=\"180\" y=\"21\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"13\" text-anchor=\"middle\">C</text>\n      <text x=\"180\" y=\"78\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"18\" text-anchor=\"middle\">?</text><text x=\"180\" y=\"210\" fill=\"currentColor\" stroke=\"none\" font-family=\"system-ui,-apple-system,Segoe UI,sans-serif\" font-size=\"15\" text-anchor=\"middle\">直径所对的圆周角</text></svg>","svgAlt":"以圆的直径为一边、顶点在圆周上的三角形，顶点处标有问号。"},
{"c":"空间想象","q":"正3棱柱有多少条棱？","a":"9条。上下底面各3条棱，侧面3条竖棱，共9条。"},
{"c":"空间想象","q":"正4棱锥有多少个面？","a":"5个。底面1个加4个侧面三角形，共5个面。"},
{"c":"空间想象","q":"一个圆柱体底面半径为r，高为2r。它的侧面积与底面积之比是多少？","a":"4:1。侧面积=2πr×2r=4πr²，底面积=πr²。比值为4。"},
{"c":"空间想象","q":"边长为5的正方体，所有棱长之和是多少？","a":"60。正方体有12条棱，每条棱长5，总长60。"},
{"c":"空间想象","q":"一个球体的体积公式是什么？表面积公式是什么？","a":"体积V=4/3πr³，表面积S=4πr²。其中r为球体半径。"},
{"c":"空间想象","q":"一个长方体长8厘米、宽5厘米、高4厘米，体积是多少？","a":"160立方厘米。体积=长×宽×高=8×5×4=160立方厘米。"},
{"c":"空间想象","q":"如果立方体的每条棱长变为原来的2倍，体积变为原来的多少倍？","a":"8倍。体积与棱长的立方成正比。2³=8倍。"},
{"c":"空间想象","q":"在空间中，到两个定点距离相等的点的轨迹是什么？","a":"一个平面（垂直平分面）。这是两点连线的垂直平分面。"},
{"c":"空间想象","q":"一个圆锥的侧面展开图是什么形状？","a":"扇形。圆锥侧面展开是一个扇形，扇形半径等于圆锥母线长，弧长等于底面周长。"},
{"c":"空间想象","q":"正8面体满足欧拉公式V-E+F=2。验证之。","a":"正8面体：V=6,E=12,F=8。V-E+F=6-12+8=2。"},
{"c":"空间想象","q":"一个正方体的体对角线互相垂直吗？","a":"不垂直。正方体有4条体对角线，两两之间夹角约为70.53°或109.47°，不垂直。"},
{"c":"空间想象","q":"在三维空间中，方程x²+y²+z²=1表示什么图形？","a":"球面。以原点为球心、半径为1的球面。"},
{"c":"空间想象","q":"把一个长方体沿对角线切一刀，截面最多是几边形？","a":"六边形。当切割面与长方体的6个面都相交时，截面是六边形。"},
{"c":"空间想象","q":"在空间中，方程z=x²+y²表示什么曲面？","a":"旋转抛物面。这是一个开口向上的抛物面，由抛物线z=r²绕z轴旋转得到。"},
{"c":"空间想象","q":"正四面体的重心到顶点的距离与到底面的距离之比是多少？","a":"3:1。正四面体的重心将高分为3:1，重心到顶点距离是高的3/4。"},
{"c":"空间想象","q":"一个球体内接正方体的边长与球半径的关系是什么？","a":"边长a=2r/√3。正方体的体对角线等于球的直径：a√3=2r，所以a=2r/√3。"},
{"c":"空间想象","q":"一个圆环绕其直径旋转一周形成什么图形？","a":"圆环体（环面/Torus）。就像一个甜甜圈的形状。"},
{"c":"空间想象","q":"在空间中，方程x²+y²=z²表示什么曲面？","a":"圆锥面。它是以z轴为轴、顶点在原点的双圆锥面；上下两个锥面在原点相接。"},
{"c":"空间想象","q":"一个圆锥的轴截面是什么形状？","a":"等腰三角形。过圆锥顶点和底面圆心的截面是等腰三角形。"},
{"c":"空间想象","q":"正六面体（正方体）的对称轴有多少条？","a":"13条。3条过对面中心（4次）、6条过对棱中点（2次）、4条体对角线（3次）。"},
{"c":"空间想象","q":"正5棱柱有多少条棱？","a":"15条。上下底面各5条棱，侧面5条竖棱，共15条。"},
{"c":"空间想象","q":"一个正方体棱长5厘米，表面积是多少？","a":"150平方厘米。每个面5×5=25，六个面共150平方厘米。"},
{"c":"空间想象","q":"一个正六棱柱有多少个面？","a":"8个。上下2个六边形底面，加6个侧面，共8个面。"},
{"c":"空间想象","q":"一个四棱锥有多少条棱？","a":"8条。底面4条，侧棱4条，共8条。"},
{"c":"图形推理","q":"下面是一个正方体的展开图，折成正方体后，与面A相对的是哪一个面？","a":"D。C是前面，A在左、D在右，左右相对；B和F上下相对，C和E前后相对。","svg":"<svg viewBox=\"0 0 360 300\" role=\"img\" aria-label=\"正方体展开图\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"120\" y=\"20\" width=\"60\" height=\"60\"/><rect x=\"60\" y=\"80\" width=\"60\" height=\"60\"/><rect x=\"120\" y=\"80\" width=\"60\" height=\"60\"/><rect x=\"180\" y=\"80\" width=\"60\" height=\"60\"/><rect x=\"240\" y=\"80\" width=\"60\" height=\"60\"/><rect x=\"120\" y=\"140\" width=\"60\" height=\"60\"/></g><g fill=\"currentColor\" font-size=\"22\" text-anchor=\"middle\"><text x=\"150\" y=\"56\">B</text><text x=\"90\" y=\"116\">A</text><text x=\"150\" y=\"116\">C</text><text x=\"210\" y=\"116\">D</text><text x=\"270\" y=\"116\">E</text><text x=\"150\" y=\"176\">F</text></g></svg>","svgAlt":"正方体展开图，上排B，中间A、C、D、E，下排F"},
{"c":"图形推理","q":"下面是一个无盖正方体纸盒的展开图，底面是A。与底面A相邻的面一共有多少个？","a":"4个。A在中间，上、下、左、右四个面都直接与它相邻；无盖只少一个顶面。","svg":"<svg viewBox=\"0 0 240 240\" role=\"img\" aria-label=\"无盖正方体展开图\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"60\" y=\"80\" width=\"60\" height=\"60\"/><rect x=\"0\" y=\"80\" width=\"60\" height=\"60\"/><rect x=\"120\" y=\"80\" width=\"60\" height=\"60\"/><rect x=\"60\" y=\"20\" width=\"60\" height=\"60\"/><rect x=\"60\" y=\"140\" width=\"60\" height=\"60\"/></g><g fill=\"currentColor\" font-size=\"20\" text-anchor=\"middle\"><text x=\"90\" y=\"116\">A</text><text x=\"30\" y=\"116\">B</text><text x=\"150\" y=\"116\">C</text><text x=\"90\" y=\"56\">D</text><text x=\"90\" y=\"176\">E</text></g></svg>","svgAlt":"无盖正方体展开图，A在中心，四周为B、C、D、E"},
{"c":"图形推理","q":"下面四个全等的正三角形能折成哪种立体图形？","a":"正四面体。四个正三角形正好是正四面体的四个面，折叠后每个顶点处有三个面。","svg":"<svg viewBox=\"0 0 300 220\" role=\"img\" aria-label=\"四个正三角形展开图\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polygon points=\"150,30 110,100 190,100\"/><polygon points=\"110,100 70,170 150,170\"/><polygon points=\"190,100 150,170 230,170\"/><polygon points=\"150,170 110,240 190,240\"/></g><g fill=\"currentColor\" font-size=\"16\" text-anchor=\"middle\"><text x=\"150\" y=\"76\">1</text><text x=\"110\" y=\"145\">2</text><text x=\"190\" y=\"145\">3</text><text x=\"150\" y=\"215\">4</text></g></svg>","svgAlt":"四个正三角形组成的展开图"},
{"c":"图形推理","q":"一个3×3方格去掉正中心的一格，剩下图形的外周长是多少？每小格边长为1。","a":"12。去掉中心格不影响最外圈边界，外周长仍是3×4=12；中心洞的边不算外周长。","svg":"<svg viewBox=\"0 0 240 240\" role=\"img\" aria-label=\"3×3方格去掉中心\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"20\" y=\"20\" width=\"60\" height=\"60\"/><rect x=\"80\" y=\"20\" width=\"60\" height=\"60\"/><rect x=\"140\" y=\"20\" width=\"60\" height=\"60\"/><rect x=\"20\" y=\"80\" width=\"60\" height=\"60\"/><rect x=\"80\" y=\"80\" width=\"60\" height=\"60\" stroke-dasharray=\"4 4\"/><rect x=\"140\" y=\"80\" width=\"60\" height=\"60\"/><rect x=\"20\" y=\"140\" width=\"60\" height=\"60\"/><rect x=\"80\" y=\"140\" width=\"60\" height=\"60\"/><rect x=\"140\" y=\"140\" width=\"60\" height=\"60\"/></g><text x=\"110\" y=\"116\" fill=\"currentColor\" font-size=\"14\" text-anchor=\"middle\">空</text></svg>","svgAlt":"3×3方格，中心格为空"},
{"c":"图形推理","q":"一个正六边形沿一条连接相对顶点的对角线剪开，得到两个什么图形？","a":"两个等腰梯形。正六边形的对边平行，沿相对顶点连线剪开，每半边都有三条边和一组平行底边。","svg":"<svg viewBox=\"0 0 300 240\" role=\"img\" aria-label=\"正六边形对角线\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polygon points=\"150,30 240,80 240,160 150,210 60,160 60,80\"/><line x1=\"150\" y1=\"30\" x2=\"150\" y2=\"210\"/></g></svg>","svgAlt":"正六边形及一条连接相对顶点的对角线"},
{"c":"图形推理","q":"一个正方形沿一条对角线剪开，得到两个什么三角形？","a":"两个等腰直角三角形。正方形四边相等，对角线把每个直角分成两个45度角，所以两个三角形都是等腰直角三角形。","svg":"<svg viewBox=\"0 0 240 240\" role=\"img\" aria-label=\"正方形及对角线\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"30\" y=\"30\" width=\"180\" height=\"180\"/><line x1=\"30\" y1=\"30\" x2=\"210\" y2=\"210\"/></g></svg>","svgAlt":"正方形内画一条对角线"},
{"c":"空间想象","q":"一个圆柱沿轴截面切开，截面是什么形状？","a":"长方形。轴截面经过圆柱的两条相对母线，宽等于直径、高等于圆柱的高，所以是长方形。","svg":"<svg viewBox=\"0 0 320 240\" role=\"img\" aria-label=\"圆柱轴截面\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><ellipse cx=\"160\" cy=\"50\" rx=\"80\" ry=\"25\"/><ellipse cx=\"160\" cy=\"190\" rx=\"80\" ry=\"25\"/><line x1=\"80\" y1=\"50\" x2=\"80\" y2=\"190\"/><line x1=\"240\" y1=\"50\" x2=\"240\" y2=\"190\"/><line x1=\"160\" y1=\"50\" x2=\"160\" y2=\"190\" stroke-dasharray=\"4 4\"/></g><text x=\"160\" y=\"225\" fill=\"currentColor\" font-size=\"14\" text-anchor=\"middle\">轴截面</text></svg>","svgAlt":"圆柱及经过轴线的截面"},
{"c":"空间想象","q":"一个圆锥的侧面展开图是半径为6、圆心角为120°的扇形，这个圆锥的底面半径是多少？","a":"2。扇形弧长为6×（120°/360°）×2π=4π，也就是底面圆周；由2πr=4π得r=2。","svg":"<svg viewBox=\"0 0 300 260\" role=\"img\" aria-label=\"圆锥侧面展开扇形\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M150 130 L150 30 A100 100 0 0 1 236.6 180 Z\"/><line x1=\"150\" y1=\"130\" x2=\"150\" y2=\"30\"/><line x1=\"150\" y1=\"130\" x2=\"236.6\" y2=\"180\"/></g><text x=\"120\" y=\"78\" fill=\"currentColor\" font-size=\"14\">6</text><text x=\"200\" y=\"160\" fill=\"currentColor\" font-size=\"14\">120°</text></svg>","svgAlt":"半径为6、圆心角120度的扇形"},
{"c":"空间想象","q":"一个几何体由若干相同小正方体搭成。它的俯视图是2×2的正方形，主视图和左视图都是2层。最少需要多少个小正方体？","a":"4个。2×2底座至少4个；让其中一个位置叠2层，就能同时满足主视图和左视图都是2层，所以最少4个。","svg":"<svg viewBox=\"0 0 300 180\" role=\"img\" aria-label=\"三视图\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"20\" y=\"30\" width=\"60\" height=\"60\"/><rect x=\"80\" y=\"30\" width=\"60\" height=\"60\"/><rect x=\"20\" y=\"90\" width=\"60\" height=\"60\"/><rect x=\"80\" y=\"90\" width=\"60\" height=\"60\"/><rect x=\"140\" y=\"30\" width=\"60\" height=\"60\"/><rect x=\"200\" y=\"30\" width=\"60\" height=\"60\"/><rect x=\"140\" y=\"90\" width=\"60\" height=\"60\"/><rect x=\"200\" y=\"90\" width=\"60\" height=\"60\"/><rect x=\"260\" y=\"30\" width=\"40\" height=\"40\"/><rect x=\"280\" y=\"50\" width=\"20\" height=\"20\"/></g><g fill=\"currentColor\" font-size=\"13\" text-anchor=\"middle\"><text x=\"80\" y=\"170\">俯视图</text><text x=\"200\" y=\"170\">主视图/左视图</text></g></svg>","svgAlt":"2×2俯视图与两层主视图示意"},
{"c":"空间想象","q":"一个正方体被一个平面切去一个角，剩下的几何体有多少个面？","a":"7个。切去一个角只新增一个三角形截面，原来的六个面都还在，所以是7个面。","svg":"<svg viewBox=\"0 0 300 260\" role=\"img\" aria-label=\"正方体切角\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polygon points=\"60,90 180,40 250,75 250,190 130,240 60,205\"/><polygon points=\"60,90 130,240 60,205\"/><polygon points=\"180,40 250,75 130,240\"/><polygon points=\"180,40 130,240 60,90\"/><polygon points=\"180,40 210,60 220,125 130,240\"/></g></svg>","svgAlt":"正方体切去一个角，新增三角形截面"},
{"c":"逻辑推理","q":"甲、乙、丙三人分别来自北京、上海、广州。已知甲不来自北京，乙来自上海，丙不来自广州。三人分别来自哪里？","a":"甲广州，乙上海，丙北京。乙已占上海，甲不能北京，只能广州；剩下丙就是北京。"},
{"c":"逻辑推理","q":"甲、乙、丙、丁四人排队。已知甲在乙前面，丙在丁前面，乙在丁后面。谁一定排在最后？","a":"乙。丙在丁前，丁又在乙前，所以乙排在丁后面；甲在乙前，因此乙最后。"},
{"c":"逻辑推理","q":"有两扇门，一扇通宝库，一扇通陷阱；两个守卫一个只说真话，一个只说假话。只能问一个守卫一个问题，应该怎么问？","a":"问另一守卫，走相反门。无论问到谁，他都会指向陷阱门，所以选相反那扇。"},
{"c":"逻辑推理","q":"三个开关在门外，三盏灯在门内，只能进门一次。怎样判断三个开关分别控制哪盏灯？","a":"用灯泡温度判断。先开一个开关几分钟后关掉，再开第二个，进门后亮的是第二个，温热的是第一个，冷的是第三个。"},
{"c":"逻辑推理","q":"5枚外观相同的硬币中有一枚较轻，用天平最少称几次一定能找出？","a":"2次。先分2、2、1称：两边各2枚，若平衡则剩下那枚轻；若不平衡，再称轻的一边两枚。"},
{"c":"逻辑推理","q":"8个外观相同的小球中有一个较重，用天平最少称几次一定能找出？","a":"2次。先分3、3、2称：若3对3平衡，重球在剩下2个中；若不平衡，在较重3个中，再称其中2个。"},
{"c":"逻辑推理","q":"三个盒子分别标着“苹果”“橘子”“混合”，但三个标签都贴错了。只从一个盒子拿一个水果，应该从哪个盒子拿？","a":"标“混合”的盒子。因为标签全错，这个盒子不可能混合，只装一种水果；拿出苹果就确定它，另外两盒随之确定。"},
{"c":"逻辑推理","q":"甲、乙、丙、丁四个孩子比身高。已知甲比乙高，丙比丁矮，乙比丁高。谁最高？","a":"甲。乙比丁高，丁又比丙高，所以甲比乙、乙比丁、丁比丙都高，甲最高。"}
  ]
};
